import type { BankQuestion } from "@/lib/bank";

/** Corporate Finance & Financial Markets (Management & Commerce): 714 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-finance-1","question":"₹10,000 is invested at 8% per annum compounded annually. What is it worth after 3 years?","options":["₹12,400.00","₹12,653.19","₹12,597.12","₹11,664.00"],"answer":2,"explanation":"FV = 10,000 × 1.08³ = 10,000 × 1.259712 = ₹12,597.12. ₹12,400 is simple interest; ₹12,653.19 assumes half-yearly compounding.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-2","question":"What is the present value of ₹50,000 receivable at the end of 2 years if the discount rate is 10% per annum?","options":["₹41,322.31","₹40,000.00","₹41,666.67","₹45,454.55"],"answer":0,"explanation":"PV = 50,000 / 1.1² = 50,000 / 1.21 = ₹41,322.31. Dividing by 1.2 ignores compounding; dividing by 1.1 discounts only one year.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-3","question":"A preference-like security pays ₹6,000 at the end of every year forever. If the required return is 12%, what is its value today?","options":["₹72,000","₹44,642.86","₹56,000","₹50,000"],"answer":3,"explanation":"PV of a perpetuity = C / r = 6,000 / 0.12 = ₹50,000. ₹56,000 would be a perpetuity due (first payment today); dividing 50,000 by 1.12 again double-counts the one-year wait.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-4","question":"A credit line charges 12% per annum compounded monthly. What is its effective annual rate (EAR)?","options":["12.00%","12.68%","12.36%","12.75%"],"answer":1,"explanation":"EAR = (1 + 0.12/12)¹² − 1 = 1.01¹² − 1 = 12.68%. 12.36% is half-yearly compounding and 12.75% is continuous compounding.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-5","question":"What is the present value of ₹20,000 received at the end of each year for 5 years at a discount rate of 10%?","options":["₹83,397.31","₹1,00,000.00","₹75,815.74","₹62,092.13"],"answer":2,"explanation":"PV = 20,000 × [1 − 1.1⁻⁵]/0.10 = 20,000 × 3.79079 = ₹75,815.74. Multiplying by 1.1 (₹83,397.31) values an annuity due; discounting the ₹1,00,000 total as one lump sum at year 5 is wrong.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-6","question":"₹5,000 is deposited at the end of every year for 10 years at 8% compounded annually. What is the accumulated amount just after the last deposit?","options":["₹72,432.81","₹78,227.44","₹1,07,946.25","₹62,437.79"],"answer":0,"explanation":"FV of an ordinary annuity = 5,000 × [(1.08¹⁰ − 1)/0.08] = 5,000 × 14.48656 = ₹72,432.81. ₹78,227.44 would be an annuity due; compounding ₹50,000 for the full 10 years ignores that later deposits earn for fewer years.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-7","question":"A share is expected to pay a dividend of ₹4 next year, growing at 5% per year forever. Investors require 13%. What is the share worth today?","options":["₹52.50","₹50.00","₹30.77","₹22.22"],"answer":1,"explanation":"Gordon growth: P₀ = D₁/(r − g) = 4/(0.13 − 0.05) = ₹50. ₹52.50 wrongly grows the already-next-year dividend once more (4 × 1.05/0.08).","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-8","question":"Using the Rule of 72, roughly how many years does money take to double at 9% per annum compounded annually?","options":["11.1 years","6 years","7.2 years","8 years"],"answer":3,"explanation":"Rule of 72: years ≈ 72 / 9 = 8. The exact figure is ln 2 / ln 1.09 ≈ 8.04 years.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-9","question":"A ₹10,00,000 loan at 12% per annum is to be repaid in equal monthly instalments over 5 years (monthly reducing balance). What is the EMI (nearest rupee)?","options":["₹23,117","₹26,667","₹22,244","₹16,667"],"answer":2,"explanation":"r = 1% per month, n = 60. EMI = P·r(1+r)ⁿ/[(1+r)ⁿ − 1] = 10,00,000 × 0.01 × 1.01⁶⁰/(1.01⁶⁰ − 1) ≈ ₹22,244.45. ₹26,667 is a flat-rate EMI (interest on the full principal for 5 years); ₹23,117 is an annual EMI divided by 12.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-10","question":"For the same ₹10,00,000, 12%, 60-month loan (EMI ≈ ₹22,244.45), what principal is still outstanding immediately after the 12th EMI is paid (nearest hundred rupees)?","options":["₹7,33,100","₹8,44,700","₹8,00,000","₹8,53,100"],"answer":1,"explanation":"Outstanding balance = PV of the remaining 48 EMIs at 1% = 22,244.45 × [1 − 1.01⁻⁴⁸]/0.01 ≈ ₹8,44,709.76. Subtracting all 12 EMIs from the principal ignores that most of each early EMI is interest; ₹8,00,000 assumes equal principal repayment.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-11","question":"An investment pays ₹30,000 a year for 4 years, with the first payment at the end of year 4. At 10%, what is its present value?","options":["₹71,447.00","₹64,951.82","₹95,095.96","₹78,591.71"],"answer":0,"explanation":"Value the 4-payment annuity one period before its first payment (end of year 3): 30,000 × 3.16987 = ₹95,095.96. Discount 3 years: ÷ 1.1³ = ₹71,447.00. Discounting 4 years is the common off-by-one error.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-12","question":"A lottery winner may take ₹1,00,000 today or ₹12,000 at the end of every year forever. At an 11% opportunity cost, what should she do?","options":["Take ₹1,00,000 today; it is worth about ₹8,000 more","Indifferent; both are worth ₹1,00,000","Take the perpetuity; it is worth about ₹21,091 more","Take the perpetuity; it is worth about ₹9,091 more"],"answer":3,"explanation":"PV of perpetuity = 12,000/0.11 = ₹1,09,090.91 > ₹1,00,000, so the perpetuity wins by about ₹9,091. ₹21,091 wrongly treats it as a perpetuity due.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-13","question":"Which deposit gives the highest effective annual yield? A: 10% compounded quarterly; B: 10.3% compounded annually; C: 9.9% compounded monthly.","options":["B","A","C","All three are equal"],"answer":1,"explanation":"EAR(A) = 1.025⁴ − 1 = 10.381%; EAR(B) = 10.300%; EAR(C) = (1 + 0.099/12)¹² − 1 = 10.362%. A is highest, though only marginally above C.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-14","question":"An employee wants ₹50,00,000 at the end of 20 years. She will invest a fixed amount at the end of every year earning 9% compounded annually. What is the annual investment (nearest rupee)?","options":["₹89,663","₹2,50,000","₹97,732","₹1,08,652"],"answer":2,"explanation":"Sinking-fund payment = FV × r / [(1+r)ⁿ − 1] = 50,00,000 × 0.09 / (1.09²⁰ − 1) = ₹97,732.38. ₹89,663 is the beginning-of-year (annuity-due) payment; ₹2,50,000 ignores interest, and ₹1,08,652 uses only 19 compounding periods.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-15","question":"A contract pays ₹10,000 at the end of year 1, and each later payment grows by 4%, for 10 payments in total. At 10%, what is its present value?","options":["₹1,66,666.67","₹61,445.67","₹74,412.30","₹71,550.29"],"answer":3,"explanation":"Growing annuity: PV = C/(r − g) × [1 − ((1+g)/(1+r))ⁿ] = 10,000/0.06 × [1 − (1.04/1.10)¹⁰] = ₹71,550.29. ₹1,66,667 treats it as a growing perpetuity; ₹61,445.67 ignores growth.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-16","question":"₹1,00,000 is invested at 8% per annum compounded continuously for 5 years. What is the maturity value?","options":["₹1,49,182.47","₹1,46,932.81","₹1,40,000.00","₹1,48,984.57"],"answer":0,"explanation":"FV = P·e^(rt) = 1,00,000 × e^0.40 = ₹1,49,182.47. Annual compounding gives ₹1,46,932.81 and monthly gives ₹1,48,984.57; continuous is always the highest.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-17","question":"A lender wants an effective annual return of exactly 12%. What nominal annual rate, compounded monthly, should it quote?","options":["12.00%","11.39%","12.68%","11.49%"],"answer":1,"explanation":"(1 + i/12)¹² = 1.12 → i = 12 × (1.12^(1/12) − 1) = 11.387%. 12.68% runs the conversion the wrong way; 11.49% is the quarterly-compounding equivalent.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-18","question":"A perpetuity of ₹5,000 a year makes its first payment at the end of year 5. At 10%, what is it worth today?","options":["₹31,046.07","₹50,000.00","₹34,150.67","₹37,565.74"],"answer":2,"explanation":"C/r = ₹50,000 gives the value at the end of year 4 (one period before the first payment). Discount 4 years: 50,000/1.1⁴ = ₹34,150.67. Discounting 5 years is the usual off-by-one error.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-19","question":"A moneylender charges 2% per month, compounded monthly. What is the effective annual interest rate?","options":["24.00%","26.25%","27.12%","26.82%"],"answer":3,"explanation":"EAR = 1.02¹² − 1 = 26.82%. 24% is the nominal rate; 26.25% would be 24% compounded quarterly and 27.12% continuous compounding.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-20","question":"An instrument pays ₹8,000 at the end of each of the next 3 years and ₹1,00,000 at the end of year 3. At a 10% required return, what is its value?","options":["₹95,026.30","₹93,163.04","₹1,00,000.00","₹80,000.00"],"answer":0,"explanation":"PV = 8,000/1.1 + 8,000/1.1² + 1,08,000/1.1³ = 7,272.73 + 6,611.57 + 81,141.99 = ₹95,026.30. Discounting all ₹1,24,000 at year 3 overstates the delay of the coupons.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-21","question":"Which statement about an annuity due compared with an otherwise identical ordinary annuity is correct?","options":["Both PV and FV are higher by a factor of (1 + r)","Its PV is higher by (1 + r) but its FV is the same","Its PV and FV are both lower by a factor of (1 + r)","Its PV is the same but its FV is higher by (1 + r)"],"answer":0,"explanation":"Every payment of an annuity due arrives one period earlier, so each cash flow is worth (1 + r) times more at any valuation date: PV_due = PV_ord × (1 + r) and FV_due = FV_ord × (1 + r).","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-22","question":"A company must redeem ₹20 crore of debentures at the end of 5 years. It will deposit an equal amount at the BEGINNING of each year into a fund earning 7% compounded annually. What is the annual deposit (₹ lakh, 2 decimals)?","options":["₹347.78 lakh","₹325.03 lakh","₹400.00 lakh","₹487.78 lakh"],"answer":1,"explanation":"FV of an annuity due = A × [(1.07⁵ − 1)/0.07] × 1.07 = 20 crore → A = ₹3,25,02,934 ≈ ₹325.03 lakh. ₹347.78 lakh is the end-of-year deposit; ₹487.78 lakh wrongly uses the loan (PV) formula.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-23","question":"How long does money take to triple at 10% per annum compounded annually?","options":["20.00 years","10.99 years","7.20 years","11.53 years"],"answer":3,"explanation":"1.1ⁿ = 3 → n = ln 3 / ln 1.1 = 1.0986/0.09531 = 11.53 years. 20 years is the simple-interest answer and 10.99 years assumes continuous compounding.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-24","question":"A finance company lends ₹1,00,000 repayable in 4 equal year-end instalments of ₹31,547 and advertises a 'flat rate' of interest. What is the true effective annual rate?","options":["6.55%","13.09%","10%","8%"],"answer":2,"explanation":"₹1,00,000/31,547 = 3.1699, which is the 4-year annuity factor at exactly 10%, so the IRR is 10%. The flat rate is (1,26,188 − 1,00,000)/1,00,000/4 = 6.55%, which understates the cost because the principal is repaid gradually.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-25","question":"₹5,000 is received every six months for 3 years (first receipt in 6 months). The discount rate is 10% per annum compounded half-yearly. What is the present value?","options":["₹24,868.52","₹25,378.46","₹21,776.30","₹30,000.00"],"answer":1,"explanation":"Use the per-period rate 5% and 6 periods: 5,000 × [1 − 1.05⁻⁶]/0.05 = 5,000 × 5.07569 = ₹25,378.46. Lumping into ₹10,000 a year at 10% gives ₹24,868.52; using 10% per half-year is wrong.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-26","question":"A deposit pays a nominal 11% per annum while inflation is 6%. What is the exact real rate of return (Fisher relation)?","options":["5.00%","17.66%","4.72%","1.83%"],"answer":2,"explanation":"(1 + nominal) = (1 + real)(1 + inflation) → real = 1.11/1.06 − 1 = 4.72%. 5% is only the approximation (11 − 6).","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-27","question":"A project returns ₹10,000, ₹20,000 and ₹30,000 at the ends of years 1, 2 and 3. At 12%, what is the present value of these inflows?","options":["₹49,847.39","₹42,706.81","₹48,036.63","₹46,225.86"],"answer":3,"explanation":"PV = 10,000/1.12 + 20,000/1.12² + 30,000/1.12³ = 8,928.57 + 15,943.88 + 21,353.41 = ₹46,225.86. ₹49,847.39 reverses the order of the flows; using the average ₹20,000 as an annuity gives ₹48,036.63.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-28","question":"A ₹5,00,000 loan at 10% per annum is repaid in 5 equal year-end instalments. How much of the SECOND instalment is interest?","options":["₹41,810.13","₹50,000.00","₹90,088.61","₹40,000.00"],"answer":0,"explanation":"Instalment = 5,00,000 × 0.10/(1 − 1.1⁻⁵) = ₹1,31,898.74. After year 1 the balance is 5,50,000 − 1,31,898.74 = ₹4,18,101.26; year-2 interest = 10% × that = ₹41,810.13. ₹90,088.61 is the principal part; ₹40,000 assumes equal principal repayments.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-29","question":"Other things equal, which change increases the present value of a fixed future cash flow?","options":["A lower discount rate","A higher discount rate","A longer wait before the cash flow is received","More frequent compounding at the same nominal rate"],"answer":0,"explanation":"PV = FV/(1 + r)ⁿ, so PV rises when r falls. A longer wait or more frequent compounding (higher effective rate) both lower PV.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-30","question":"₹25,000 is put in a deposit paying 6% simple interest per annum. How much interest does it earn in 4 years?","options":["₹6,561.92","₹6,000","₹1,500","₹31,000"],"answer":1,"explanation":"Simple interest = P × r × t = 25,000 × 0.06 × 4 = ₹6,000. ₹6,561.92 is compound interest; ₹31,000 is the amount, not the interest.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-31","question":"A machine costs ₹1,00,000 and generates a constant cash inflow of ₹30,000 a year. What is its simple payback period?","options":["3 years","4 years","3.67 years","3.33 years"],"answer":3,"explanation":"Payback = outlay / annual inflow = 1,00,000 / 30,000 = 3.33 years (3 years and 4 months).","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-32","question":"If a project's net present value at the firm's cost of capital is positive, its profitability index (PI) must be:","options":["Exactly 1","Less than 1 but positive","Greater than 1","Negative"],"answer":2,"explanation":"PI = PV of inflows / outlay = 1 + NPV/outlay, so NPV > 0 ⇔ PI > 1.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-33","question":"A project costs ₹2,00,000 and returns ₹70,000 at the end of each year for 4 years. At a 12% cost of capital, what is its NPV?","options":["₹80,000","₹38,128","₹21,891","₹12,614"],"answer":3,"explanation":"PV of inflows = 70,000 × 3.0373 (4-year annuity factor at 12%) = ₹2,12,614; NPV = ₹2,12,614 − 2,00,000 = ₹12,614. ₹80,000 ignores discounting; ₹38,128 treats the inflows as starting today.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-34","question":"For a project costing ₹2,00,000 with inflows of ₹70,000 a year for 4 years, what is the profitability index at 12%?","options":["1.063","0.063","1.400","0.941"],"answer":0,"explanation":"PI = PV of inflows / outlay = (70,000 × 3.0373)/2,00,000 = 2,12,614/2,00,000 = 1.063. 1.400 uses undiscounted inflows; 0.063 is NPV/outlay, not PI.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-35","question":"A project costing ₹5,60,000 returns ₹1,20,000, ₹1,80,000, ₹2,00,000, ₹1,50,000 and ₹1,00,000 in years 1–5. What is its payback period (cash flows evenly spread within a year)?","options":["3.73 years","3.40 years","4.00 years","3.60 years"],"answer":1,"explanation":"Cumulative inflows: 1.2, 3.0, 5.0 lakh after 3 years. ₹60,000 more is needed out of year 4's ₹1,50,000 → 0.4 year. Payback = 3.40 years. 3.73 years wrongly divides the outlay by the average inflow (₹1,50,000).","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-36","question":"For the same ₹5,60,000 project with inflows of ₹1,20,000, ₹1,80,000, ₹2,00,000, ₹1,50,000 and ₹1,00,000, what is the discounted payback period at 10%?","options":["3.40 years","4.01 years","4.80 years","5.00 years"],"answer":2,"explanation":"Discounted inflows at 10%: 1,09,091, 1,48,760, 1,50,263, 1,02,452, 62,092. Cumulative after 4 years = 5,10,566, short of 5,60,000 by 49,434; year 5 adds 62,092, so discounted payback = 4 + 49,434/62,092 = 4.80 years. 4.01 years wrongly mixes discounted and undiscounted flows.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-37","question":"An investment of ₹1,00,000 returns a single payment of ₹1,44,000 at the end of year 2 and nothing else. What is its IRR?","options":["20%","22%","44%","18.5%"],"answer":0,"explanation":"1,00,000(1 + IRR)² = 1,44,000 → (1 + IRR) = √1.44 = 1.2 → IRR = 20%. 22% is the simple average (44%/2).","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-38","question":"A project's NPV is +₹8,000 at 10% and −₹2,000 at 15%. Using linear interpolation, its IRR is approximately:","options":["11.0%","12.5%","13.0%","14.0%"],"answer":3,"explanation":"IRR ≈ 10% + 5% × 8,000/(8,000 + 2,000) = 10% + 4% = 14%. 11% weights by the wrong NPV (2,000/10,000).","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-39","question":"Mutually exclusive projects, each costing ₹1,00,000: A returns ₹1,30,000 at the end of year 1 (IRR 30%); B returns ₹1,69,000 at the end of year 3 (IRR ≈ 19.1%). The cost of capital is 10%. Which should be chosen?","options":["A, because its IRR of 30% is higher than B's","A, as its payback of under 1 year is shorter","B, as its NPV (₹26,972) exceeds A's (₹18,182)","Either, because both have positive NPV at 10%"],"answer":2,"explanation":"NPV(A) = 1,30,000/1.1 − 1,00,000 = ₹18,182; NPV(B) = 1,69,000/1.1³ − 1,00,000 = ₹26,972. For mutually exclusive projects the higher NPV wins; IRR misranks them because of the timing difference.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-40","question":"Projects A (−1,00,000 now, +1,30,000 in year 1) and B (−1,00,000 now, +1,69,000 in year 3) are mutually exclusive. Above what discount rate does A have the higher NPV?","options":["24.56%","14.02%","30.00%","19.11%"],"answer":1,"explanation":"The crossover rate is the IRR of (B − A): −1,30,000 in year 1 and +1,69,000 in year 3 → (1 + r)² = 1.3 → r = 14.02%. Above it the shorter project A wins; below it B wins. Averaging the two IRRs is meaningless.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-41","question":"A project costs ₹1,00,000 and returns ₹50,000 at the end of each of the next 3 years. If inflows are reinvested at the 10% cost of capital, what is its MIRR?","options":["23.38%","18.29%","14.47%","21.83%"],"answer":1,"explanation":"Terminal value of inflows = 50,000(1.1² + 1.1 + 1) = ₹1,65,500. MIRR = (1,65,500/1,00,000)^(1/3) − 1 = 18.29%. The IRR is 23.38%; MIRR is lower because it assumes reinvestment at 10%, not at the IRR.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-42","question":"A project has cash flows of −₹100 now, +₹230 in year 1 and −₹132 in year 2. Which statement is correct?","options":["It has a single IRR of 15%, the midpoint","Two IRRs, 10% and 20%; NPV is positive outside that range","Two IRRs, 10% and 20%; NPV is positive only between them","No real IRR, because the cash flows change sign twice"],"answer":2,"explanation":"Put x = 1 + r: −100x² + 230x − 132 = 0 → x = (230 ± 10)/200 = 1.1 or 1.2, so IRR = 10% and 20%. At 15%, NPV = −100 + 200 − 99.81 = +0.19 > 0, while at 0% NPV = −2, so NPV is positive only between the two IRRs.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-43","question":"A firm spent ₹5 lakh last year on a feasibility study for a new plant. In evaluating the plant today, this ₹5 lakh should be:","options":["Ignored, because it is a sunk cost","Added to the initial outlay","Spread over the plant's life as an annual outflow","Deducted from the project's terminal cash flow"],"answer":0,"explanation":"Capital budgeting uses incremental future cash flows. The study cost has already been incurred whatever the decision, so it is sunk and irrelevant.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-44","question":"A company will build a warehouse on land it bought years ago for ₹20 lakh; the land could be sold today for ₹35 lakh (ignore taxes). How should the land enter the warehouse's NPV analysis?","options":["As a ₹20 lakh outflow at time 0 (historical cost)","It should be ignored because the land is already owned","As a ₹15 lakh inflow (unrealised gain)","As a ₹35 lakh outflow at time 0 (opportunity cost)"],"answer":3,"explanation":"Using the land means giving up ₹35 lakh that could be realised now. Its opportunity cost, not its historical cost, is the relevant cash outflow.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-45","question":"A ₹10,00,000 machine (5-year life, straight-line depreciation, no salvage) raises EBITDA by ₹3,50,000 a year. Tax rate 30%, cost of capital 12%. What is the NPV?","options":["₹99,457","−₹1,16,830","₹2,61,672","−₹6,21,498"],"answer":0,"explanation":"Annual OCF = (EBITDA − depreciation)(1 − t) + depreciation = (3,50,000 − 2,00,000)(0.7) + 2,00,000 = ₹3,05,000. NPV = 3,05,000 × 3.6048 − 10,00,000 = ₹99,457. Ignoring the depreciation tax shield gives −₹1,16,830; ignoring tax gives ₹2,61,672.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-46","question":"For a project year: sales ₹8 lakh, cash operating costs ₹3 lakh, depreciation ₹1 lakh, tax rate 25%. What is the operating cash flow?","options":["₹3.00 lakh","₹4.00 lakh","₹3.75 lakh","₹5.00 lakh"],"answer":1,"explanation":"OCF = (8 − 3 − 1)(1 − 0.25) + 1 = 3.00 + 1.00 = ₹4.00 lakh. Equivalently (8 − 3)(0.75) + 0.25 × 1 = 3.75 + 0.25. ₹3.00 lakh is net profit and ₹3.75 lakh forgets the depreciation tax shield.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-47","question":"At the end of a project, a machine with a tax book value of ₹1.2 lakh is sold for ₹2 lakh; the tax rate is 30% and ₹1.5 lakh of working capital is released. What is the terminal cash flow?","options":["₹3.50 lakh","₹2.90 lakh","₹3.26 lakh","₹1.76 lakh"],"answer":2,"explanation":"After-tax salvage = 2 − 0.30 × (2 − 1.2) = 2 − 0.24 = 1.76 lakh; add working-capital recovery 1.5 lakh → ₹3.26 lakh. ₹3.50 lakh ignores the tax on the gain; ₹2.90 lakh taxes the whole sale price; ₹1.76 lakh forgets working capital.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-48","question":"With ₹10 lakh to invest, a firm can choose among indivisible projects A (cost ₹6 lakh, NPV ₹1.80 lakh), B (₹4 lakh, ₹1.40 lakh), C (₹5 lakh, ₹1.60 lakh) and D (₹3 lakh, ₹0.75 lakh). Which selection maximises NPV?","options":["B and C (total NPV ₹3.00 lakh)","A and D (total NPV ₹2.55 lakh)","B, C and D (total NPV ₹3.75 lakh)","A and B (total NPV ₹3.20 lakh)"],"answer":3,"explanation":"PIs: B 1.35, C 1.32, A 1.30, D 1.25. Ranking by PI picks B + C (₹9 lakh, NPV 3.00) and leaves ₹1 lakh idle, but with indivisible projects the right test is the feasible combination with the highest total NPV: A + B uses all ₹10 lakh for NPV 3.20. B + C + D has a higher NPV but costs ₹12 lakh, beyond the budget.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-49","question":"Two mutually exclusive machines will be replaced repeatedly: X has NPV ₹50,000 over a 3-year life; Y has NPV ₹70,000 over a 5-year life. At 10%, which is better and why?","options":["X: its EAA (₹20,106) beats Y's (₹18,466)","Y, because its NPV of ₹70,000 is higher","Y, because its EAA (₹18,466) exceeds X's","They are equal once their lives are considered"],"answer":0,"explanation":"EAA = NPV / annuity factor: X = 50,000/2.4869 = ₹20,106; Y = 70,000/3.7908 = ₹18,466. For repeated projects of unequal life, compare EAAs, so X wins despite its lower NPV.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-50","question":"Machine P costs ₹3,00,000, runs for 4 years and costs ₹40,000 a year to operate; machine Q costs ₹4,50,000, runs for 6 years and costs ₹25,000 a year. At 12%, compare their equivalent annual costs.","options":["P is cheaper: ₹1,38,770 vs ₹1,34,452 a year","P is cheaper: ₹1,15,000 vs ₹1,00,000 a year","Q is cheaper: ₹1,34,452 vs ₹1,38,770 a year","Both cost the same per year"],"answer":2,"explanation":"EAC = cost / annuity factor + running cost. P: 3,00,000/3.0373 + 40,000 = ₹1,38,770. Q: 4,50,000/4.1114 + 25,000 = ₹1,34,452. Q has the lower EAC. Straight division (₹75,000 + 40,000 vs ₹75,000 + 25,000) ignores the time value of money.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-51","question":"For a conventional project (one outflow followed by inflows), the NPV at 14% is positive. Which conclusions follow? I. The IRR exceeds 14%. II. The PI at 14% exceeds 1. III. The discounted payback at 14% is shorter than the simple payback.","options":["I only","I and II only","I, II and III","II and III only"],"answer":1,"explanation":"With conventional flows NPV falls as the rate rises, so positive NPV at 14% means IRR > 14% (I) and PI > 1 (II). Discounted payback is always LONGER than simple payback, so III is false.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-52","question":"An asset costs ₹5,00,000, has a salvage value of ₹1,00,000 after 5 years and yields an average profit after tax of ₹60,000 a year. What is its accounting rate of return on average investment?","options":["12%","15%","24%","20%"],"answer":3,"explanation":"Average investment = (5,00,000 + 1,00,000)/2 = 3,00,000. ARR = 60,000/3,00,000 = 20%. 12% uses the initial investment; 15% uses the depreciable amount ₹4,00,000.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-53","question":"A project needs ₹8 lakh of machinery plus ₹2 lakh of working capital at the start; the working capital is fully recovered at the end of year 5. Inflows are ₹3 lakh a year for 5 years. At 10%, what is the NPV?","options":["₹2,61,420","₹3,37,236","₹1,37,236","₹2,73,839"],"answer":0,"explanation":"NPV = 3,00,000 × 3.7908 + 2,00,000/1.1⁵ − 10,00,000 = 11,37,236 + 1,24,184 − 10,00,000 = ₹2,61,420. Ignoring working capital altogether gives ₹3,37,236; forgetting its recovery gives ₹1,37,236.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-54","question":"Assertion (A): IRR can rank two mutually exclusive projects differently from NPV. Reason (R): IRR implicitly assumes intermediate cash flows are reinvested at the project's own IRR, whereas NPV assumes reinvestment at the cost of capital.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true. The different reinvestment-rate assumptions (along with differences in scale and timing) are the standard explanation for NPV–IRR ranking conflicts.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-55","question":"A ₹10 lakh project yields ₹2.5 lakh a year for 6 years; the cost of capital is 12%. By what percentage can annual inflows fall before the NPV becomes zero?","options":["2.79%","33.33%","2.71%","12.00%"],"answer":2,"explanation":"PV of inflows = 2,50,000 × 4.1114 = ₹10,27,852; NPV = ₹27,852. Inflows can fall by NPV/PV of inflows = 27,852/10,27,852 = 2.71%. Dividing by the outlay (2.79%) uses the wrong base; 33.33% ignores discounting.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-56","question":"Which statements about payback are correct? I. Simple payback ignores cash flows after the payback date. II. Discounted payback can never be shorter than simple payback for a conventional project. III. A project with a payback shorter than the cut-off must have a positive NPV.","options":["I, II and III","I only","II and III only","I and II only"],"answer":3,"explanation":"I and II are true. III is false: a project can recover its cost quickly yet have little or nothing after payback, so its NPV can still be negative, especially under simple payback.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-57","question":"A project costing ₹1,60,000 is expected to generate ₹1,00,000 a year for 2 years in TODAY'S prices. The nominal cost of capital is 15.5% and inflation is 5%. What is the NPV?","options":["₹1,541","₹13,554","₹12,396","₹40,000"],"answer":1,"explanation":"Real rate = 1.155/1.05 − 1 = 10%. Discount real flows at the real rate: 1,00,000 × 1.7355 − 1,60,000 = ₹13,554. Discounting real flows at the nominal rate (₹1,541) understates NPV; using 15.5 − 5 = 10.5% is only an approximation.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-58","question":"Which capital budgeting method ignores the time value of money?","options":["Net present value","Profitability index","Internal rate of return","Simple payback period"],"answer":3,"explanation":"Simple payback (like ARR) adds undiscounted cash flows. NPV, PI and IRR are discounted cash flow methods.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-59","question":"A diversified firm uses its company-wide WACC of 11% to evaluate all projects. Over time, this practice tends to:","options":["Under-invest in high-risk projects and over-invest in low-risk projects","Have no effect if the WACC is computed with market-value weights","Over-invest in high-risk projects and under-invest in low-risk projects","Lower the firm's beta"],"answer":2,"explanation":"Risky projects deserve a hurdle above 11% and safe ones below it. A single rate accepts risky projects that should be rejected and rejects safe ones that should be accepted, gradually raising the firm's risk.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-60","question":"Match each technique with its feature. Techniques: (p) NPV, (q) IRR, (r) PI, (s) Payback. Features: (1) Best for ranking divisible projects under capital rationing; (2) Measures liquidity rather than profitability; (3) May give multiple answers for non-conventional cash flows; (4) Directly measures the increase in shareholder wealth.","options":["p-1, q-3, r-4, s-2","p-4, q-3, r-1, s-2","p-4, q-1, r-3, s-2","p-3, q-4, r-1, s-2"],"answer":1,"explanation":"NPV is the rupee value added for shareholders (4); IRR can have multiple roots when signs change more than once (3); PI ranks divisible projects when funds are rationed (1); payback is a liquidity/risk screen (2).","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-61","question":"The risk-free rate is 6%, the market return is 12% and a stock's beta is 1.2. What is its required return under CAPM?","options":["14.40%","13.20%","20.40%","7.20%"],"answer":1,"explanation":"Ke = Rf + β(Rm − Rf) = 6% + 1.2 × (12% − 6%) = 6% + 7.2% = 13.2%. 14.4% multiplies beta by the market return instead of the market premium.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-62","question":"A company borrows at 10% and pays tax at 30%. What is its after-tax cost of debt?","options":["10%","13%","3%","7%"],"answer":3,"explanation":"After-tax Kd = 10% × (1 − 0.30) = 7%, because interest is tax-deductible. 3% is the tax saving, not the cost.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-63","question":"A share trades at ₹200. The dividend just paid was ₹10 and dividends are expected to grow at 6% a year forever. What is the cost of equity?","options":["11.00%","5.30%","11.30%","6.00%"],"answer":2,"explanation":"D₁ = 10 × 1.06 = 10.60. Ke = D₁/P₀ + g = 10.60/200 + 6% = 5.3% + 6% = 11.3%. Using D₀ gives 11.0%; 5.3% forgets growth.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-64","question":"A firm has ₹60 lakh of equity (cost 14%) and ₹40 lakh of debt (pre-tax cost 10%). The tax rate is 25%. What is its WACC?","options":["11.40%","12.40%","10.75%","10.10%"],"answer":0,"explanation":"WACC = 0.6 × 14% + 0.4 × 10% × (1 − 0.25) = 8.4% + 3.0% = 11.4%. 12.4% ignores the tax shield; 10.10% swaps the weights.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-65","question":"A company has 10 lakh shares (face value ₹10, market price ₹50) and debentures of face value ₹2 crore trading at 95% of par with a YTM of 9%. The cost of equity is 15% and the tax rate 30%. What is the WACC using market-value weights?","options":["12.60%","9.20%","13.35%","12.51%"],"answer":0,"explanation":"Market values: equity = 10 lakh × ₹50 = ₹5 crore; debt = 0.95 × 2 = ₹1.9 crore. After-tax Kd = 9% × 0.7 = 6.3%. WACC = (5 × 15% + 1.9 × 6.3%)/6.9 = 12.60%. Book weights (₹1 crore and ₹2 crore) give 9.20%; using pre-tax Kd gives 13.35%.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-66","question":"A 5-year bond with face value ₹100 and a 10% annual coupon trades at ₹95. Using the approximation formula, what is its yield to maturity?","options":["10.53%","11.28%","10.00%","11.58%"],"answer":1,"explanation":"Approximate YTM = [coupon + (face − price)/n] / [(face + price)/2] = [10 + 5/5]/97.5 = 11/97.5 = 11.28%. 10.53% is the current yield (10/95), which ignores the ₹5 gain at maturity.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-67","question":"Irredeemable 12% preference shares of face value ₹100 are issued at ₹95, with flotation costs of 2% of face value. What is the cost of preference capital?","options":["12.00%","12.63%","12.90%","9.03%"],"answer":2,"explanation":"Net proceeds = 95 − 2 = ₹93. Kp = 12/93 = 12.90%. Preference dividends are not tax-deductible, so no (1 − t) adjustment; 9.03% wrongly applies one.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-68","question":"A firm's share price is ₹100, next year's dividend is ₹5 and growth is 7%. New shares involve flotation costs of 5% of the price. What are the costs of retained earnings and of new equity?","options":["12.26% and 12.00%","12.00% and 12.00%","12.35% and 12.26%","12.00% and 12.26%"],"answer":3,"explanation":"Retained earnings: Ke = 5/100 + 7% = 12%. New equity: Ke = 5/(100 × 0.95) + 7% = 5.263% + 7% = 12.26%. New equity costs more because of flotation costs.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-69","question":"A comparable listed firm has an equity beta of 1.5 at a debt–equity ratio of 0.5. Your firm has the same business risk but a debt–equity ratio of 1.0. Tax rate 30%, risk-free rate 6%, market risk premium 7%. What is your firm's cost of equity?","options":["19.22%","16.50%","20.00%","23.85%"],"answer":0,"explanation":"Unlever: β_U = 1.5/[1 + 0.7 × 0.5] = 1.1111. Relever: β_L = 1.1111 × [1 + 0.7 × 1.0] = 1.8889. Ke = 6% + 1.8889 × 7% = 19.22%. 16.5% uses the comparable's beta unchanged; 20% ignores taxes in unlevering and relevering (β_U = 1.0, β_L = 2.0); 23.85% relevers the comparable beta without unlevering it first.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-70","question":"A firm targets 30% debt and 70% equity. Its beta is 1.3, the risk-free rate 7%, the market risk premium 6%, its pre-tax cost of debt 10% and its tax rate 25%. What is its WACC?","options":["13.36%","12.61%","11.01%","14.80%"],"answer":1,"explanation":"Ke = 7% + 1.3 × 6% = 14.8%. After-tax Kd = 10% × 0.75 = 7.5%. WACC = 0.7 × 14.8% + 0.3 × 7.5% = 10.36% + 2.25% = 12.61%. 13.36% ignores the tax shield; 14.8% is just the cost of equity.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-71","question":"A firm sells 10,000 units at ₹50 each; variable cost is ₹30 per unit and fixed operating costs are ₹1,20,000. What is its degree of operating leverage?","options":["1.67","0.40","2.50","1.60"],"answer":2,"explanation":"Contribution = 10,000 × (50 − 30) = ₹2,00,000; EBIT = 2,00,000 − 1,20,000 = ₹80,000. DOL = contribution/EBIT = 2,00,000/80,000 = 2.5. 0.40 is the inverse (EBIT/contribution).","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-72","question":"A firm has contribution of ₹2,00,000, EBIT of ₹80,000 and interest of ₹20,000. What is its degree of combined leverage?","options":["3.83","1.88","2.50","3.33"],"answer":3,"explanation":"DOL = 2,00,000/80,000 = 2.5; DFL = 80,000/(80,000 − 20,000) = 1.333; DCL = 2.5 × 1.333 = 3.33 (= contribution/EBT = 2,00,000/60,000). Adding the two (3.83) is the trap.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-73","question":"A company's DOL is 2.5 and its DFL is 1.6. If sales rise by 8%, by how much will EPS rise?","options":["32.0%","20.0%","12.8%","33.6%"],"answer":0,"explanation":"DCL = 2.5 × 1.6 = 4.0, so %ΔEPS = 4.0 × 8% = 32%. 20% applies only DOL (EBIT change); 33.6% wrongly adds (2.5 + 1.6) × 8%.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-74","question":"Selling price ₹50, variable cost ₹30 per unit, fixed costs ₹1,20,000 and current sales of 10,000 units. What is the margin of safety, and how does it relate to DOL?","options":["60%, which equals 1/DOL","40%, which equals 1/DOL","40%, which equals DOL − 1","60%, which equals 1 − 1/DOL"],"answer":1,"explanation":"Break-even = 1,20,000/20 = 6,000 units. Margin of safety = (10,000 − 6,000)/10,000 = 40%. DOL = 2.5 and 1/2.5 = 0.40: the margin of safety ratio is always the reciprocal of DOL.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-75","question":"EBIT is ₹5 lakh, interest ₹1 lakh and preference dividend ₹60,000; the tax rate is 40%. What is the degree of financial leverage?","options":["1.250","1.471","1.374","1.667"],"answer":3,"explanation":"Preference dividend is paid from after-tax profit, so gross it up: 60,000/(1 − 0.4) = ₹1,00,000. DFL = EBIT/[EBIT − I − Dp/(1 − t)] = 5/(5 − 1 − 1) = 1.667. 1.250 ignores the preference dividend; 1.471 forgets the gross-up.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-76","question":"A new company needs ₹50 lakh. Plan 1: issue 5 lakh equity shares of ₹10. Plan 2: issue 2.5 lakh shares of ₹10 and ₹25 lakh of 12% debt. Tax rate 30%. At what EBIT are the two plans' EPS equal, and what is that EPS?","options":["EBIT ₹3 lakh; EPS ₹0.42","EBIT ₹12 lakh; EPS ₹1.68","EBIT ₹6 lakh; EPS ₹0.84","EBIT ₹6 lakh; EPS ₹1.20"],"answer":2,"explanation":"(EBIT)(0.7)/5 = (EBIT − 3)(0.7)/2.5 (₹ lakh, shares in lakh) → 2.5 EBIT = 5 EBIT − 15 → EBIT = ₹6 lakh. EPS = 6 × 0.7/5 = ₹0.84 under both plans. ₹1.20 forgets tax.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-77","question":"Plan 1: 10 lakh equity shares. Plan 2: 6 lakh equity shares plus ₹40 lakh of 10% preference shares. Tax rate 40%. What is the EBIT indifference point?","options":["₹10.00 lakh","₹6.67 lakh","₹25.00 lakh","₹16.67 lakh"],"answer":3,"explanation":"0.6 EBIT/10 = (0.6 EBIT − 4)/6 (₹ lakh) → 3.6 EBIT = 6 EBIT − 40 → EBIT = 40/2.4 = ₹16.67 lakh. Treating the ₹4 lakh preference dividend as if it were pre-tax interest gives ₹10 lakh.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-78","question":"Under Modigliani–Miller without taxes, an all-equity firm has a cost of capital of 12%. An identical firm is financed 40% by debt costing 8% and 60% by equity. What is the levered firm's cost of equity?","options":["12.00%","14.67%","13.60%","10.40%"],"answer":1,"explanation":"MM Proposition II: Ke = Ko + (Ko − Kd) × D/E = 12% + (12% − 8%) × 40/60 = 14.67%. 13.6% uses D/V (0.4) instead of D/E; 10.4% is the WACC-style average 0.6 × 12 + 0.4 × 8.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-79","question":"Under Modigliani–Miller with corporate taxes, an unlevered firm is worth ₹200 crore. An identical firm has ₹80 crore of permanent debt; the tax rate is 25%. What is the value of the levered firm's equity?","options":["₹140 crore","₹120 crore","₹220 crore","₹200 crore"],"answer":0,"explanation":"V_L = V_U + tD = 200 + 0.25 × 80 = ₹220 crore; equity = V_L − D = 220 − 80 = ₹140 crore. ₹220 crore is the firm value, not equity; ₹120 crore ignores the tax shield.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-80","question":"Which statements are correct? I. Under the Net Income approach, using more debt raises firm value. II. Under the Net Operating Income approach, the overall cost of capital is constant whatever the leverage. III. Under the traditional approach, there is an optimal capital structure.","options":["I and II only","II and III only","I, II and III","I and III only"],"answer":2,"explanation":"NI approach: Ke and Kd are constant, so adding cheaper debt lowers WACC and raises value. NOI approach: Ko is constant and Ke rises to offset cheaper debt. Traditional approach: WACC first falls, then rises, so an optimum exists.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-81","question":"Assertion (A): Retained earnings are not a free source of finance. Reason (R): Shareholders forgo the return they could have earned by investing the dividends themselves.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: retained earnings carry an opportunity cost roughly equal to the cost of equity (without flotation costs).","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-82","question":"A firm estimates these after-tax costs: at 0% debt, Ke = 12%; at 20% debt, Ke = 12.5% and Kd = 7%; at 40% debt, Ke = 14% and Kd = 8%; at 60% debt, Ke = 18% and Kd = 10%. Under the traditional view, which debt ratio is optimal?","options":["0% debt (WACC 12.0%)","40% debt (WACC 11.6%)","20% debt (WACC 11.4%)","60% debt (WACC 13.2%)"],"answer":2,"explanation":"WACC: 0% → 12%; 20% → 0.8 × 12.5 + 0.2 × 7 = 11.4%; 40% → 0.6 × 14 + 0.4 × 8 = 11.6%; 60% → 0.4 × 18 + 0.6 × 10 = 13.2%. The minimum WACC (11.4%) is at 20% debt.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-83","question":"A firm earns an operating return on assets (EBIT/assets) of 15%. It borrows at 10%, has a debt–equity ratio of 1 and pays tax at 30%. What is its return on equity?","options":["10.5%","20.0%","17.5%","14.0%"],"answer":3,"explanation":"ROE = [ROA + (ROA − Kd) × D/E](1 − t) = [15% + 5% × 1] × 0.7 = 14%. The unlevered ROE would be 15% × 0.7 = 10.5%; 20% forgets tax. Leverage helps because ROA > Kd.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-84","question":"Why is debt usually the cheapest source of long-term finance for a profitable company?","options":["Debt never has to be repaid out of the company's future profits","Interest is tax-deductible and lenders bear less risk","Lenders share in the company's profits like owners","Debt does not increase the firm's financial risk"],"answer":1,"explanation":"Lenders have a fixed, prior claim, so they accept a lower return, and the tax deductibility of interest cuts the effective cost further. Debt does raise financial risk and must be repaid.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-85","question":"A firm's DOL is 3 and its DFL is 2; its current EPS is ₹12. If sales fall by 5%, what will EPS become?","options":["₹9.00","₹10.80","₹11.40","₹8.40"],"answer":3,"explanation":"DCL = 3 × 2 = 6, so EPS falls 6 × 5% = 30%: 12 × 0.70 = ₹8.40. Adding the leverages (5 × 5% = 25%) gives ₹9.00; using only DFL gives ₹10.80.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-86","question":"A company's degree of financial leverage is 1.25 and it has no preference shares. What is its interest coverage ratio (EBIT/interest)?","options":["5 times","1.25 times","4 times","0.8 times"],"answer":0,"explanation":"DFL = EBIT/(EBIT − I) = 1.25 → EBIT = 1.25 EBIT − 1.25 I → 0.25 EBIT = 1.25 I → EBIT/I = 5.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-87","question":"Irredeemable 12% debentures of face value ₹100 are issued at ₹96 net of costs. The tax rate is 30%. What is the after-tax cost of debt?","options":["8.40%","8.75%","12.50%","12.00%"],"answer":1,"explanation":"Kd = I(1 − t)/net proceeds = 12 × 0.7/96 = 8.4/96 = 8.75%. 8.40% uses face value instead of net proceeds; 12.50% is the pre-tax cost.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-88","question":"A firm keeps 60% equity and 40% debt and expects ₹30 lakh of retained earnings this year. Beyond what total capital budget must it issue costlier new equity (the retained-earnings break point)?","options":["₹30 lakh","₹18 lakh","₹50 lakh","₹75 lakh"],"answer":2,"explanation":"Break point = retained earnings / equity weight = 30/0.6 = ₹50 lakh. Up to ₹50 lakh, the equity part (60%) is met from retained earnings; beyond it new shares are needed. ₹75 lakh divides by the debt weight.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-89","question":"A firm sells at ₹50 a unit with variable cost ₹30 and fixed costs ₹1,20,000. If volume falls from 10,000 to 8,000 units, what happens to EBIT and to DOL?","options":["EBIT falls 20% to ₹64,000 and DOL stays 2.5","EBIT falls 50% to ₹40,000 and DOL falls to 1.6","EBIT falls 40% to ₹48,000 and DOL rises to 3.3","EBIT falls 50% to ₹40,000 and DOL rises to 4.0"],"answer":3,"explanation":"At 10,000 units EBIT = ₹80,000 and DOL = 2.5, so a 20% volume fall cuts EBIT by 2.5 × 20% = 50% to ₹40,000 (check: 8,000 × 20 − 1,20,000). New DOL = 1,60,000/40,000 = 4.0: leverage rises as sales approach break-even.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-90","question":"Which theory holds that, in perfect markets without taxes, a firm's value does not depend on how it is financed?","options":["Net Income (NI) approach","Myers' pecking order theory","Modigliani–Miller proposition I","Traditional approach to capital structure"],"answer":2,"explanation":"MM (1958) showed that without taxes, bankruptcy costs or information asymmetry, firm value depends only on its assets' cash flows and risk, not on the debt–equity mix.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-91","question":"A firm holds inventory for 60 days, collects receivables in 45 days and pays suppliers in 30 days. What is its cash conversion cycle?","options":["75 days","135 days","105 days","15 days"],"answer":0,"explanation":"Operating cycle = 60 + 45 = 105 days; cash conversion cycle = 105 − 30 = 75 days. 135 days wrongly adds the payable period.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-92","question":"Cost of goods sold ₹36.5 lakh, average inventory ₹6 lakh, credit sales ₹73 lakh, average debtors ₹9 lakh, credit purchases ₹40.15 lakh and average creditors ₹3.3 lakh (365-day year). What is the cash conversion cycle?","options":["105 days","75 days","135 days","45 days"],"answer":1,"explanation":"Inventory days = 6/36.5 × 365 = 60; receivable days = 9/73 × 365 = 45; payable days = 3.3/40.15 × 365 = 30. CCC = 60 + 45 − 30 = 75 days. Computing inventory days on sales instead of COGS gives 30 days and a CCC of 45.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-93","question":"Annual demand is 10,000 units, the cost of placing an order is ₹200 and the holding cost is ₹4 per unit per year. What is the economic order quantity?","options":["707 units","1,000 units","1,414 units","500 units"],"answer":1,"explanation":"EOQ = √(2AO/C) = √(2 × 10,000 × 200/4) = √10,00,000 = 1,000 units. 707 units forgets the 2 in the formula.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-94","question":"With annual demand of 10,000 units, ordering cost ₹200 and holding cost ₹4 per unit per year, what is the total annual ordering-plus-holding cost at the EOQ?","options":["₹2,000","₹6,000","₹4,828","₹4,000"],"answer":3,"explanation":"EOQ = 1,000 units. Ordering cost = (10,000/1,000) × 200 = ₹2,000; holding cost = (1,000/2) × 4 = ₹2,000; total ₹4,000. At EOQ the two costs are always equal.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-95","question":"A retailer sells 24,000 units a year. Each order costs ₹150 to place, the unit price is ₹50 and annual carrying cost is 12% of the price. What is the EOQ (nearest unit)?","options":["316 units","379 units","1,095 units","1,549 units"],"answer":2,"explanation":"Holding cost C = 12% × 50 = ₹6 per unit per year. EOQ = √(2 × 24,000 × 150/6) = √12,00,000 = 1,095.4 ≈ 1,095 units. Using monthly demand gives 316; using the price ₹50 as C gives 379; halving the carrying cost (₹3) gives 1,549.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-96","question":"Annual demand 10,000 units, price ₹10, ordering cost ₹200 per order, holding cost 20% of price a year. The supplier offers a 2% discount on orders of at least 2,500 units. Should the firm take the discount, and what is the annual saving?","options":["Yes; total cost falls by about ₹1,578","No; total cost rises by about ₹650","Yes; total cost falls by exactly ₹2,000","No; EOQ (1,414 units) is always optimal"],"answer":0,"explanation":"At EOQ = √(2 × 10,000 × 200/2) = 1,414: purchase ₹1,00,000 + ordering 1,414 + holding 1,414 = ₹1,02,828. At 2,500 units (price ₹9.80, C = ₹1.96): 98,000 + 4 × 200 + 1,250 × 1.96 = ₹1,01,250. Saving ≈ ₹1,578. ₹2,000 counts only the price discount and ignores the higher holding cost.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-97","question":"Daily usage is 40 units, the supplier's lead time is 12 days and the firm keeps a safety stock of 200 units. What is the reorder level?","options":["680 units","480 units","880 units","240 units"],"answer":0,"explanation":"Reorder level = lead-time demand + safety stock = 40 × 12 + 200 = 680 units. 480 units forgets the safety stock.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-98","question":"A supplier offers terms of 2/10 net 40. What is the approximate annualised cost of NOT taking the discount and paying on day 40 (365-day year, simple basis)?","options":["24.33%","18.62%","24.83%","2.04%"],"answer":2,"explanation":"Cost = [d/(100 − d)] × [365/(credit period − discount period)] = (2/98) × (365/30) = 24.83%. Using 2/100 gives 24.33%; dividing by 40 instead of 30 days ignores that the discount is available until day 10.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-99","question":"Credit sales are ₹50 lakh with 30-day terms. Extending terms to 60 days would raise sales by 10%. Contribution margin is 25%, bad debts on the extra sales would be 4%, and funds tied up in receivables (valued at sales value, 360-day year) cost 12%. What is the net effect on annual profit?","options":["Gain of ₹95,000","Gain of ₹1,05,000","Loss of ₹15,000","Gain of ₹45,000"],"answer":3,"explanation":"Extra contribution = 5 lakh × 25% = ₹1,25,000. Extra bad debts = 4% × 5 lakh = ₹20,000. Receivables rise from 50 × 30/360 = 4.17 lakh to 55 × 60/360 = 9.17 lakh, i.e. by ₹5 lakh; cost = 12% × 5 lakh = ₹60,000. Net gain = 1,25,000 − 20,000 − 60,000 = ₹45,000. ₹95,000 counts the funding cost only on the new sales.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-100","question":"Annual credit sales are ₹60 lakh on 1-month terms; variable costs are 70% of sales and fixed costs will not change. Offering 2-month terms would lift sales to ₹72 lakh, while bad debts rise from 1% to 2% of total sales. The required return on receivables, valued at variable cost, is 15%. What is the net gain from the new policy?","options":["₹1.710 lakh","₹2.025 lakh","₹2.760 lakh","₹2.625 lakh"],"answer":1,"explanation":"Extra contribution = 12 × 30% = 3.60 lakh. Bad debts: 1.44 − 0.60 = 0.84 lakh. Receivables at variable cost: old 60 × 0.7/12 = 3.5 lakh, new 72 × 0.7 × 2/12 = 8.4 lakh; extra 4.9 lakh × 15% = 0.735 lakh. Net = 3.60 − 0.84 − 0.735 = ₹2.025 lakh. Valuing receivables at sales value gives 1.71; ignoring the cost of funds gives 2.76.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-101","question":"Which statement about working-capital financing policies is correct?","options":["A conservative policy finances temporary current assets with short-term funds only","The matching (hedging) policy finances fixed assets with short-term funds","Aggressive policy funds some permanent needs short-term, raising return and risk","An aggressive policy lowers both expected return and refinancing risk"],"answer":2,"explanation":"Matching: permanent needs from long-term funds, temporary needs from short-term funds. Aggressive: some permanent needs from cheaper short-term funds (higher return, higher risk). Conservative: even part of the temporary needs from long-term funds.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-102","question":"Current assets are ₹12 lakh and current liabilities ₹8 lakh. The firm pays ₹2 lakh to creditors in cash. What happens to the current ratio and net working capital?","options":["Current ratio falls from 1.50 to 1.25; NWC falls to ₹2 lakh","Current ratio stays 1.50; NWC stays ₹4 lakh","Current ratio rises from 1.50 to 1.67; NWC rises to ₹6 lakh","Current ratio rises from 1.50 to 1.67; NWC stays ₹4 lakh"],"answer":3,"explanation":"Both sides fall by ₹2 lakh: CA = 10, CL = 6. Current ratio = 10/6 = 1.67 (up from 1.50, because it was above 1). NWC = 10 − 6 = ₹4 lakh, unchanged.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-103","question":"Current assets of ₹12 lakh include inventory of ₹5 lakh and prepaid expenses of ₹1 lakh. Current liabilities are ₹6 lakh. What is the quick (acid-test) ratio?","options":["1.17","1.00","2.00","0.83"],"answer":1,"explanation":"Quick assets = 12 − 5 − 1 = ₹6 lakh; quick ratio = 6/6 = 1.00. 1.17 forgets to exclude prepaid expenses; 2.00 is the current ratio.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-104","question":"Under the Baumol model, a firm needs ₹36 lakh of cash a year, each conversion of securities into cash costs ₹150, and securities earn 9% a year. What is the optimal cash withdrawal size (nearest rupee)?","options":["₹1,09,545","₹77,460","₹31,623","₹3,79,473"],"answer":0,"explanation":"C* = √(2 × T × b / i) = √(2 × 36,00,000 × 150/0.09) = √(1.2 × 10¹⁰) ≈ ₹1,09,545. Forgetting the 2 gives ₹77,460; using the monthly need gives ₹31,623; pairing the annual need with a monthly rate (0.75%) gives ₹3,79,473.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-105","question":"Cost of goods sold is ₹48 lakh, opening inventory ₹7 lakh and closing inventory ₹9 lakh. What is the inventory turnover ratio?","options":["5.33 times","6.86 times","8.00 times","6.00 times"],"answer":3,"explanation":"Average inventory = (7 + 9)/2 = ₹8 lakh. Turnover = 48/8 = 6 times (about 61 days). Using closing inventory gives 5.33; using opening gives 6.86.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-106","question":"A company with annual credit sales of ₹7.3 crore cuts its average collection period from 60 to 45 days (365-day year). If its cost of funds is 10%, what is the annual interest saving?","options":["₹30 lakh","₹3 lakh","₹1.5 lakh","₹9 lakh"],"answer":1,"explanation":"Daily sales = 7.3 crore/365 = ₹2 lakh. Receivables fall by 15 days × 2 lakh = ₹30 lakh, which saves 10% × 30 lakh = ₹3 lakh a year. ₹30 lakh is the cash released, not the saving.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-107","question":"In factoring WITHOUT recourse, who bears the loss if a customer fails to pay a factored invoice?","options":["The selling firm","The customer's bank","The factor","The loss is shared equally by law"],"answer":2,"explanation":"Without recourse the factor buys the credit risk, so it bears bad debts and charges a higher fee. With recourse, the seller must make good any default.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-108","question":"Net working capital is defined as:","options":["Current assets minus current liabilities","Total current assets of the business","Current assets minus inventory and prepaid expenses","Fixed assets minus long-term debt"],"answer":0,"explanation":"Gross working capital is total current assets; net working capital is current assets less current liabilities.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-109","question":"Using Walter's model: EPS ₹10, DPS ₹4, return on investment 15% and cost of equity 12%. What is the share price?","options":["₹95.83","₹83.33","₹33.33","₹104.17"],"answer":0,"explanation":"P = [D + (r/k)(E − D)]/k = [4 + (0.15/0.12) × 6]/0.12 = (4 + 7.5)/0.12 = ₹95.83. ₹83.33 is E/k (the price when r = k); ₹104.17 is the price at zero payout.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-110","question":"Under Walter's model, a firm earns 15% on reinvested funds while its shareholders require 12%. What payout maximises the share price?","options":["100% (distribute all earnings)","The payout makes no difference","Exactly 50%","0% (retain all earnings)"],"answer":3,"explanation":"When r > k, every rupee retained creates more value than it would in shareholders' hands, so Walter's price is maximised at zero payout. When r < k the optimum is 100%; when r = k payout is irrelevant.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-111","question":"Under Gordon's model, a firm has EPS ₹20, earns 15% on retained funds and has a cost of equity of 12%. If it cuts its retention ratio from 60% to 40%, what happens to the share price?","options":["It rises from ₹266.67 to ₹200.00","It rises from ₹200.00 to ₹266.67","It falls from ₹266.67 to ₹200.00","It stays at ₹166.67"],"answer":2,"explanation":"g = b × r. At b = 0.6: g = 9%, D = 8, P = 8/(0.12 − 0.09) = ₹266.67. At b = 0.4: g = 6%, D = 12, P = 12/(0.12 − 0.06) = ₹200.00. With r > k, retaining less lowers growth and the price.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-112","question":"Under MM dividend irrelevance, a share trades at ₹100 today and investors require 10%. If a dividend of ₹5 is paid at year-end, what will the ex-dividend price at year-end be?","options":["₹110","₹105","₹100","₹95"],"answer":1,"explanation":"P₀ = (D₁ + P₁)/(1 + k) → 100 = (5 + P₁)/1.10 → P₁ = 110 − 5 = ₹105. Without the dividend P₁ would be ₹110; shareholders' total wealth is the same either way.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-113","question":"Under MM, a firm has 1 lakh shares priced at ₹100, cost of equity 10%, expected net income ₹20 lakh and planned investment ₹30 lakh. It will pay a ₹5 dividend at year-end. How many new shares must it issue at year-end to finance the investment?","options":["15,000","9,091","14,286","10,000"],"answer":2,"explanation":"Year-end price P₁ = 100 × 1.10 − 5 = ₹105. Funds needed = 30 − (20 − 5) = ₹15 lakh. New shares = 15,00,000/105 = 14,286. 15,000 uses the old price; 9,091 is the answer if no dividend were paid (₹10 lakh at ₹110).","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-114","question":"Which statements are correct? I. A bonus issue leaves total shareholders' funds unchanged. II. A stock split changes the face value per share. III. A bonus issue reduces the company's cash.","options":["I and II only","I, II and III","I only","II and III only"],"answer":0,"explanation":"A bonus issue capitalises reserves into share capital, so total net worth and cash are unchanged (III is false). A split divides each share into more shares of lower face value.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-115","question":"Under Lintner's model, a firm has a target payout of 40% and an adjustment factor of 0.5. Last year's DPS was ₹4 and this year's EPS is ₹15. What DPS should it declare?","options":["₹6.00","₹4.50","₹7.00","₹5.00"],"answer":3,"explanation":"D₁ = D₀ + speed × (target payout × EPS − D₀) = 4 + 0.5 × (0.4 × 15 − 4) = 4 + 0.5 × 2 = ₹5. ₹6 is the full target dividend with no smoothing.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-116","question":"A company's EPS is ₹8, its DPS is ₹3 and its share price is ₹60. What are its payout ratio and dividend yield?","options":["62.5% and 5.0%","37.5% and 5.0%","37.5% and 13.3%","5.0% and 37.5%"],"answer":1,"explanation":"Payout = DPS/EPS = 3/8 = 37.5%. Dividend yield = DPS/price = 3/60 = 5%. 62.5% is the retention ratio; 13.3% is the earnings yield.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-117","question":"The 'bird-in-hand' argument, that investors value a certain dividend today more than uncertain future capital gains, is most associated with:","options":["Modigliani and Miller","James Walter","Myron Gordon","Harry Markowitz"],"answer":2,"explanation":"Gordon (with Lintner) argued that risk-averse investors prefer current dividends, so higher payout lowers the required return. MM argued dividends are irrelevant.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-118","question":"A company earns ₹50 lakh after tax on 10 lakh shares. It buys back 1 lakh shares at ₹60 using cash that was earning 6% pre-tax; the tax rate is 25%. What is EPS after the buyback?","options":["₹5.26","₹5.00","₹5.56","₹5.16"],"answer":0,"explanation":"Lost after-tax income = 60 lakh × 6% × 0.75 = ₹2.7 lakh. New EPS = (50 − 2.7) lakh/9 lakh = ₹5.26 (up from ₹5.00). ₹5.56 ignores the lost interest; ₹5.16 forgets that the interest was taxable.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-119","question":"Assertion (A): Under Walter's model, if a firm's return on investment equals its cost of equity, the dividend payout has no effect on the share price. Reason (R): Each rupee retained then earns exactly what shareholders could earn by reinvesting it themselves.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"With r = k, P = [D + (E − D)]/k = E/k whatever D is. R gives the economic reason, so R explains A.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-120","question":"A firm follows a residual dividend policy with a target capital structure of 40% debt and 60% equity. Net income is ₹80 lakh and planned capital spending is ₹60 lakh. What dividend will it pay?","options":["₹20 lakh","₹44 lakh","₹56 lakh","₹32 lakh"],"answer":1,"explanation":"Equity needed for the budget = 60% × 60 = ₹36 lakh, taken from earnings first. Residual dividend = 80 − 36 = ₹44 lakh. ₹20 lakh wrongly funds the whole budget from equity; ₹56 lakh uses the debt share.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-121","question":"A 3-year bond of face value ₹1,000 pays an 8% annual coupon. If the market yield is 10%, what is its price?","options":["₹1,000.00","₹1,051.54","₹751.31","₹950.26"],"answer":3,"explanation":"Price = 80 × [1 − 1.1⁻³]/0.10 + 1,000/1.1³ = 80 × 2.4869 + 751.31 = ₹950.26. Because the coupon (8%) is below the yield (10%), the bond sells at a discount. ₹751.31 values only the principal.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-122","question":"A 2-year bond of face value ₹1,000 pays a 10% coupon half-yearly. The market yield is 8% per annum compounded half-yearly. What is its price?","options":["₹1,035.67","₹900.64","₹1,000.00","₹1,036.30"],"answer":3,"explanation":"Per half-year: coupon ₹50, yield 4%, 4 periods. Price = 50 × 3.6299 + 1,000/1.04⁴ = 181.49 + 854.80 = ₹1,036.30. Annual discounting gives ₹1,035.67; using 8% per half-year gives ₹900.64.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-123","question":"When a bond's yield to maturity is higher than its coupon rate, the bond trades:","options":["Above face value (at a premium)","Exactly at face value","Below face value (at a discount)","At a price that cannot be determined from this information"],"answer":2,"explanation":"A buyer needs a return above the coupon, which comes from paying less than face value and gaining the difference at maturity.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-124","question":"A bond with face value ₹1,000 and a 9% annual coupon trades at ₹900. What is its current yield?","options":["9.00%","10.00%","8.10%","11.11%"],"answer":1,"explanation":"Current yield = annual coupon/price = 90/900 = 10%. 9% is the coupon rate on face value; current yield ignores the gain at maturity, so YTM would be higher still.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-125","question":"A 5-year zero-coupon bond has a face value of ₹1,00,000. If investors require 7% a year (annual compounding), what is its price?","options":["₹65,000.00","₹74,074.07","₹71,298.62","₹76,289.52"],"answer":2,"explanation":"Price = 1,00,000/1.07⁵ = 1,00,000/1.40255 = ₹71,298.62. ₹65,000 deducts simple interest; 1.35 in the denominator is simple-interest discounting.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-126","question":"A 2-year bond pays a 10% annual coupon on ₹1,000 face value and yields 10%. What is its modified duration?","options":["1.9091 years","1.7355 years","2.0000 years","2.1000 years"],"answer":1,"explanation":"PV of cash flows: 100/1.1 = 90.91 and 1,100/1.21 = 909.09 (price ₹1,000). Macaulay duration = (1 × 90.91 + 2 × 909.09)/1,000 = 1.9091 years. Modified = 1.9091/1.10 = 1.7355. 2 years is the maturity, which equals duration only for a zero-coupon bond.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-127","question":"A bond priced at ₹1,040 has a modified duration of 6.5. If yields rise by 50 basis points, what is the approximate new price (ignoring convexity)?","options":["₹1,006.20","₹1,073.80","₹972.40","₹1,036.75"],"answer":0,"explanation":"%ΔP ≈ −D_mod × Δy = −6.5 × 0.005 = −3.25%. New price ≈ 1,040 × 0.9675 = ₹1,006.20. A rise in yields lowers the price; ₹972.40 uses a 1% move.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-128","question":"A 3-year zero-coupon bond with face value ₹10,000 sells for ₹7,938.32. What is its yield to maturity?","options":["8.66%","25.97%","7.70%","8.00%"],"answer":3,"explanation":"(10,000/7,938.32)^(1/3) − 1 = 1.25971^(1/3) − 1 = 8.00%. 8.66% is the simple annual average (25.97%/3); 25.97% is the total 3-year return.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-129","question":"A 5-year, 6% annual-coupon bond (face ₹1,000) is bought at ₹920.15 to yield 8%. If its yield is still 8% one year later, what is the one-year holding-period return?","options":["6.00%","8.00%","6.52%","1.48%"],"answer":1,"explanation":"Next year's price (4 years left at 8%) = ₹933.76. HPR = [60 + (933.76 − 920.15)]/920.15 = 8.00%. With an unchanged yield, a bond's one-year return equals its YTM: the current yield (6.52%) plus the pull towards par (1.48%).","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-130","question":"A convertible bond can be exchanged for 25 shares now trading at ₹44 each. Its straight-bond value is ₹980. What is the minimum price at which it should trade?","options":["₹980","₹1,040","₹2,080","₹1,100"],"answer":3,"explanation":"Conversion value = 25 × 44 = ₹1,100. A convertible is worth at least the higher of its straight value (₹980) and conversion value (₹1,100), otherwise arbitrageurs would buy and convert.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-131","question":"A company has just paid a dividend of ₹3. Dividends will grow at 8% a year forever and investors require 14%. What is the share's intrinsic value?","options":["₹54.00","₹50.00","₹23.14","₹58.32"],"answer":0,"explanation":"D₁ = 3 × 1.08 = 3.24. P₀ = D₁/(k − g) = 3.24/0.06 = ₹54. ₹50 uses D₀; ₹58.32 grows the dividend one year too many.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-132","question":"A firm has just paid ₹2 a share. Dividends will grow 20% a year for the next 2 years and 5% a year after that. With a 12% required return, what is the share worth today?","options":["₹35.19","₹37.24","₹38.88","₹30.00"],"answer":2,"explanation":"D₁ = 2.40, D₂ = 2.88, D₃ = 2.88 × 1.05 = 3.024. P₂ = D₃/(k − g) = 3.024/0.07 = 43.20. P₀ = 2.40/1.12 + (2.88 + 43.20)/1.12² = 2.143 + 36.735 = ₹38.88. Discounting P₂ three years is the classic timing error; using D₂ instead of D₃ in P₂ gives ₹37.24.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-133","question":"A company pays out 40% of earnings, grows at 7% a year forever and has a 12% cost of equity. What is its justified P/E on NEXT year's earnings?","options":["8.56","3.33","8.00","20.00"],"answer":2,"explanation":"P₀ = D₁/(k − g) = 0.4 E₁/0.05 → P₀/E₁ = 0.4/0.05 = 8.0. On trailing earnings it would be 8 × 1.07 = 8.56. 20 ignores the payout ratio.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-134","question":"A share trades at ₹125. Next year's EPS is ₹10 and the cost of equity is 12%. What is the present value of growth opportunities (PVGO) embedded in the price?","options":["₹83.33","₹41.67","₹115.00","₹13.33"],"answer":1,"explanation":"No-growth value = E₁/k = 10/0.12 = ₹83.33. PVGO = 125 − 83.33 = ₹41.67, about a third of the price.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-135","question":"Comparable companies trade at 8× EV/EBITDA. Your target has EBITDA of ₹50 crore, debt of ₹120 crore, cash of ₹20 crore and 10 crore shares. What value per share does the multiple imply?","options":["₹40.00","₹28.00","₹26.00","₹30.00"],"answer":3,"explanation":"EV = 8 × 50 = ₹400 crore. Equity = EV − debt + cash = 400 − 120 + 20 = ₹300 crore → ₹30 a share. ₹40 forgets debt; ₹28 forgets cash; ₹26 subtracts cash instead of adding it.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-136","question":"A company's EPS is ₹12 and similar companies trade at a P/E of 15. What price does relative valuation suggest?","options":["₹180","₹27","₹0.80","₹1,800"],"answer":0,"explanation":"Relative valuation applies the peers' multiple to the company's earnings: Price = EPS × P/E = 12 × 15 = ₹180. ₹0.80 wrongly divides EPS by the P/E, ₹27 adds the two, and ₹1,800 slips a zero.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-137","question":"A company's shareholders' equity is ₹500 crore, it has 25 crore shares and the share price is ₹60. What is its price-to-book ratio?","options":["3.0","0.33","20.0","12.0"],"answer":0,"explanation":"Book value per share = 500/25 = ₹20; P/B = 60/20 = 3.0. 0.33 is the inverse; 20 is the book value per share.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-138","question":"Next year's free cash flow to equity is expected to be ₹40 crore, growing at 6% a year forever. The cost of equity is 14% and there are 5 crore shares. What is the value per share?","options":["₹106","₹57.14","₹100","₹50"],"answer":2,"explanation":"Equity value = FCFE₁/(Ke − g) = 40/0.08 = ₹500 crore → 500/5 = ₹100 a share. ₹106 grows the already-forward FCFE again; ₹57.14 ignores growth (40/0.14/5).","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-139","question":"Next year's free cash flow to the firm is ₹60 crore, growing at 5% forever. WACC is 11%, debt is ₹300 crore and there are 20 crore shares. What is the equity value per share?","options":["₹50.00","₹35.00","₹37.50","₹12.27"],"answer":1,"explanation":"Enterprise value = FCFF₁/(WACC − g) = 60/0.06 = ₹1,000 crore. Equity = 1,000 − 300 = ₹700 crore → ₹35 a share. ₹50 forgets to deduct debt; ₹37.50 grows the forward FCFF again (63/0.06); ₹12.27 ignores growth.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-140","question":"An investor puts 60% of her money in a stock expected to return 15% and 40% in a stock expected to return 10%. What is the portfolio's expected return?","options":["12.5%","12.0%","25.0%","13.0%"],"answer":3,"explanation":"Expected return = 0.6 × 15% + 0.4 × 10% = 9% + 4% = 13%. 12.5% is the simple average.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-141","question":"A stock returns 25% in a boom (probability 0.3), 12% in a normal year (0.5) and −5% in a recession (0.2). What is its expected return?","options":["10.67%","12.5%","14.5%","16.5%"],"answer":1,"explanation":"E(R) = 0.3 × 25 + 0.5 × 12 + 0.2 × (−5) = 7.5 + 6 − 1 = 12.5%. 10.67% is the unweighted average; 14.5% ignores the sign of the recession return.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-142","question":"For a stock with returns of 25%, 12% and −5% with probabilities 0.3, 0.5 and 0.2 (expected return 12.5%), what is the standard deviation of returns?","options":["1.08%","12.42%","6.01%","10.40%"],"answer":3,"explanation":"Variance = 0.3(12.5)² + 0.5(0.5)² + 0.2(17.5)² = 46.875 + 0.125 + 61.25 = 108.25 (%²). σ = √108.25 = 10.40%. Ignoring the probabilities gives 12.42%.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-143","question":"A portfolio holds 60% in asset A (σ = 20%) and 40% in asset B (σ = 10%); their correlation is 0.3. What is the portfolio's standard deviation?","options":["16.00%","12.65%","13.74%","13.21%"],"answer":2,"explanation":"σp² = 0.6²(20²) + 0.4²(10²) + 2(0.6)(0.4)(0.3)(20)(10) = 144 + 16 + 28.8 = 188.8; σp = 13.74%. 16% (the weighted average) holds only if ρ = 1; 12.65% assumes ρ = 0.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-144","question":"Two assets have standard deviations of 20% (A) and 10% (B) and are uncorrelated. What weight in A gives the minimum-variance portfolio?","options":["20%","33.3%","80%","50%"],"answer":0,"explanation":"With ρ = 0, w_A = σ_B²/(σ_A² + σ_B²) = 100/(400 + 100) = 20%. 33.3% uses standard deviations instead of variances; 80% is the weight in B.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-145","question":"A portfolio holds 40% in a stock with beta 1.5, 35% in a stock with beta 0.8 and 25% in a stock with beta 1.2. What is the portfolio beta?","options":["1.17","1.18","1.50","3.50"],"answer":1,"explanation":"Portfolio beta = 0.4 × 1.5 + 0.35 × 0.8 + 0.25 × 1.2 = 0.60 + 0.28 + 0.30 = 1.18. 1.17 is the simple average of the three betas.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-146","question":"Fund X returned 15% with a standard deviation of 20%; Fund Y returned 12% with a standard deviation of 12%. The risk-free rate is 6%. On a risk-adjusted (Sharpe) basis:","options":["X is better: excess return 9% vs 6%","X is better because its return is higher","Y is better: Sharpe 0.50 vs 0.45","They are equal: Sharpe 0.45 for both"],"answer":2,"explanation":"Sharpe = (Rp − Rf)/σp. X: (15 − 6)/20 = 0.45. Y: (12 − 6)/12 = 0.50. Y earns more excess return per unit of total risk.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-147","question":"A fund earned 16% with a beta of 1.2. The risk-free rate was 6% and the market returned 13%. What is its Jensen's alpha?","options":["+3.0%","−1.6%","+2.0%","+1.6%"],"answer":3,"explanation":"CAPM return = 6% + 1.2 × (13% − 6%) = 14.4%. Alpha = 16% − 14.4% = +1.6%. +3.0% compares the fund with the market return without adjusting for beta.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-148","question":"An analyst expects a stock to return 15%. Its beta is 1.4, the risk-free rate is 5% and the market return is 12%. Relative to the security market line, the stock is:","options":["Undervalued: required return 14.8% is below the expected 15%","Overvalued: required return 21.8% exceeds the expected 15%","Fairly valued: expected return equals the market return plus 3%","Overvalued: its beta is above 1"],"answer":0,"explanation":"Required = 5% + 1.4 × 7% = 14.8%. The expected 15% plots above the SML, so the stock offers more than it needs to: it is undervalued (buy). 21.8% wrongly uses 1.4 × 12%.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-149","question":"The covariance between a stock's returns and the market's returns is 0.024, and the market's standard deviation is 20%. What is the stock's beta?","options":["0.12","1.67","0.60","0.30"],"answer":2,"explanation":"β = Cov(i, m)/σm² = 0.024/0.04 = 0.60. Dividing by σm (0.20) instead of σm² gives 0.12.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-150","question":"A stock has a total standard deviation of 30% and a beta of 1.2; the market's standard deviation is 20%. What share of the stock's total variance is systematic?","options":["64%","80%","36%","120%"],"answer":0,"explanation":"Systematic variance = β²σm² = 1.44 × 400 = 576; total variance = 30² = 900. Share = 576/900 = 64% (the remaining 36% is diversifiable). 80% compares standard deviations (24/30) instead of variances.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-151","question":"When a company sells its shares to the public for the first time through an IPO, the transaction takes place in the:","options":["Secondary market","Money market","Derivatives market","Primary market"],"answer":3,"explanation":"New securities issued by the company (IPO, FPO, rights issue) are sold in the primary market; the money goes to the issuer. Later trading among investors happens in the secondary market.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-152","question":"In a book-built IPO with a price band, a retail investor who bids at the 'cut-off' price is agreeing to:","options":["Buy only at the lowest price quoted in the price band","Buy at whatever final issue price is set within the band","Buy at the price at which the shares list on the exchange","Sell the shares on listing day at the cut-off price"],"answer":1,"explanation":"Bidding at cut-off means accepting the final price set after the book is built; the investor blocks money at the upper end of the band and any excess is released.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-153","question":"Which statements correctly contrast futures with forwards? I. Futures are standardised and exchange-traded. II. Futures are marked to market daily. III. Forwards carry more counterparty risk than exchange-traded futures.","options":["I and II only","I, II and III","I and III only","II only"],"answer":1,"explanation":"Futures are standardised, cleared through a clearing corporation and settled daily through margins, which nearly removes counterparty risk. Forwards are private OTC contracts settled at maturity, so default risk remains.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-154","question":"An investor buys a call option with a strike price of ₹500 for a premium of ₹20. At expiry the share is at ₹560. What is the profit per share?","options":["₹60","₹80","₹40","−₹20"],"answer":2,"explanation":"Payoff = max(560 − 500, 0) = ₹60; profit = 60 − 20 = ₹40. ₹60 ignores the premium paid.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-155","question":"An investor buys a put with a strike of ₹300 for a premium of ₹15. What are the break-even price and the profit if the share ends at ₹270?","options":["Break-even ₹315; profit ₹30","Break-even ₹285; profit ₹30","Break-even ₹315; loss ₹15","Break-even ₹285; profit ₹15"],"answer":3,"explanation":"A long put breaks even at strike − premium = 300 − 15 = ₹285. At ₹270 the payoff is 300 − 270 = 30, so profit = 30 − 15 = ₹15.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-156","question":"A trader writes (sells) a call with a strike of ₹1,000 for a premium of ₹40. At expiry the underlying is at ₹1,100. What is the writer's profit or loss?","options":["Loss of ₹60","Profit of ₹40","Loss of ₹100","Profit of ₹60"],"answer":0,"explanation":"The buyer exercises: the writer pays 1,100 − 1,000 = ₹100 but kept the ₹40 premium, so net loss = ₹60. A call writer's loss is unlimited as the price rises.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-157","question":"A trader buys a call and a put on the same share, both with strike ₹200, for premiums of ₹12 and ₹8. What are the break-even prices and the profit if the share ends at ₹230?","options":["Break-evens ₹188 and ₹212; profit ₹18","Break-evens ₹180 and ₹220; profit ₹10","Break-evens ₹180 and ₹220; profit ₹30","Break-evens ₹192 and ₹212; profit ₹10"],"answer":1,"explanation":"Long straddle cost = 12 + 8 = ₹20, so break-evens are 200 ± 20 = ₹180 and ₹220. At ₹230 the call pays 30, the put expires worthless: profit = 30 − 20 = ₹10.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-158","question":"A trader buys a ₹100-strike call for ₹8 and sells a ₹110-strike call on the same share and expiry for ₹3. What are the maximum profit and the break-even price?","options":["Maximum profit ₹10; break-even ₹105","Maximum profit ₹5; break-even ₹108","Unlimited profit; break-even ₹105","Maximum profit ₹5; break-even ₹105"],"answer":3,"explanation":"Bull call spread: net debit = 8 − 3 = ₹5. Maximum payoff is the strike gap, 110 − 100 = 10, so maximum profit = 10 − 5 = ₹5 (at ₹110 or above). Break-even = lower strike + net debit = ₹105.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-159","question":"A trader buys one futures lot of 500 units at ₹1,200. Initial margin is 10% of contract value and maintenance margin is 75% of the initial margin. Next day the price settles at ₹1,150. How much variation margin must he deposit?","options":["₹25,000","₹10,000","₹0","₹15,000"],"answer":0,"explanation":"Initial margin = 10% × 500 × 1,200 = ₹60,000; maintenance = ₹45,000. MTM loss = 500 × 50 = ₹25,000, leaving ₹35,000, below maintenance. He must restore the account to the initial ₹60,000, i.e. deposit ₹25,000. ₹10,000 only tops up to the maintenance level.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-160","question":"A share trades at ₹2,000 and will pay a dividend of ₹40 in exactly one year. The risk-free rate is 9% a year (annual compounding). What is the fair 1-year forward price?","options":["₹2,180","₹2,220","₹2,140","₹1,960"],"answer":2,"explanation":"F = S(1 + r) − FV of income = 2,000 × 1.09 − 40 = 2,180 − 40 = ₹2,140. ₹2,180 ignores the dividend the forward buyer will not receive; ₹2,220 adds it.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-161","question":"A European call on a non-dividend share costs ₹8. The share price is ₹100, the strike ₹105, time to expiry 1 year and the risk-free rate 5% (annual compounding). By put–call parity, what should the matching put cost?","options":["₹13.00","₹3.00","₹5.00","₹8.00"],"answer":3,"explanation":"C + K/(1 + r) = P + S → P = 8 + 105/1.05 − 100 = 8 + 100 − 100 = ₹8. ₹13 forgets to discount the strike.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-162","question":"A call with a strike of ₹450 trades at a premium of ₹42 when the share is at ₹480. What are its intrinsic value and time value?","options":["Intrinsic ₹42; time value ₹0","Intrinsic ₹12; time value ₹30","Intrinsic ₹30; time value ₹12","Intrinsic ₹0; time value ₹42"],"answer":2,"explanation":"Intrinsic value of a call = max(S − K, 0) = 480 − 450 = ₹30. Time value = premium − intrinsic = 42 − 30 = ₹12.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-163","question":"A share trades at ₹470. Which statements are true? I. A call with strike ₹500 is out of the money. II. A put with strike ₹500 is in the money. III. That put's intrinsic value is ₹30.","options":["I and II only","I, II and III","II and III only","I only"],"answer":1,"explanation":"A call is in the money when S > K and a put when S < K. With S = 470 < 500 the call is out of the money and the put in the money, with intrinsic value 500 − 470 = ₹30.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-164","question":"The spot rate is ₹80.00 per US dollar. One-year interest rates are 7% in India and 4% in the US. By covered interest parity, what is the 1-year forward rate?","options":["₹82.31/$","₹82.40/$","₹77.76/$","₹80.00/$"],"answer":0,"explanation":"F = S × (1 + r_INR)/(1 + r_USD) = 80 × 1.07/1.04 = ₹82.31. The higher-interest currency trades at a forward discount. ₹82.40 is the approximation 80 × (1 + 3%); ₹77.76 inverts the ratio.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-165","question":"A company with a floating-rate loan enters a plain-vanilla interest rate swap in which it pays fixed and receives floating. It gains from the swap if:","options":["Floating rates fall below the fixed swap rate","The rupee depreciates","The swap's notional principal is exchanged at maturity","Floating rates rise above the fixed swap rate"],"answer":3,"explanation":"Paying fixed and receiving floating converts the floating loan into a fixed one. If floating rates rise, the floating leg it receives grows while its fixed payment stays the same. Notional principal is not exchanged in an interest rate swap.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-166","question":"What is the purpose of a green-shoe option in a public issue?","options":["It allows promoters to sell their entire stake on the listing day itself","It lets retail investors withdraw bids after the issue closes","Over-allotment lets a stabilising agent support the post-listing price","It guarantees investors a minimum listing-day return on shares"],"answer":2,"explanation":"Over-allotted shares create a short position; if the price falls below the issue price, the stabilising agent buys shares in the market, supporting the price. If the price rises, the company issues the extra shares instead.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-167","question":"A share trades at ₹120 cum-rights. The company offers 1 new share for every 4 held at ₹80. What are the theoretical ex-rights price and the value of the right attached to each existing share?","options":["₹112 and ₹8","₹112 and ₹32","₹104 and ₹16","₹110 and ₹10"],"answer":0,"explanation":"TERP = (4 × 120 + 1 × 80)/5 = 560/5 = ₹112. Value of a right per existing share = 120 − 112 = ₹8 (equivalently (112 − 80)/4). ₹32 is the gain per NEW share.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-168","question":"A fund manager holds a ₹50 lakh equity portfolio with a beta of 1.2. Index futures trade at 20,000 with a lot size of 50. How many futures contracts should she sell to hedge the portfolio fully?","options":["5 contracts","6 contracts","60 contracts","4 contracts"],"answer":1,"explanation":"Contract value = 20,000 × 50 = ₹10 lakh. Contracts = β × portfolio value/contract value = 1.2 × 50/10 = 6. Ignoring beta gives 5.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-169","question":"A miller wants to hedge 1,000 tonnes of wheat. Monthly changes in the spot price have σ = 2%, in the futures price σ = 2.5%, and their correlation is 0.9. Each futures contract covers 10 tonnes. How many contracts give the minimum-variance hedge?","options":["100 contracts","90 contracts","72 contracts","80 contracts"],"answer":2,"explanation":"Hedge ratio h* = ρ × σS/σF = 0.9 × 2/2.5 = 0.72. Contracts = 0.72 × 1,000/10 = 72. 100 is a naive one-for-one hedge; 80 ignores the correlation (2/2.5 = 0.8).","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-170","question":"In India's capital market, which entity holds investors' securities in electronic (dematerialised) form?","options":["A depository, through its depository participants","The stock exchange's trading member (broker)","The registrar and transfer agent to the issue","The merchant banker that managed the public issue"],"answer":0,"explanation":"Depositories hold securities in electronic book-entry form; investors access them through depository participants (banks, brokers) where their demat accounts are opened.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-171","question":"In exchange-traded options, which party is normally required to deposit margin, and why?","options":["The buyer, because the buyer can lose more than the premium","Both parties equally, because both face unlimited losses","Neither party, because premiums are paid upfront in full","The writer, who alone carries an open obligation"],"answer":3,"explanation":"The buyer's maximum loss is the premium already paid, so no further margin is needed. The writer must perform if the option is exercised and can lose much more, so the clearing house collects margin from the writer.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-172","question":"An investor owns a share bought at ₹500 and writes a call on it with a strike of ₹540 for ₹15 (covered call). At expiry the share is at ₹600. What is her total profit per share?","options":["₹115","₹55","₹100","₹15"],"answer":1,"explanation":"The call is exercised, so she sells at ₹540: share gain = 540 − 500 = 40, plus the ₹15 premium = ₹55. Her upside is capped; ₹115 ignores that the share is called away.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-173","question":"An investor buys a share at ₹400 and a put with a strike of ₹380 for ₹10 (protective put). What is his maximum possible loss per share?","options":["₹10","₹20","₹410","₹30"],"answer":3,"explanation":"Below ₹380 the put offsets further falls, so the worst case is selling at 380: loss on share = 20, plus premium 10 = ₹30.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-174","question":"A 91-day Treasury bill with face value ₹100 is bought for ₹98.25. What is its annualised yield (365-day basis, simple)?","options":["7.02%","1.75%","7.14%","7.05%"],"answer":2,"explanation":"Yield = [(100 − 98.25)/98.25] × 365/91 = 1.7812% × 4.011 = 7.14%. 7.02% is the discount yield on face value; 1.75% is the 91-day return unannualised.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-175","question":"Match each money-market instrument with its feature. (p) Treasury bill, (q) Commercial paper, (r) Certificate of deposit, (s) Call money. Features: (1) Unsecured short-term promissory note issued by a highly rated company; (2) Overnight inter-bank borrowing and lending; (3) Discounted short-term government security; (4) Negotiable time deposit issued by a bank.","options":["p-1, q-3, r-4, s-2","p-3, q-1, r-4, s-2","p-3, q-4, r-1, s-2","p-3, q-1, r-2, s-4"],"answer":1,"explanation":"T-bills are discounted government securities (3); CP is an unsecured note of a highly rated corporate (1); a CD is a negotiable bank time deposit (4); call money is overnight inter-bank lending (2).","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-176","question":"A bank earns ₹900 crore of interest, pays ₹600 crore of interest and has average earning assets of ₹10,000 crore. What is its net interest margin?","options":["3.0%","9.0%","6.0%","33.3%"],"answer":0,"explanation":"NIM = (interest earned − interest paid)/average earning assets = 300/10,000 = 3%. 9% is the yield on assets; 33.3% divides net interest by interest income.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-177","question":"A bank has current deposits of ₹2,000 crore, savings deposits of ₹5,000 crore and term deposits of ₹13,000 crore. What is its CASA ratio?","options":["53.8%","35%","25%","65%"],"answer":1,"explanation":"CASA ratio = (current + savings)/total deposits = 7,000/20,000 = 35%. 53.8% divides by term deposits only; 65% is the term-deposit share.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-178","question":"A bank's gross advances are ₹10,000 crore, gross NPAs ₹600 crore and NPA provisions ₹360 crore. What is its net NPA ratio?","options":["2.40%","6.00%","2.49%","3.60%"],"answer":2,"explanation":"Net NPA = 600 − 360 = ₹240 crore. Net advances = 10,000 − 360 = ₹9,640 crore. Net NPA ratio = 240/9,640 = 2.49%. 2.40% divides by gross advances; 6% is the gross NPA ratio.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-179","question":"A bank has gross NPAs of ₹600 crore and has made provisions of ₹360 crore against them. What is its provision coverage ratio?","options":["60%","40%","3.6%","166.7%"],"answer":0,"explanation":"PCR = provisions/gross NPAs = 360/600 = 60%. A higher PCR means more of the bad loans are already provided for. 40% is the unprovided share.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-180","question":"A bank has Tier 1 capital of ₹800 crore and Tier 2 capital of ₹300 crore. Its assets: corporate loans ₹10,000 crore (risk weight 100%), home loans ₹4,000 crore (50%) and government securities ₹6,000 crore (0%). What is its capital-to-risk-weighted-assets ratio?","options":["5.50%","6.67%","7.86%","9.17%"],"answer":3,"explanation":"RWA = 10,000 × 1 + 4,000 × 0.5 + 6,000 × 0 = ₹12,000 crore. CRAR = (800 + 300)/12,000 = 9.17%. 5.50% divides by total assets (₹20,000 crore); 6.67% is the Tier 1 ratio only.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-181","question":"Match the Basel framework pillars with their content. (p) Pillar 1, (q) Pillar 2, (r) Pillar 3. Content: (1) Disclosure requirements that allow market discipline; (2) Minimum capital for credit, market and operational risk; (3) Supervisory review of the bank's internal capital assessment.","options":["p-1, q-2, r-3","p-2, q-3, r-1","p-3, q-2, r-1","p-2, q-1, r-3"],"answer":1,"explanation":"Pillar 1 sets minimum capital requirements; Pillar 2 is the supervisory review process (including the bank's own capital assessment); Pillar 3 is market discipline through disclosure.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-182","question":"A bank receives fresh deposits of ₹1,000 crore. It must keep 4% as cash reserves with the central bank and invest 18% in approved liquid securities. Ignoring other uses, how much is available for lending?","options":["₹960 crore","₹820 crore","₹220 crore","₹780 crore"],"answer":3,"explanation":"Pre-emptions = 4% + 18% = 22% of deposits = ₹220 crore. Lendable funds = 1,000 − 220 = ₹780 crore. ₹960 crore deducts only the cash reserve; ₹220 crore is the amount locked up.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-183","question":"A bank funds itself with deposits of ₹8,000 crore at 5.5% and borrowings of ₹1,000 crore at 7%. It holds advances of ₹6,000 crore yielding 9.5% and investments of ₹3,000 crore yielding 7%. What are its net interest income and NIM on earning assets?","options":["₹270 crore and 2.70%","₹780 crore and 8.67%","₹270 crore and 3.00%","₹200 crore and 2.22%"],"answer":2,"explanation":"Interest income = 6,000 × 9.5% + 3,000 × 7% = 570 + 210 = ₹780 crore. Interest expense = 8,000 × 5.5% + 1,000 × 7% = 440 + 70 = ₹510 crore. NII = ₹270 crore; NIM = 270/9,000 = 3.00%. 2.70% divides by an assumed ₹10,000 crore.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-184","question":"Assertion (A): A bank that funds 20-year fixed-rate home loans mainly with one-year deposits is hurt when interest rates rise. Reason (R): Its liabilities reprice faster than its assets, so its cost of funds rises while its loan yields stay fixed.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A. The maturity/repricing mismatch squeezes net interest income when rates rise — the core of asset–liability management.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-185","question":"A bank has rate-sensitive assets of ₹5,000 crore and rate-sensitive liabilities of ₹6,500 crore over the next year. If all rates rise by 1 percentage point, what is the approximate change in its net interest income?","options":["Rises by ₹15 crore","Falls by ₹115 crore","Falls by ₹15 crore","Rises by ₹50 crore"],"answer":2,"explanation":"Repricing gap = RSA − RSL = 5,000 − 6,500 = −₹1,500 crore. ΔNII ≈ gap × Δr = −1,500 × 1% = −₹15 crore. A negative gap means more liabilities than assets reprice, so rising rates hurt.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-186","question":"A bank has net profit of ₹1,200 crore, total assets of ₹1,00,000 crore and equity of ₹8,000 crore. What are its ROA and ROE?","options":["ROA 12%; ROE 1.5%","ROA 1.2%; ROE 15%","ROA 1.2%; ROE 1.2%","ROA 8%; ROE 15%"],"answer":1,"explanation":"ROA = 1,200/1,00,000 = 1.2%. ROE = 1,200/8,000 = 15%. ROE = ROA × equity multiplier = 1.2% × 12.5. Banks earn high ROE from low ROA through high leverage.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-187","question":"A company's net profit margin is 8%, asset turnover 1.5 times and equity multiplier 2. If it raises its equity multiplier to 2.5 with margin and turnover unchanged, what happens to ROE?","options":["It rises from 24% to 30%","It rises from 11.5% to 12%","It rises from 24% to 25%","It stays at 24%"],"answer":0,"explanation":"DuPont: ROE = margin × turnover × equity multiplier = 8% × 1.5 × 2 = 24%; with a multiplier of 2.5, ROE = 8% × 1.5 × 2.5 = 30%. Adding the factors (11.5%) is wrong.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-188","question":"A firm pays out 40% of its earnings and wants to grow at 12% a year without issuing new equity or changing its leverage. What return on equity must it earn?","options":["30%","12%","18%","20%"],"answer":3,"explanation":"Sustainable growth g = ROE × retention. Retention = 60%, so ROE = 12%/0.6 = 20%. 30% divides by the payout ratio instead of the retention ratio.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-189","question":"A firm with 40% debt (pre-tax cost 10%) and 60% equity (cost 16%) pays tax at 30%. A project of average risk costs ₹50 lakh and returns ₹15 lakh a year for 5 years. Which conclusion is correct?","options":["Reject: at the 16% cost of equity the NPV is about −₹0.89 lakh","Accept: at a WACC of 13.6% the NPV is about ₹2.00 lakh","Accept: at a WACC of 12.4% the NPV is about ₹3.54 lakh","Reject: the payback of 3.33 years exceeds the 3-year norm"],"answer":2,"explanation":"WACC = 0.6 × 16% + 0.4 × 10% × 0.7 = 9.6% + 2.8% = 12.4%. NPV = 15 × annuity factor(12.4%, 5) − 50 = 15 × 3.5693 − 50 ≈ ₹3.54 lakh > 0, so accept. Discounting at the cost of equity wrongly rejects it; 13.6% forgets the tax shield on debt.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-190","question":"A company's EBIT is ₹160 crore, its tax rate 25%, capital employed ₹800 crore and WACC 12%. What is its economic value added (EVA)?","options":["₹24 crore","₹64 crore","₹120 crore","₹96 crore"],"answer":0,"explanation":"NOPAT = 160 × (1 − 0.25) = ₹120 crore. Capital charge = 12% × 800 = ₹96 crore. EVA = 120 − 96 = ₹24 crore. ₹64 crore uses pre-tax EBIT.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-191","question":"A bank lends ₹10 lakh at 10% a year but requires the borrower to keep a compensating balance of 20% of the loan in a non-interest account. What is the effective cost of the loan?","options":["10.00%","12.50%","12.00%","8.00%"],"answer":1,"explanation":"Interest = ₹1 lakh; usable funds = 10 − 2 = ₹8 lakh. Effective cost = 1/8 = 12.5%. 12% simply adds 20% of 10%.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-192","question":"A one-year loan of ₹10 lakh carries 12% interest deducted in advance (discount basis) and also requires a 10% compensating balance. What is the effective annual cost?","options":["13.64%","13.33%","12.00%","15.38%"],"answer":3,"explanation":"Usable funds = 10 − 1.2 (interest deducted) − 1.0 (compensating balance) = ₹7.8 lakh. Effective cost = 1.2/7.8 = 15.38%. 13.64% allows only for the discount; 13.33% allows only for the balance.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-193","question":"Which statements about bond price sensitivity to interest rates are correct? I. Other things equal, longer maturity means greater sensitivity. II. Other things equal, a higher coupon means greater sensitivity. III. A zero-coupon bond's Macaulay duration equals its maturity.","options":["I and III only","I, II and III","I and II only","II and III only"],"answer":0,"explanation":"Longer maturity raises duration (I). A higher coupon returns more cash earlier, LOWERING duration and sensitivity, so II is false. A zero has a single cash flow at maturity, so its duration equals maturity (III).","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-194","question":"A mutual fund scheme has assets of ₹520 crore, liabilities of ₹20 crore and 40 crore units outstanding. What is its NAV per unit?","options":["₹13.00","₹12.50","₹12.00","₹10.00"],"answer":1,"explanation":"NAV = (assets − liabilities)/units = (520 − 20)/40 = ₹12.50. ₹13.00 ignores liabilities.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-195","question":"An investor puts ₹6,000 into a fund every month for three months at NAVs of ₹20, ₹24 and ₹30. What is her average cost per unit?","options":["₹24.67","₹25.00","₹24.00","₹30.00"],"answer":2,"explanation":"Units = 300 + 250 + 200 = 750 for ₹18,000, so average cost = 18,000/750 = ₹24.00, below the average NAV of ₹24.67. Equal rupee amounts buy more units when prices are low (rupee-cost averaging).","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-196","question":"₹1 lakh invested in a fund becomes ₹1.5 lakh after one year and ₹1.2 lakh after two years. Which statement is correct?","options":["Both the average annual return and the CAGR are 15%","The CAGR is 10% while the average annual return is 9.54%","The CAGR is 15% because the gain was earned in year 1","Average annual return is 15% but the CAGR is only 9.54%"],"answer":3,"explanation":"Yearly returns are +50% and −20%: arithmetic average = 15%. CAGR = (1.2/1.0)^(1/2) − 1 = 9.54%. The arithmetic average overstates the compound return whenever returns are volatile; 10% is the simple (20%/2) annual gain.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-197","question":"A bank's exposure to a borrower is ₹50 crore. The probability of default over the year is 2% and the loss given default is 45%. What is the expected credit loss?","options":["₹1 crore","₹22.5 crore","₹45 lakh","₹4.5 crore"],"answer":2,"explanation":"EL = PD × LGD × EAD = 0.02 × 0.45 × 50 crore = ₹0.45 crore = ₹45 lakh. ₹1 crore ignores recoveries (assumes LGD = 100%); ₹22.5 crore omits the default probability.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-198","question":"A stock has a beta of 1.25; the risk-free rate is 6% and the market risk premium 8%. It trades at ₹75 and next year's dividend is expected to be ₹6. What constant growth rate is the market implying?","options":["10.0%","6.0%","24.0%","8.0%"],"answer":3,"explanation":"Ke = 6% + 1.25 × 8% = 16%. From P₀ = D₁/(Ke − g): g = Ke − D₁/P₀ = 16% − 6/75 = 16% − 8% = 8%.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-199","question":"A firm's target debt–equity ratio is 0.5. Its cost of equity is 15%, its pre-tax cost of debt 9% and its tax rate 30%. What is its WACC?","options":["12.10%","10.65%","13.00%","9.17%"],"answer":0,"explanation":"D/E = 0.5 means D/V = 0.5/1.5 = 1/3 and E/V = 2/3. WACC = (2/3)(15%) + (1/3)(9% × 0.7) = 10% + 2.1% = 12.10%. Treating 0.5 as the debt weight gives 10.65%; ignoring tax gives 13.00%.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-200","question":"Assertion (A): A higher share of CASA deposits generally lowers a bank's cost of funds. Reason (R): Current accounts usually pay no interest and savings accounts pay lower rates than term deposits.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: cheap current and savings deposits pull down the average cost of deposits, which supports the bank's NIM.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-201","question":"A ₹40,00,000 home loan at 8.4% per annum is repaid by monthly EMIs over 20 years on a reducing balance. Roughly how much interest does the borrower pay over the life of the loan?","options":["₹42.70 lakh","₹67.20 lakh","₹43.92 lakh","₹82.70 lakh"],"answer":0,"explanation":"r = 0.7% a month, n = 240. EMI = P·r/[1 − (1 + r)⁻ⁿ] ≈ ₹34,460.18. Total paid = ₹34,460.18 × 240 ≈ ₹82.70 lakh, so interest ≈ ₹42.70 lakh. ₹67.20 lakh is flat interest on the full principal; ₹43.92 lakh assumes yearly instalments; ₹82.70 lakh is the total outgo including principal.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-202","question":"A ₹12,00,000 loan at 10% per annum is repaid in 120 equal monthly instalments (reducing balance). How much of the FIRST EMI goes towards principal (nearest rupee)?","options":["₹15,727","₹5,858","₹10,000","₹15,858"],"answer":1,"explanation":"EMI = 12,00,000 × (0.10/12)/[1 − (1 + 0.10/12)⁻¹²⁰] ≈ ₹15,858.09. First-month interest = 12,00,000 × 0.10/12 = ₹10,000. Principal = ₹15,858.09 − ₹10,000 ≈ ₹5,858. ₹15,727 is the principal in the LAST EMI, when almost no interest remains.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-203","question":"For the same ₹12,00,000, 10%, 120-month loan, how much of the 61st EMI is principal (nearest rupee)?","options":["₹9,719","₹10,000","₹9,638","₹7,929"],"answer":2,"explanation":"The principal part of the k-th EMI equals EMI ÷ (1 + r)^(n − k + 1), because it repays exactly the PV of that instalment. Here: ₹15,858.09 ÷ (1 + 0.10/12)⁶⁰ ≈ ₹9,638. Equivalently, the first principal component (₹5,858) grows by (1 + r) each month: ₹5,858 × (1 + r)⁶⁰ ≈ ₹9,638; compounding 61 times instead gives ₹9,719.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-204","question":"A borrower can afford an EMI of ₹25,000. The bank lends ₹15,00,000 at 9% per annum (monthly reducing balance). How many EMIs are needed (the last one may be smaller)?","options":["60","72","93","81"],"answer":3,"explanation":"Solve 15,00,000 = 25,000 × [1 − (1.0075)⁻ⁿ]/0.0075 → (1.0075)⁻ⁿ = 1 − 15,00,000 × 0.0075/25,000 = 0.55 → n = −ln(0.55)/ln(1.0075) ≈ 80.01, so 81 EMIs. 60 ignores interest altogether (15,00,000 ÷ 25,000).","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-205","question":"A ₹20,00,000 loan at 9% per annum for 20 years (monthly EMIs, reducing balance) has run for exactly 5 years (60 EMIs paid). The rate is now reset to 10.5% and the borrower keeps the EMI unchanged. Roughly how many EMIs now remain (round up)?","options":["228","180","258","210"],"answer":0,"explanation":"EMI = ₹17,994.52. Balance after 60 EMIs = PV of the remaining 180 EMIs at 0.75% = ₹17,74,141. At r = 0.875% a month: (1.00875)⁻ᵐ = 1 − ₹17,74,141 × 0.00875/₹17,994.52 → m ≈ 227.9, i.e. 228 EMIs (up from 180). Keeping 180 months would instead need a new EMI of about ₹19,611.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-206","question":"In a standard EMI loan on a reducing balance, what happens to the interest and principal components as the instalments are paid?","options":["Both components stay constant in every single instalment","Interest falls and principal rises, with the EMI unchanged","The interest component rises and the principal component falls","The EMI falls each month as interest is charged on less"],"answer":1,"explanation":"Interest each month is charged on the outstanding balance, which shrinks after every EMI. With the EMI fixed, a smaller interest part leaves a larger part for principal.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-207","question":"A company puts ₹50 lakh at the end of every year into a fund earning 8% compounded annually. What is the minimum number of whole years needed for the fund to reach ₹5 crore?","options":["10 years","7 years","8 years","9 years"],"answer":2,"explanation":"Need 50 lakh × [(1.08ⁿ − 1)/0.08] ≥ 5 crore → 1.08ⁿ ≥ 1 + 5,00,00,000 × 0.08/50,00,000 = 1.8 → n ≥ ln 1.8/ln 1.08 = 7.64. After 7 years the fund holds ₹4.46 crore; after 8 years ₹5.32 crore. 10 years ignores interest.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-208","question":"A firm will need ₹60 lakh in 6 years to replace a machine. It will deposit an equal amount at the end of every quarter in a fund earning 7% per annum compounded quarterly. What is the quarterly deposit (nearest rupee)?","options":["₹2,09,694","₹2,50,000","₹1,03,134","₹2,03,314"],"answer":3,"explanation":"Per-quarter rate 1.75%, 24 deposits. A = 60,00,000 × 0.0175/(1.0175²⁴ − 1) ≈ ₹2,03,314. Dividing the annual sinking-fund deposit by 4 gives ₹2,09,694; ₹2,50,000 ignores interest; using 7% per quarter is wrong.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-209","question":"Investors want a real return of 3% and expect inflation of 5%. What exact nominal rate satisfies the Fisher relation?","options":["8.15%","8.00%","2.00%","1.94%"],"answer":0,"explanation":"(1 + nominal) = (1 + real)(1 + inflation) = 1.03 × 1.05 = 1.0815, so nominal = 8.15%. 8% is the additive approximation that drops the cross term 0.03 × 0.05.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-210","question":"An investor in the 30% tax bracket earns 10% a year on a fixed deposit (interest fully taxable) while inflation is 6%. What is the exact after-tax real return?","options":["3.77%","0.94%","2.80%","1.00%"],"answer":1,"explanation":"After-tax nominal = 10% × 0.7 = 7%. Real = 1.07/1.06 − 1 = 0.94%. 3.77% is the pre-tax real return; 2.80% wrongly taxes only the real part (4% × 0.7); 1% is the rough 7 − 6.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-211","question":"A retiree wants to withdraw the equivalent of ₹6 lakh in today's money at the end of each of the next 20 years, with each withdrawal rising with inflation of 6% a year. Her fund earns 10% nominal. What corpus does she need today (₹ lakh, 2 decimals)?","options":["₹51.08 lakh","₹81.54 lakh","₹83.20 lakh","₹78.49 lakh"],"answer":2,"explanation":"First withdrawal = 6 lakh × 1.06 = ₹6.36 lakh, then growing 6%. Growing annuity: PV = 6.36/(0.10 − 0.06) × [1 − (1.06/1.10)²⁰] ≈ ₹83.20 lakh. This equals ₹6 lakh discounted as a level annuity at the exact real rate (1.10/1.06 − 1 = 3.77%). Ignoring inflation gives ₹51.08 lakh; using the approximate 4% real rate gives ₹81.54 lakh; starting the growing annuity at ₹6 lakh gives ₹78.49 lakh.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-212","question":"A firm can buy a ₹10 lakh machine (5-year life, straight-line depreciation, no salvage) with a loan, or lease it for ₹2.8 lakh a year paid at each year-end for 5 years. Tax rate 30%; pre-tax borrowing cost 10%. What is the net advantage of leasing (NAL), and what should it do?","options":["NAL ≈ ₹29,559; lease the machine","NAL ≈ ₹1,96,361; lease the machine","NAL ≈ −₹61,420; buy the machine","NAL ≈ −₹49,651; buy the machine"],"answer":3,"explanation":"Leasing saves the ₹10 lakh outlay but costs the after-tax rental (2.8 × 0.7 = ₹1.96 lakh) plus the lost depreciation tax shield (2 × 0.3 = ₹0.60 lakh) each year: ₹2.56 lakh. Discount at the after-tax cost of debt, 10% × 0.7 = 7%: 2.56 × 4.1002 = ₹10.50 lakh. NAL = 10 − 10.4965 ≈ −₹49,651 < 0, so buy. Discounting at 10% or forgetting the lost depreciation shield wrongly favours leasing.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-213","question":"For the same ₹10 lakh machine (5-year straight-line, no salvage, tax 30%, pre-tax borrowing cost 10%), what is the maximum year-end lease rental at which leasing is no worse than buying (nearest hundred rupees)?","options":["₹2,62,700","₹2,91,100","₹3,48,400","₹2,43,900"],"answer":0,"explanation":"Set NAL = 0: (0.7L + 0.60 lakh) × 4.1002 = ₹10 lakh → 0.7L + 60,000 = ₹2,43,891 → L ≈ ₹2,62,701. Using 10% instead of the 7% after-tax rate gives ₹2,91,100; ignoring the lost depreciation shield gives ₹3,48,400.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-214","question":"In a lease-versus-buy analysis, why are the lease cash flows normally discounted at the after-tax cost of borrowing rather than at the firm's WACC?","options":["Because lease rentals are not tax-deductible for the lessee firm at all","A lease displaces debt and its fixed cash flows carry debt-like risk","Because WACC already includes the lessor's profit margin","Because lease payments are paid in advance, which removes all risk"],"answer":1,"explanation":"Lease rentals and depreciation shields are contractual and fairly certain, and leasing displaces borrowing capacity. Their risk resembles the firm's debt, so the after-tax cost of debt is the consistent rate.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-215","question":"A firm will replace an old machine (tax book value ₹3 lakh, current sale value ₹2 lakh) with a new one costing ₹8 lakh. Tax rate 30%; the loss on sale is tax-deductible. What is the net initial outlay of the replacement?","options":["₹6,00,000","₹6,30,000","₹5,70,000","₹5,00,000"],"answer":2,"explanation":"Outlay = 8,00,000 − 2,00,000 sale proceeds − tax saved on the ₹1 lakh loss (30% × 1,00,000 = 30,000) = ₹5,70,000. ₹6,00,000 ignores tax; ₹6,30,000 treats the loss as taxable; ₹5,00,000 uses book value as if it were cash.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-216","question":"Continuing the replacement (net outlay ₹5.7 lakh): the new machine saves ₹2.5 lakh a year in pre-tax cash operating costs for 5 years. The new machine is depreciated straight-line over 5 years to zero; the old machine would have been depreciated ₹60,000 a year for 5 more years. Neither has salvage value. Tax 30%, cost of capital 10%. What is the NPV of replacing?","options":["₹2,75,345","₹3,77,697","₹93,388","₹2,07,111"],"answer":3,"explanation":"Incremental depreciation = 1,60,000 − 60,000 = 1,00,000. Incremental cash flow = 2,50,000 × 0.7 + 1,00,000 × 0.3 = ₹2,05,000. NPV = ₹2,05,000 × 3.7908 − 5,70,000 ≈ ₹2,07,111. Using the full new depreciation (forgetting the old machine's lost shield) gives ₹2,75,345.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-217","question":"A ₹10 lakh project lasts 5 years with no salvage and no taxes. It sells at ₹100 a unit with variable cost ₹60 and annual fixed cash costs of ₹1 lakh; the discount rate is 10%. What annual sales volume makes its NPV exactly zero (nearest unit)?","options":["9,095 units","7,500 units","2,500 units","6,595 units"],"answer":0,"explanation":"Required annual cash flow = 10,00,000 ÷ 3.7908 = ₹2,63,797. Units = (₹2,63,797 + 1,00,000) ÷ ₹40 contribution ≈ 9,095. 7,500 uses undiscounted payback of ₹2 lakh a year; 2,500 is accounting break-even ignoring the investment.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-218","question":"The same project expects 10,000 units a year (price ₹100, variable cost ₹60, fixed cash costs ₹1 lakh, investment ₹10 lakh, 5 years, 10%, no tax). By what percentage can the selling price fall, with volume unchanged, before NPV turns negative?","options":["9.05%","3.62%","3.76%","13.72%"],"answer":1,"explanation":"Base NPV = 3,00,000 × 3.7908 − 10,00,000 = ₹1,37,236. Break-even cash flow ₹2,63,797 = 10,000(P − 60) − 1,00,000 → P = ₹96.38, a fall of 3.62%. 9.05% is the tolerable fall in volume, which is larger because each lost unit costs only the ₹40 contribution while a price cut hits every rupee of revenue.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-219","question":"A project's NPV is ₹50 lakh in a boom (probability 0.3), ₹20 lakh in a normal year (0.5) and −₹40 lakh in a slump (0.2). What are its expected NPV and coefficient of variation?","options":["₹10 lakh; CV ≈ 3.13","₹17 lakh; CV ≈ 0.54","₹17 lakh; CV ≈ 1.84","₹33 lakh; CV ≈ 0.95"],"answer":2,"explanation":"E(NPV) = 0.3 × 50 + 0.5 × 20 + 0.2 × (−40) = ₹17 lakh. Variance = 0.3(33)² + 0.5(3)² + 0.2(−57)² = 981.0, σ ≈ ₹31.32 lakh. CV = σ/E = 1.84. ₹10 lakh is the simple average of the three scenarios; 0.54 inverts the ratio.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-220","question":"Discounted at the unlevered cost of equity, a project's base-case NPV is −₹2 crore. It will support ₹40 crore of permanent debt; the tax rate is 25% and debt issue costs are ₹0.5 crore. What is its adjusted present value (APV)?","options":["−₹2.5 crore","₹8.0 crore","₹0.0 crore","₹7.5 crore"],"answer":3,"explanation":"APV = base NPV + PV of tax shields − issue costs. For permanent debt, PV of shields = T × D = 0.25 × 40 = ₹10 crore. APV = −2 + 10 − 0.5 = ₹7.5 crore, so the financing side makes the project worthwhile.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-221","question":"A project's base-case NPV (all-equity, at 12%) is −₹3 crore. It is financed partly with a ₹50 crore, 5-year interest-only loan at 9%, repaid in full at the end of year 5. Tax rate 30%; interest tax shields are discounted at the cost of debt. What is the APV?","options":["₹2.25 crore","₹12.00 crore","₹1.87 crore","₹3.75 crore"],"answer":0,"explanation":"Annual interest = ₹4.5 crore; tax shield = 4.5 × 0.30 = ₹1.35 crore for 5 years. PV at 9% = 1.35 × 3.8897 = ₹5.25 crore. APV = −3 + 5.25 = ₹2.25 crore. T × D (₹15 crore) applies only to permanent debt; discounting shields at 12% gives ₹1.87 crore.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-222","question":"A company has EBIT of ₹200 crore, a 25% tax rate, depreciation of ₹40 crore, capital expenditure of ₹70 crore and an increase in net working capital of ₹15 crore. What is its free cash flow to the firm (FCFF)?","options":["₹120 crore","₹105 crore","₹135 crore","₹155 crore"],"answer":1,"explanation":"FCFF = EBIT(1 − t) + depreciation − capex − ΔNWC = 150 + 40 − 70 − 15 = ₹105 crore. ₹120 crore forgets the working-capital investment; ₹135 crore adds it instead of subtracting; ₹155 crore skips tax on EBIT before deducting capex and NWC.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-223","question":"A firm's FCFF is ₹105 crore. It pays interest of ₹30 crore (tax rate 25%) and raises net new borrowing of ₹20 crore during the year. What is its free cash flow to equity (FCFE)?","options":["₹95.0 crore","₹62.5 crore","₹102.5 crore","₹82.5 crore"],"answer":2,"explanation":"FCFE = FCFF − interest × (1 − t) + net borrowing = 105 − 30 × 0.75 + 20 = ₹102.5 crore. Deducting pre-tax interest gives ₹95 crore; subtracting the new borrowing gives ₹62.5 crore; ignoring it gives ₹82.5 crore.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-224","question":"A firm's FCFF is forecast at ₹100 crore, ₹110 crore and ₹121 crore for years 1–3, then to grow at 5% a year forever. Its WACC is 12%. What is its enterprise value today?","options":["₹1,416.6 crore","₹1,493.5 crore","₹4,728.6 crore","₹1,555.0 crore"],"answer":3,"explanation":"PV of years 1–3 = ₹263.1 crore. Terminal value at end of year 3 = 121 × 1.05/(0.12 − 0.05) = ₹1,815.0 crore; its PV = 1,815.0/1.12³ = ₹1,291.9 crore. EV ≈ ₹1,555.0 crore. Discounting the terminal value 4 years gives ₹1,416.6 crore; omitting the year-4 growth in TV gives ₹1,493.5 crore.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-225","question":"The spot rate is ₹83.00 per US dollar and the 6-month forward rate is ₹84.66. What is the annualised forward premium on the dollar?","options":["4.00%","2.00%","3.92%","1.66%"],"answer":0,"explanation":"Premium = (F − S)/S × 12/months = (84.66 − 83.00)/83.00 × 2 = 4.00%. 2.00% is the 6-month (unannualised) figure; dividing by the forward rate gives 3.92%.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-226","question":"The spot rate is ₹82.00/$. Three-month interest rates are 8% per annum in India and 4% per annum in the US (simple interest for the quarter). What is the 3-month forward rate implied by covered interest parity?","options":["₹85.15","₹82.81","₹83.64","₹81.20"],"answer":1,"explanation":"F = S × (1 + i₹ × 3/12)/(1 + i$ × 3/12) = 82 × 1.02/1.01 = ₹82.8119. Using full annual rates gives ₹85.15; ignoring the US rate gives ₹83.64; inverting the ratio puts the rupee at a premium even though it carries the higher rate.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-227","question":"Spot is ₹80/$, the 1-year forward is ₹83/$, and 1-year rates are 6% in India and 3% in the US. An arbitrageur can borrow ₹80 lakh. What is the covered-interest arbitrage and its riskless profit?","options":["Borrow dollars, convert to rupees, invest at 6%, buy dollars forward: profit ≈ ₹69,000","Borrow rupees, buy $1 lakh spot, invest at 3%, sell dollars forward: profit ≈ ₹60,000","No arbitrage exists because the forward premium equals the interest differential","Borrow rupees, buy $1 lakh spot, invest at 3%, sell dollars forward: profit ≈ ₹69,000"],"answer":3,"explanation":"Parity forward = 80 × 1.06/1.03 = ₹82.33; the quoted ₹83 overprices the dollar forward, so sell dollars forward. $1,00,000 × 1.03 = $1,03,000 → × 83 = ₹85,49,000. Repay 80 lakh × 1.06 = ₹84,80,000. Profit = ₹69,000. The forward premium (3.75%) exceeds the interest differential (about 2.9%).","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-228","question":"According to covered interest parity, a currency with a higher interest rate than another will usually:","options":["Trade at a forward discount against the lower-rate currency","Trade at a forward premium against the lower-rate currency","Have a forward rate exactly equal to its current spot rate today","Appreciate in the spot market immediately"],"answer":0,"explanation":"For no arbitrage, the extra interest earned on the high-rate currency must be offset by losing on its conversion back, so it sells forward at a discount. The low-rate currency is at a forward premium.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-229","question":"The spot rate is ₹84.00/€ and the 1-year forward rate is ₹86.10/€. The 1-year rupee interest rate is 7%. If covered interest parity holds, what is the 1-year euro interest rate?","options":["4.50%","4.39%","9.67%","9.50%"],"answer":1,"explanation":"1 + i€ = (1 + i₹) × S/F = 1.07 × 84/86.10 = 1.04390 → i€ ≈ 4.39%. The approximation 7% − premium 2.50% gives 4.50%; using F/S instead of S/F gives 9.67%.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-230","question":"An exporter will receive $2,00,000 in 3 months and sells it forward at ₹83.40/$. At maturity the spot rate is ₹82.10/$. Compared with staying unhedged, the forward contract has:","options":["Cost the exporter ₹2,60,000","Gained the exporter ₹1,30,000","Gained the exporter ₹2,60,000","Made no difference, since a forward only fixes the rate"],"answer":2,"explanation":"Hedged receipt = 2,00,000 × 83.40 = ₹1,66,80,000; unhedged = 2,00,000 × 82.10 = ₹1,64,20,000. The rupee strengthened, so the forward saved ₹2,60,000.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-231","question":"An importer must pay $1,00,000 in 6 months. Spot is ₹83.00/$ and the 6-month forward is ₹84.40/$. For the 6 months, the importer can borrow rupees at 4% and earn 2% on dollar deposits (period rates). Which hedge is cheaper, and by how much?","options":["Money-market hedge, cheaper by about ₹22,745","Money-market hedge, cheaper by about ₹2,99,615","Both cost the same by interest-rate parity","Forward, cheaper by about ₹22,745"],"answer":3,"explanation":"Money-market hedge: deposit $1,00,000/1.02 = $98,039.22 now, bought with ₹81,37,255 borrowed at 4%; repay ₹84,62,745 in 6 months. Forward cost = ₹84,40,000. The forward is cheaper by about ₹22,745. Parity would give ₹84.63, so the quoted forward is slightly cheap.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-232","question":"Buying a European call and selling a European put on the same share, with the same strike and expiry, produces a payoff at expiry identical to:","options":["A long forward to buy the share at the strike price","A short position in the underlying share","A risk-free bond paying the strike price at the expiry date","A long straddle with the same strike and expiry"],"answer":0,"explanation":"At expiry, if S > K the call pays S − K and the put expires; if S < K the written put costs K − S. Either way the payoff is S − K, which is a long forward at K. Hence C − P = S − PV(K).","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-233","question":"A non-dividend share trades at ₹250. A 6-month European put with strike ₹240 costs ₹20, and the risk-free rate is 8% per annum (annual compounding). By put–call parity, what should the 6-month ₹240 call cost?","options":["₹30.00","₹39.06","₹47.78","₹39.23"],"answer":1,"explanation":"C = P + S − K/(1 + r)^t = 20 + 250 − 240/1.08^0.5 = 20 + 250 − 230.94 = ₹39.06. Ignoring discounting gives ₹30; discounting a full year gives ₹47.78; using simple half-year interest (4%) gives ₹39.23.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-234","question":"A non-dividend share is at ₹100. One-year European options with strike ₹100 trade at ₹15 (call) and ₹4 (put); the risk-free rate is 10% (annual compounding). Which strategy locks in an arbitrage profit today, and how much?","options":["Buy the call, sell the put, short the share and lend ₹90.91: about ₹1.91 today","Sell the call, buy the put, buy the share and borrow ₹100: about ₹11.00 today","Sell the call, buy the put, buy the share and borrow ₹90.91: about ₹1.91 today","None; the prices satisfy put–call parity"],"answer":2,"explanation":"Parity requires C − P = S − PV(K) = 100 − 90.91 = ₹9.09, but C − P = ₹11: the call is rich relative to the put. Sell call (+15), buy put (−4), buy share (−100), borrow PV(K) (+90.91) → +₹1.91 now. At expiry the share plus put minus call is worth exactly ₹100, which repays the loan.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-235","question":"A share trades at ₹500 and will pay a dividend whose present value is ₹10 before option expiry. A European call with strike ₹520 costs ₹30, and the present value of the strike is ₹490. What should the matching European put cost?","options":["₹20","₹60","₹10","₹30"],"answer":3,"explanation":"With a known dividend: C + PV(K) = P + S − PV(D) → P = C − S + PV(D) + PV(K) = 30 − 500 + 10 + 490 = ₹30. Ignoring the dividend gives ₹20; using the undiscounted strike gives ₹60; subtracting the dividend instead of adding it gives ₹10.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-236","question":"A farmer expects to sell 100 tonnes of grain at harvest and sells futures at ₹25,000 a tonne. At harvest the spot price is ₹22,000 and the futures price ₹22,300, and he closes out the hedge. What effective price per tonne does he realise?","options":["₹24,700","₹25,000","₹22,000","₹25,300"],"answer":0,"explanation":"Spot sale ₹22,000 + futures gain (25,000 − 22,300 = ₹2,700) = ₹24,700. The ₹300 gap from the locked-in ₹25,000 is basis risk: the futures did not converge fully to spot.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-237","question":"A stock index stands at 20,000. The risk-free rate is 7% and the index dividend yield 2% a year, both continuously compounded. What is the fair price of a 3-month index future?","options":["20,353.08","20,251.57","21,025.42","19,751.56"],"answer":1,"explanation":"F = S·e^((r − q)t) = 20,000 × e^(0.05 × 0.25) = 20,251.57. Ignoring dividends gives 20,353.08; using a full year gives 21,025.42.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-238","question":"A fund manager runs a ₹2 crore portfolio with a beta of 1.3 and wants to cut its beta to 0.8 for a month without selling shares. Index futures trade at 25,000 with a lot size of 25. What should she do?","options":["Sell 42 index futures contracts","Buy 16 index futures contracts","Sell 16 index futures contracts","Sell 26 index futures contracts"],"answer":2,"explanation":"Contracts = (β_target − β_current) × portfolio value ÷ contract value = (0.8 − 1.3) × 2,00,00,000 ÷ (25,000 × 25) = −16: sell 16. Selling 42 would hedge beta all the way to zero.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-239","question":"An investor holds a ₹50 lakh portfolio with a beta of 1.0 and hedges it fully by selling index futures (lot size 50) at 20,200 when the index is at 20,000; the number of contracts is based on the spot index. When she lifts the hedge, the index is 19,000, futures are at 19,100 and the portfolio has fallen 5%. What is her net gain or loss?","options":["Net loss of ₹25,000","Exactly zero, since the hedge was perfect","Net gain of ₹50,000","Net gain of ₹25,000"],"answer":3,"explanation":"Contracts = 50,00,000 ÷ (20,000 × 50) = 5. Futures gain = (20,200 − 19,100) × 50 × 5 = ₹2,75,000. Portfolio loss = 5% × 50 lakh = ₹2,50,000. Net = ₹25,000 gain, because the basis narrowed from 200 to 100 points. Assuming futures converge fully to 19,000 gives ₹50,000.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-240","question":"An acquirer's share trades at ₹200 and the target's at ₹60. The acquirer offers its own shares at a 20% premium to the target's market price. What is the exchange ratio?","options":["0.36 acquirer share per target share","0.30 acquirer share per target share","0.24 acquirer share per target share","2.78 acquirer shares per target share"],"answer":0,"explanation":"Offer value = ₹60 × 1.2 = ₹72 per target share; exchange ratio = 72 ÷ 200 = 0.36. 0.30 ignores the premium; 2.78 inverts the ratio.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-241","question":"Acquirer A earns ₹100 crore on 10 crore shares; target T earns ₹30 crore on 5 crore shares. A issues 0.36 of its shares for each T share and expects no synergies. What is the combined firm's EPS, and is the deal accretive for A's shareholders?","options":["₹8.67; dilutive","₹11.02; accretive","₹11.02; dilutive","₹13.00; accretive"],"answer":1,"explanation":"New shares = 5 × 0.36 = 1.8 crore; total = 11.8 crore. EPS = 130 ÷ 11.8 = ₹11.02 versus A's ₹10 before: accretive. It rises because A pays a P/E of 72/6 = 12, below its own P/E of 20.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-242","question":"For the same deal (A: ₹100 crore earnings, 10 crore shares; T: ₹30 crore earnings, 5 crore shares; no synergies), what is the highest exchange ratio A can offer without diluting its current EPS of ₹10?","options":["0.30","0.36","0.60","0.50"],"answer":2,"explanation":"Require 130 ÷ (10 + 5 × ER) ≥ 10 → 10 + 5ER ≤ 13 → ER ≤ 0.60. Without synergies this equals the ratio of EPS (₹6 ÷ ₹10). 0.30 is the market-price ratio (60/200) and 0.36 the offered ratio.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-243","question":"After the A–T merger (combined earnings ₹130 crore on 11.8 crore shares, exchange ratio 0.36), the market values the combined firm at a P/E of 18. Before the deal A traded at ₹200 and T at ₹60. Which statement is correct?","options":["₹220.34: both groups gain, as the P/E of 20 is kept","₹198.31: both groups gain from the higher combined EPS","₹198.31: A's holders gain slightly while T's holders lose","₹198.31: A's holders lose slightly while T's holders gain"],"answer":3,"explanation":"Post-merger price = 18 × ₹11.02 = ₹198.31, a little below A's ₹200. T's holders get 0.36 × ₹198.31 = ₹71.39 per old share versus ₹60. EPS accretion does not guarantee value creation: the P/E fell from 20 to 18.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-244","question":"A merger is expected to yield after-tax synergies of ₹12 crore next year, growing 3% a year forever, discounted at 11%. One-time integration costs are ₹20 crore today. If the acquirer pays a ₹90 crore premium over the target's standalone value, what is the NPV to the acquirer's shareholders?","options":["₹40 crore","₹60 crore","−₹0.91 crore","₹130 crore"],"answer":0,"explanation":"PV of synergies = 12 ÷ (0.11 − 0.03) = ₹150 crore. Net of integration costs = ₹130 crore. NPV to acquirer = 130 − 90 = ₹40 crore; the target's holders capture the ₹90 crore premium. ₹130 crore is the total gain before splitting it.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-245","question":"An acquirer is unsure whether the projected merger synergies will materialise. Compared with a cash offer of the same value, why might a stock offer suit it better?","options":["A stock offer always costs the acquirer less than a cash offer of equal value","Target holders become part-owners and share any synergy shortfall","A stock offer removes the need for any shareholder approval","With stock, the acquirer's EPS cannot be diluted by the deal"],"answer":1,"explanation":"In a cash deal the acquirer pays a fixed sum and bears all the synergy risk. In a stock deal the target's holders own a share of the combined firm, so the true cost depends on the post-merger price and the risk is shared. Stock offers are also used when managers think their own shares are overvalued.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-246","question":"In India the rupee–dollar rate is quoted directly as ₹84.00 per US dollar. What is the equivalent indirect quote per ₹100?","options":["$0.8400 per ₹100","$11.905 per ₹100","$1.1905 per ₹100","$84.00 per ₹100"],"answer":2,"explanation":"Indirect quote = 1 ÷ 84 = $0.011905 per rupee, i.e. $1.1905 per ₹100.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-247","question":"A bank quotes ₹/$ 83.90–84.10 and $/€ 1.0790–1.0810 (bid–ask). What is its implied ₹/€ bid–ask quote?","options":["₹90.70 – ₹90.74","₹90.53 – ₹90.74","₹77.61 – ₹77.94","₹90.53 – ₹90.91"],"answer":3,"explanation":"To buy euros from customers (bid in ₹), the bank buys € with $ at 1.0790 and sells those $ for ₹ at 83.90: 83.90 × 1.0790 = ₹90.53. To sell euros (ask): 84.10 × 1.0810 = ₹90.91. Cross rates multiply bid with bid and ask with ask, so the spread widens.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-248","question":"Assertion (A): Other things equal, the value of a put option rises when the volatility of the underlying share rises. Reason (R): The maximum loss for the buyer of a put option is unlimited.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A is true: greater volatility raises the chance of a large favourable move while the downside stays capped at the premium. R is false: a put buyer can lose at most the premium paid.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-249","question":"On the rating scales used by Indian credit rating agencies for long-term debt, which is the LOWEST rating that is still regarded as investment grade?","options":["A (A−)","BBB (BBB−)","BB (BB+)","AA (AA−)"],"answer":1,"explanation":"Investment grade runs from AAA down to the BBB category (BBB− at the bottom). BB and below are speculative grade, with higher default risk and wider spreads.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-250","question":"Why do index funds usually have lower expense ratios than actively managed equity funds?","options":["They are exempt from all taxes on capital gains and dividends","They invest only in low-cost government securities","They track an index, so research and trading costs are low","SEBI caps their returns, so their costs must be lower"],"answer":2,"explanation":"A passive fund copies the index weights, so it saves on analyst teams and has low portfolio turnover. Active funds pay for research and trading in the hope of beating the index.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-251","question":"An investor redeems 5,000 units of an equity fund within the exit-load period. The NAV on the redemption date is ₹42.60 and the exit load is 1% of NAV. How much does he receive (before tax)?","options":["₹2,10,870","₹2,13,000","₹1,91,700","₹2,10,891"],"answer":0,"explanation":"Redemption price = NAV × (1 − exit load) = 42.60 × 0.99 = ₹42.174. Proceeds = 5,000 × 42.174 = ₹2,10,870. ₹2,10,891 divides by 1.01 instead of deducting 1%.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-252","question":"A fund's NAV was ₹20.00 at the start of the year. It paid an income distribution (IDCW) of ₹1.50 per unit during the year and its NAV at year-end was ₹21.00. Ignoring reinvestment and taxes, what was the investor's total return?","options":["5.00%","12.50%","7.50%","12.20%"],"answer":1,"explanation":"Total return = (ending NAV + distribution − starting NAV)/starting NAV = (21.00 + 1.50 − 20.00)/20.00 = 12.50%. Looking only at the NAV change (5%) ignores the cash paid out.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-253","question":"₹10 lakh is invested as a lump sum for 15 years in the same scheme. The direct plan earns 11.2% a year net of expenses and the regular plan, whose expense ratio is 1 percentage point higher, earns 10.2%. Roughly how much larger is the direct-plan corpus after 15 years?","options":["₹1.50 lakh","₹1.61 lakh","₹6.23 lakh","₹49.16 lakh"],"answer":2,"explanation":"Direct: 10 lakh × 1.112¹⁵ = ₹49.16 lakh; regular: 10 lakh × 1.102¹⁵ = ₹42.93 lakh. Difference ≈ ₹6.23 lakh. A 1% annual cost gap compounds; ₹1.5 lakh (1% × 15 years on the original sum) badly understates it.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-254","question":"A closed-end fund has a NAV of ₹50 and trades at ₹45. Over the next year the NAV rises 8% and the discount to NAV narrows to 5%. Ignoring distributions, what return does a buyer at ₹45 earn?","options":["8.0%","20.0%","13.0%","14.0%"],"answer":3,"explanation":"Initial discount = 10%. New NAV = ₹54.00; new price = 54.00 × 0.95 = ₹51.30. Return = 51.30/45 − 1 = 14.0%. The narrowing discount adds to the 8% NAV gain; 20.0% assumes the fund then trades at NAV.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-255","question":"A one-year corporate zero-coupon bond has a 2% probability of default; if it defaults, investors recover 40% of face value at maturity. The one-year risk-free rate is 7%. Ignoring any risk premium, what yield must the bond offer so that its expected return equals the risk-free rate, and what is the implied credit spread?","options":["8.30%; spread ≈ 130 bp","8.20%; spread ≈ 120 bp","9.18%; spread ≈ 218 bp","7.80%; spread ≈ 80 bp"],"answer":0,"explanation":"Expected payoff per ₹1 promised = 0.98 × 1 + 0.02 × 0.40 = 1 − 0.02 × 0.60 = 0.988. Need (1 + y) × 0.988 = 1.07 → y = 8.30%, spread ≈ 130 bp. The shortcut PD × LGD = 120 bp slightly understates it; assuming zero recovery gives 9.18%.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-256","question":"Which statements about credit ratings and bond spreads are correct? I. A credit rating is an opinion on the likelihood of timely payment of interest and principal. II. Other things equal, lower-rated bonds trade at wider spreads over government securities. III. A high rating is a guarantee by the agency that the issuer will not default. IV. Credit spreads tend to widen in economic downturns.","options":["I and II only","I, II and IV only","I, II, III and IV","II, III and IV only"],"answer":1,"explanation":"Ratings are opinions, not guarantees, so III is false. Lower ratings demand more compensation for default risk (II), and spreads widen in recessions as default fears and risk aversion rise (IV).","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-257","question":"A one-year zero-coupon bond with face value ₹100 trades at ₹88. Its probability of default is 6%, and in default holders recover ₹40 at maturity. What are its promised yield and its expected return?","options":["Promised 13.64%; expected 12.82%","Promised 12.00%; expected 9.55%","Promised 13.64%; expected 9.55%","Promised 13.64%; expected 6.82%"],"answer":2,"explanation":"Promised yield = 100/88 − 1 = 13.64%. Expected payoff = 0.94 × 100 + 0.06 × 40 = ₹96.40, so expected return = 96.40/88 − 1 = 9.55%. Ignoring recovery gives 6.82%. The gap between promised and expected yield is why high-yield bonds' quoted yields overstate likely returns.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-258","question":"A one-year corporate zero-coupon bond (face ₹100) trades at ₹90.50. The one-year risk-free rate is 7% and the expected recovery in default is 40% of face, paid at maturity. Assuming risk-neutral pricing, what default probability is implied?","options":["3.16%","8.74%","7.91%","5.27%"],"answer":3,"explanation":"Price = [(1 − p) × 100 + p × 40]/1.07 → 90.50 × 1.07 = 96.835 = 100 − 60p → p = 3.165/60 = 5.27%. Ignoring recovery gives 3.16%.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-259","question":"A 5-year bond with an 8% annual coupon trades at par (₹100) to yield 8%. After a downgrade, investors demand 9.5%. What is the new price?","options":["₹94.24","₹92.50","₹84.21","₹98.52"],"answer":0,"explanation":"Price = 8 × [1 − 1.095⁻⁵]/0.095 + 100/1.095⁵ = 30.72 + 63.52 = ₹94.24. Subtracting 1.5% × 5 years (₹92.50) is a crude duration guess using maturity instead of duration; ₹84.21 values the coupon as a perpetuity.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-260","question":"Match each derivative with its feature. (p) Credit default swap, (q) Interest rate swap, (r) Currency swap, (s) Forward rate agreement. Features: (1) Exchange of principal and interest in two different currencies; (2) Protection buyer pays a periodic premium and is compensated if a reference borrower defaults; (3) Fixed interest exchanged for floating interest in the same currency on a notional principal; (4) Locks in an interest rate for a single future borrowing or lending period.","options":["p-1, q-3, r-2, s-4","p-2, q-4, r-1, s-3","p-3, q-2, r-1, s-4","p-2, q-3, r-1, s-4"],"answer":3,"explanation":"A CDS transfers default risk (p-2); a plain interest rate swap exchanges fixed for floating on a notional amount (q-3); a currency swap exchanges principal and interest in two currencies (r-1); an FRA fixes the rate for one future period (s-4).","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-261","question":"Bank X offers a ₹30 lakh, 20-year home loan at 9.00% (monthly reducing, no fee). Bank Y offers 8.75% but charges a 1% processing fee deducted upfront. Comparing the effective annual rate (nominal, compounded monthly) of Bank Y with Bank X, which is correct?","options":["About 9.75% (fee added to the rate), so X is cheaper","About 8.89%, so Y is still cheaper than X's 9.00%","About 8.80% (fee spread over 20 years), so Y is cheaper","About 9.19%, so X is cheaper than Y"],"answer":1,"explanation":"Y's EMI on ₹30 lakh at 8.75% for 240 months = ₹26,511.32, but the borrower receives only ₹29.70 lakh. Solving 29,70,000 = ₹26,511.32 × annuity factor(i, 240) gives i ≈ 0.7408% a month, i.e. 8.89% nominal a year. That is still below 9.00%: over 20 years the 1% fee adds only about 0.1–0.15 percentage point.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-262","question":"A borrower owes ₹20 lakh on a loan at 9% per annum with 120 monthly EMIs left. She prepays ₹5 lakh and keeps the EMI unchanged. Roughly how many EMIs are saved (round the new tenure up)?","options":["30 EMIs","33 EMIs","41 EMIs","51 EMIs"],"answer":2,"explanation":"EMI = ₹25,335.15. New balance ₹15 lakh: (1.0075)⁻ᵐ = 1 − 15,00,000 × 0.0075/₹25,335.15 → m ≈ 78.6, so 79 EMIs remain and 41 are saved. 30 assumes the tenure falls in proportion to the balance (25% of 120); because a larger share of each EMI now goes to principal, the saving is bigger.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-263","question":"A fixed pension of ₹50,000 a month is not indexed to inflation. If inflation averages 6% a year, what will the pension be worth in today's purchasing power after 10 years (nearest rupee)?","options":["₹20,000","₹31,250","₹26,931","₹27,920"],"answer":3,"explanation":"Real value = 50,000/1.06¹⁰ = 50,000/1.7908 ≈ ₹27,920. Subtracting 6% × 10 = 60% gives ₹20,000; dividing by 1.6 uses simple inflation.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-264","question":"A company issues ₹100 crore of 10-year, 9% bonds repayable in a lump sum at maturity. To repay them it makes equal year-end deposits into a sinking fund earning 6% a year. What is its total annual cash outflow for coupons plus sinking-fund deposits?","options":["₹16.59 crore","₹19.00 crore","₹7.59 crore","₹15.58 crore"],"answer":0,"explanation":"Sinking-fund deposit = 100 × 0.06/(1.06¹⁰ − 1) = ₹7.59 crore. Add the ₹9 crore coupon: ₹16.59 crore a year. ₹19 crore ignores interest on the fund; ₹15.58 crore is the payment on an amortising loan at 9%, a different structure.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-265","question":"A new machine has an equivalent annual cost (EAC) of ₹2.5 lakh at 10%. The old machine can be sold today for ₹1.0 lakh or kept one more year, after which it would sell for ₹0.6 lakh; its operating cost for that year (paid at year-end) is ₹1.8 lakh. Ignoring taxes, what should the firm do?","options":["Replace now: keeping it costs ₹2.20 lakh, close to the EAC","Keep it a year: its cost of ₹2.30 lakh is below the ₹2.5 lakh EAC","Replace now: keeping it costs ₹2.80 lakh, above the ₹2.5 lakh EAC","Replace now, as the old machine loses ₹0.40 lakh of resale value"],"answer":1,"explanation":"Cost of keeping one more year (in year-end rupees) = forgone sale value with interest (1.0 × 1.10 = ₹1.10 lakh) − sale value next year (₹0.60 lakh) + operating cost (₹1.80 lakh) = ₹2.30 lakh. That is below the ₹2.5 lakh EAC, so keep it one more year and re-evaluate. Forgetting the interest on the sale value gives ₹2.20 lakh.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-266","question":"Which statements about the adjusted present value (APV) method are correct? I. It values the project as if all-equity financed and then adds the value of financing side effects. II. It is especially convenient when the amount of debt changes over time, as in a leveraged buyout. III. It discounts the operating cash flows at the after-tax WACC.","options":["I and III only","II and III only","I and II only","I, II and III"],"answer":2,"explanation":"APV discounts operating cash flows at the unlevered cost of equity, not WACC (III is false), and then adds items such as the PV of interest tax shields and subtracts issue costs. Because each financing effect is valued separately, it handles a changing debt schedule easily.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-267","question":"A firm's after-tax operating profit (NOPAT) this year is ₹200 crore. It reinvests 40% of NOPAT every year at a return on invested capital of 15%, and this will continue forever. Its WACC is 11%. What is its enterprise value today?","options":["₹2,400 crore","₹4,240 crore","₹1,091 crore","₹2,544 crore"],"answer":3,"explanation":"g = reinvestment rate × ROIC = 0.40 × 15% = 6%. Next year's NOPAT = 200 × 1.06 = ₹212 crore; FCFF = 212 × (1 − 0.40) = ₹127.2 crore. EV = 127.2/(0.11 − 0.06) = ₹2,544 crore. Using this year's NOPAT gives ₹2,400 crore; ignoring reinvestment (discounting NOPAT) gives ₹4,240 crore.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-268","question":"A 6-year corporate bond with a modified duration of 4.8 is rated BBB, and BBB bonds trade at 220 bp over government securities. The bond is upgraded to A, where the spread is 140 bp. If government yields are unchanged, what is the approximate percentage change in its price?","options":["+3.84%","−3.84%","+10.56%","+4.80%"],"answer":0,"explanation":"Yield falls by the spread change: 220 − 140 = 80 bp. ΔP/P ≈ −MD × Δy = −4.8 × (−0.0080) = +3.84%. Using maturity (6) instead of modified duration gives +4.80%.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-269","question":"A scheme has net assets of ₹500 crore and 20 crore units, so its NAV is ₹25.00. Next day its portfolio rises 1.2% and the day's expenses are accrued at an annual expense ratio of 1.46% on the opening net assets (365-day year). What is the new NAV (4 decimals)?","options":["₹25.3000","₹25.2990","₹24.9350","₹25.2696"],"answer":1,"explanation":"Daily expense = 500 × 1.46%/365 = ₹0.02 crore. Net assets = 500 × 1.012 − 0.02 = ₹505.98 crore. NAV = 505.98/20 = ₹25.2990. Deducting the full annual expense ratio in one day gives ₹24.9350.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-270","question":"A bond priced at ₹1,000 has a modified duration of 5.0 and convexity of 40. Its credit spread widens by 100 bp while risk-free yields are unchanged. Using the duration–convexity approximation, what is its new price?","options":["₹950","₹948","₹952","₹954"],"answer":2,"explanation":"ΔP/P ≈ −MD × Δy + ½ × convexity × (Δy)² = −5 × 0.01 + 0.5 × 40 × 0.0001 = −5.0% + 0.2% = −4.8%. New price ≈ ₹952. Duration alone gives ₹950; subtracting the convexity term gives ₹948; omitting the ½ gives ₹954.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-271","question":"Assertion (A): When a bond is downgraded from investment grade to speculative grade, its price can fall more sharply than the change in default risk alone would suggest. Reason (R): Many institutional investors are permitted to hold only investment-grade debt and may be forced to sell.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: mandate-driven selling by funds, insurers and others that cannot hold sub-investment-grade paper adds selling pressure beyond the pure change in expected loss.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-272","question":"A bank buys 5-year credit protection on ₹10 crore of a company's bonds through a credit default swap at a premium of 150 bp a year. In year 3 the company defaults and the bonds recover 35% of face value. What did the bank pay in annual premium, and what does the protection seller pay on default (cash settlement)?","options":["₹15 lakh a year; ₹10 crore","₹1.5 lakh a year; ₹6.5 crore","₹15 lakh a year; ₹3.5 crore","₹15 lakh a year; ₹6.5 crore"],"answer":3,"explanation":"Premium = 1.50% × ₹10 crore = ₹15 lakh a year, paid until default. On default the seller pays notional × (1 − recovery) = 10 × 0.65 = ₹6.5 crore. ₹3.5 crore is the recovery itself.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-273","question":"₹12,000 is deposited at the BEGINNING of each year for 8 years in an account paying 9% compounded annually. What is the balance at the end of year 8?","options":["₹1,44,252.44","₹1,32,341.69","₹1,56,252.44","₹1,04,640.00"],"answer":0,"explanation":"An annuity due earns one extra year of interest on every deposit: FV = 12,000 × [(1.09⁸ − 1)/0.09] × 1.09 = ₹1,44,252.44. ₹1,32,341.69 is the ordinary-annuity value, which treats deposits as year-end.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-274","question":"On her 30th birthday an employee plans to withdraw ₹6 lakh a year for 20 years, the first withdrawal on her 60th birthday. She will fund this with 30 equal deposits made on her 31st to 60th birthdays (the last deposit is made just before the first withdrawal). At 8% a year throughout, what is each deposit (nearest rupee)?","options":["₹52,001","₹56,162","₹51,580","₹61,195"],"answer":1,"explanation":"Value needed at 60 = 6,00,000 × annuity-due factor (20 yrs, 8%) = ₹63,62,160; the 30 deposits are an ordinary annuity ending at 60, so deposit = ₹63,62,160 / 113.2832 = ₹56,162. Treating the withdrawals as starting at 61 gives ₹52,001.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-275","question":"A cash flow of ₹50,000 will arrive at the end of year 3 and then grow at 4% a year forever. At a discount rate of 11%, what is the stream worth today?","options":["₹5,22,279.56","₹7,14,285.71","₹5,79,730.31","₹6,02,919.52"],"answer":2,"explanation":"The growing-perpetuity formula C/(r − g) = 50,000/0.07 = ₹7,14,285.71 values the stream one period before its first cash flow, i.e. at year 2; discount two years: ₹5,79,730.31. Discounting three years is the classic off-by-one trap.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-276","question":"A bank quotes a deposit rate of 9% per annum compounded quarterly. What nominal annual rate compounded MONTHLY gives exactly the same effective annual return?","options":["9.000%","9.308%","9.067%","8.933%"],"answer":3,"explanation":"Match the effective quarterly growth: (1 + j/12)³ = 1.0225, so j = 12 × (1.0225^(1/3) − 1) = 8.933%. More frequent compounding needs a slightly lower nominal rate than 9%; 9.308% is the effective annual rate itself.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-277","question":"What continuously compounded annual rate gives the same growth as an effective annual rate of 10%?","options":["9.53%","10.00%","10.52%","9.57%"],"answer":0,"explanation":"e^r = 1.10, so r = ln 1.10 = 9.53%. 10.52% goes the wrong way (the EAR of 10% continuous) and 9.57% is the monthly-compounded equivalent.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-278","question":"A dealer offers a ₹5,00,000 car loan at a 'flat' 7% a year for 3 years: interest of 7% × 3 on the original amount is added and the total is repaid in 36 equal monthly instalments. What is the true annual percentage rate (nominal, monthly compounding), to one decimal?","options":["7.0%","12.8%","14.0%","10.5%"],"answer":1,"explanation":"EMI = (5,00,000 + 1,05,000)/36 = ₹16,805.56; solving 5,00,000 = EMI × annuity factor gives a monthly rate of 1.069%, i.e. about 12.8% a year. A flat rate ignores that the principal is being repaid, so the true rate is nearly double.","difficulty":"very-hard","source":"IB analyst test · Bank MT"},
  {"id":"mgmt-finance-279","question":"₹10,000 will be received every six months for 5 years, the first receipt in six months. The discount rate is an EFFECTIVE 8% per annum. What is the present value?","options":["₹81,108.96","₹79,854.20","₹81,420.56","₹84,614.73"],"answer":2,"explanation":"The six-monthly rate is 1.08^0.5 − 1 = 3.923%, not 4%; PV = 10,000 × annuity factor (10 periods) = ₹81,420.56. Using 4% (₹81,108.96) treats 8% as a nominal rate.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-280","question":"A ₹30 lakh loan at 9% per annum (compounded monthly) is repaid with 120 monthly payments of ₹25,000 and a balloon payment at the end of month 120 that clears the rest. What is the balloon payment (nearest rupee)?","options":["₹25,44,212","₹43,54,071","₹10,26,458","₹25,16,214"],"answer":3,"explanation":"Balloon = FV of the loan − FV of the payments = 30,00,000 × 1.0075¹²⁰ − 25,000 × [(1.0075¹²⁰ − 1)/0.0075] = ₹25,16,214. Subtracting undiscounted payments ignores the interest they save.","difficulty":"very-hard","source":"IB analyst test · Bank MT"},
  {"id":"mgmt-finance-281","question":"₹10,000, ₹20,000 and ₹30,000 are deposited at the ends of years 1, 2 and 3 respectively in an account paying 7% compounded annually. Nothing more is added. What is the balance at the end of year 5?","options":["₹71,955.82","₹62,849.00","₹76,992.73","₹73,502.58"],"answer":0,"explanation":"Each deposit compounds to year 5: 10,000 × 1.07⁴ + 20,000 × 1.07³ + 30,000 × 1.07² = ₹71,955.82. Compounding from time 0 overstates; stopping at year 3 understates.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-282","question":"A ₹10 lakh loan at 12% per annum (1% a month) is repaid with monthly payments of ₹15,000. Roughly how many payments are needed?","options":["About 67 months","About 110 months","About 88 months","About 116 months"],"answer":1,"explanation":"Solve 10,00,000 = 15,000 × [1 − 1.01⁻ⁿ]/0.01: 1.01⁻ⁿ = 1 − 2/3 = 1/3, n = ln 3/ln 1.01 ≈ 110.4 months. Dividing principal by EMI (67) ignores interest altogether.","difficulty":"hard","source":"IB analyst test · Bank MT"},
  {"id":"mgmt-finance-283","question":"A fund's NAV moves from ₹100 to ₹150, then to ₹90, then to ₹130 over three successive years. What are its arithmetic mean annual return and its compound annual growth rate (CAGR)?","options":["Mean 9.1%; CAGR 18.1%","Mean 10.0%; CAGR 9.1%","Mean 18.1%; CAGR 9.1%","Mean 18.1%; CAGR 10.0%"],"answer":2,"explanation":"Yearly returns are +50%, −40% and +44.4%, averaging 18.1%; the CAGR is (130/100)^(1/3) − 1 = 9.1%. The arithmetic mean always overstates the compound rate when returns are volatile; 10% is just total gain ÷ 3.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-284","question":"A perpetual bond pays ₹3,000 every six months, the first payment in six months. Investors require an effective annual return of 10%. What is it worth?","options":["₹60,000.00","₹63,000.00","₹64,464.27","₹61,464.27"],"answer":3,"explanation":"Six-monthly rate = 1.1^0.5 − 1 = 4.881%; value = 3,000/0.04881 = ₹61,464.27. Using 6,000/0.10 ignores that half of each year's cash arrives early, and 5% treats 10% as nominal.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-285","question":"A lessee pays ₹2,00,000 at the START of each year for 5 years. At 10%, what is the present value of the lease payments?","options":["₹8,33,973.09","₹7,58,157.35","₹9,58,157.35","₹9,17,370.40"],"answer":0,"explanation":"Annuity due PV = 2,00,000 × 3.7908 × 1.10 = ₹8,33,973.09 (equivalently 2,00,000 + 2,00,000 × 3.1699). Adding a full extra payment to the 5-year ordinary annuity counts six payments.","difficulty":"moderate","source":"IB analyst test · Bank MT"},
  {"id":"mgmt-finance-286","question":"A seller can accept ₹10,00,000 cash today or ₹3,00,000 today plus ₹2,00,000 at the end of each of the next 4 years. At 8%, which is better and by roughly how much in present-value terms?","options":["Instalments, by ₹1,00,000","Cash today, by ₹37,575","Instalments, by ₹15,419","Instalments, by ₹39,419"],"answer":1,"explanation":"PV of instalments = 3,00,000 + 2,00,000 × 3.3121 = ₹9,62,425, which is below ₹10,00,000 by ₹37,575. Adding the undiscounted ₹11 lakh makes the instalments look better.","difficulty":"hard","source":"MBA finance · Consulting"},
  {"id":"mgmt-finance-287","question":"A one-year loan of ₹10 lakh carries 10% interest payable at maturity, but the lender deducts a 1% processing fee at disbursement. What is the borrower's effective annual cost?","options":["11.00%","10.00%","11.11%","10.91%"],"answer":2,"explanation":"The borrower receives ₹9.9 lakh and repays ₹11 lakh: cost = 11/9.9 − 1 = 11.11%. Simply adding the fee (11%) ignores that it reduces the usable amount.","difficulty":"moderate","source":"IB analyst test · Bank MT"},
  {"id":"mgmt-finance-288","question":"A child starts college in 14 years. Fees are ₹5 lakh a year at today's prices, rise 8% a year, and are paid at the start of each of the 4 college years (i.e. at t = 14, 15, 16, 17). Money earns 10%. What lump sum is needed today?","options":["₹14,77,863","₹4,59,099","₹15,46,910","₹15,05,230"],"answer":3,"explanation":"PV = Σ 5,00,000 × (1.08/1.10)ᵗ for t = 14–17 = ₹15,05,230. Ignoring fee inflation gives ₹4,59,099; putting the fees at t = 15–18 discounts one year too many.","difficulty":"very-hard","source":"MBA finance · Consulting"},
  {"id":"mgmt-finance-289","question":"A trust pays ₹20,000 today and then amounts growing at 3% a year forever (₹20,600 next year, and so on). At 9%, what is the trust's obligation worth today?","options":["₹3,63,333.33","₹3,33,333.33","₹3,43,333.33","₹3,63,933.33"],"answer":0,"explanation":"Today's payment plus a growing perpetuity starting next year: 20,000 + 20,600/(0.09 − 0.03) = ₹3,63,333.33. 20,000/0.06 would assume the first payment is a year away.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-290","question":"An annuity pays ₹5,000 at the end of each year for 6 years. The discount rate is 8% for years 1–3 and 10% for years 4–6. What is its present value?","options":["₹22,429.59","₹22,756.20","₹22,227.53","₹25,319.74"],"answer":1,"explanation":"Value years 4–6 at 10% as of t = 3 (₹12,434.26), then bring it back three years at 8%, and add years 1–3 at 8%: ₹22,756.20. Using 10% for the first three years of that deferral, or an average 9%, is wrong.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-291","question":"A ₹8 lakh loan at 10% is repaid in 5 equal year-end instalments. How much interest is paid in total over the life of the loan?","options":["₹4,00,000","₹2,40,000","₹2,55,190","₹4,88,408"],"answer":2,"explanation":"Instalment = 8,00,000 × 0.10/(1 − 1.1⁻⁵) = ₹2,11,038; total paid = ₹10,55,190, so interest = ₹2,55,190. ₹4 lakh assumes the full principal stays outstanding for 5 years.","difficulty":"moderate","source":"IB analyst test · Bank MT"},
  {"id":"mgmt-finance-292","question":"Plan P pays 12% simple interest a year for 10 years; Plan Q pays 8% compounded annually for 10 years. For ₹1 lakh invested, which statement is correct?","options":["Q ends ahead by ₹15,892","Q ends ahead by ₹90,585","Both end at the same amount","P ends ahead by ₹4,108"],"answer":3,"explanation":"P: 1,00,000 × (1 + 1.2) = ₹2,20,000. Q: 1,00,000 × 1.08¹⁰ = ₹2,15,892. Compounding needs more time before 8% compound beats 12% simple, so P is ahead by ₹4,108.","difficulty":"moderate","source":"IB analyst test · Bank MT"},
  {"id":"mgmt-finance-293","question":"Starting next year, a saver puts ₹1 lakh at the end of each year into an account earning 8%. What is the minimum number of deposits after which the balance first reaches ₹15 lakh?","options":["11","10","15","12"],"answer":0,"explanation":"Need [(1.08ⁿ − 1)/0.08] ≥ 15, i.e. 1.08ⁿ ≥ 2.2, n ≥ ln 2.2/ln 1.08 = 10.24, so 11 deposits (10 give only ₹14,48,656). 15 ignores interest.","difficulty":"hard","source":"IB analyst test · Bank MT"},
  {"id":"mgmt-finance-294","question":"A perpetuity pays ₹2,500 every quarter, the FIRST payment today. The discount rate is 12% per annum compounded quarterly. What is it worth?","options":["₹83,333.33","₹85,833.33","₹79,675.68","₹86,994.82"],"answer":1,"explanation":"Quarterly rate = 3%; a perpetuity due = C + C/r = 2,500 + 2,500/0.03 = ₹85,833.33. Discounting ₹10,000 a year at the effective 12.55% treats the stream as an annual perpetuity starting in a year.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-295","question":"An asset pays ₹20,000 at the end of each of years 1–5 and ₹30,000 at the end of each of years 6–10. At 10%, what is it worth today?","options":["₹1,53,614.18","₹1,89,539.34","₹1,46,429.15","₹1,60,799.21"],"answer":2,"explanation":"Treat it as ₹20,000 for 10 years plus ₹10,000 for years 6–10: 20,000 × 6.1446 + 10,000 × 3.7908/1.1⁵ = ₹1,46,429.15. Averaging to ₹25,000 overvalues because the larger cash flows come later.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-296","question":"A project costs ₹1,000 and returns ₹400, ₹500 and ₹600 at the ends of years 1–3. The firm reinvests and borrows at 10%. What is its modified IRR (MIRR)?","options":["21.65%","10.00%","14.47%","17.78%"],"answer":3,"explanation":"Terminal value at 10% = 400 × 1.21 + 500 × 1.1 + 600 = 1634; MIRR = (1634/1,000)^(1/3) − 1 = 17.78%. The ordinary IRR (21.65%) assumes reinvestment at the IRR itself.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-297","question":"A project costs ₹50,000 and returns ₹20,000 a year for 4 years. At a 10% discount rate, what is its discounted payback period?","options":["3.02 years","2.50 years","3.42 years","It never pays back"],"answer":0,"explanation":"Discounted inflows: 18,182, 16,529, 15,026, 13,660. After 2 years ₹49,737 is recovered; the remaining ₹263 takes 0.02 of year 3, so 3.02 years. 2.50 years is the simple payback.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-298","question":"Project A has cash flows (−100, +60, +60) and project B (−100, 0, +130) over years 0–2. At what discount rate do the two NPVs become equal (the crossover rate)?","options":["13.07%","16.67%","14.02%","13.54%"],"answer":1,"explanation":"Equate NPVs by finding the IRR of the difference (0, +60, −70): 60/(1+r) = 70/(1+r)², so 1 + r = 70/60 and r = 16.67%. Below it B (later, bigger cash) has the higher NPV; above it A does.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-299","question":"A new snack will sell ₹10 crore a year at a 40% contribution margin with ₹1.5 crore of new fixed cash costs. Research shows ₹3 crore of those sales will come from customers switching from the firm's existing snack, which also has a 40% margin. At a 25% tax rate, what is the incremental after-tax operating cash flow (ignore depreciation)?","options":["₹1.875 crore","₹2.100 crore","₹0.975 crore","₹1.300 crore"],"answer":2,"explanation":"Only the ₹7 crore of genuinely new sales adds contribution: (7 × 0.40 − 1.5) × 0.75 = ₹0.975 crore. Ignoring cannibalisation gives ₹1.875 crore.","difficulty":"hard","source":"MBA finance · Consulting"},
  {"id":"mgmt-finance-300","question":"A firm has ₹10 crore to invest. Projects are DIVISIBLE: P (cost ₹4 crore, NPV ₹2.0 crore), Q (₹5 crore, ₹1.5 crore), R (₹3 crore, ₹1.2 crore), S (₹2 crore, ₹0.4 crore). What is the maximum total NPV?","options":["₹3.50 crore","₹3.60 crore","₹3.20 crore","₹4.10 crore"],"answer":3,"explanation":"Rank by profitability index: P (1.50), R (1.40), Q (1.30), S (1.20). Take P and R fully (₹7 crore, NPV ₹3.2 crore) and 3/5 of Q (NPV ₹0.9 crore): total ₹4.10 crore. Ranking by absolute NPV (P + Q = ₹3.5 crore) wastes the budget's best uses.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-301","question":"A ₹12 lakh project lasts 6 years with no salvage value. At an 11% cost of capital, what is the minimum equal annual cash inflow at which it is acceptable?","options":["₹2,83,652","₹2,00,000","₹3,32,000","₹3,74,083"],"answer":0,"explanation":"Set NPV = 0: inflow = 12,00,000 / annuity factor (11%, 6) = 12,00,000/4.2305 = ₹2,83,652. ₹2 lakh only recovers the cost without any return.","difficulty":"hard","source":"IB analyst test · Bank MT"},
  {"id":"mgmt-finance-302","question":"An investment costs ₹5 lakh and pays ₹60,000 at the end of year 1, with the payment then growing at 2% a year forever. What is its IRR?","options":["12%","14%","10%","12.24%"],"answer":1,"explanation":"For a growing perpetuity, cost = C₁/(IRR − g), so IRR = C₁/cost + g = 60,000/5,00,000 + 2% = 14%. 12% ignores growth; 12.24% applies growth to the first cash flow.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-303","question":"A ₹100 crore project returns ₹50 crore at the end of year 1. At that point the PV of its remaining cash flows will be either ₹120 crore or ₹30 crore with equal probability. At year 1 the firm may instead abandon it and sell the assets for ₹60 crore. At 10%, what is the value of the abandonment option?","options":["₹30.00 crore","₹15.00 crore","₹13.64 crore","₹27.27 crore"],"answer":2,"explanation":"Abandonment adds ₹30 crore (60 − 30) only in the bad state: 0.5 × 30 = ₹15 crore at year 1, worth 15/1.1 = ₹13.64 crore today. It turns the project NPV from ₹13.64 crore to ₹27.27 crore.","difficulty":"very-hard","source":"MBA finance · Consulting"},
  {"id":"mgmt-finance-304","question":"A ₹20 lakh asset is depreciated straight-line over 4 years to zero. The tax rate is 25% and the discount rate 10%. What is the present value of its depreciation tax shields?","options":["₹5,00,000","₹15,84,933","₹11,88,700","₹3,96,233"],"answer":3,"explanation":"Annual shield = depreciation × t = 5,00,000 × 0.25 = ₹1,25,000; PV = 1,25,000 × 3.1699 = ₹3,96,233. ₹5 lakh is the undiscounted total of shields.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-305","question":"Which statements about a conventional project's NPV profile are correct? I. It cuts the horizontal axis at the IRR. II. Its vertical-axis intercept equals the undiscounted sum of all cash flows. III. Projects whose cash flows come later have flatter profiles.","options":["I and II only","I, II and III","I and III only","II and III only"],"answer":0,"explanation":"At r = 0 NPV is the simple sum of cash flows, and NPV = 0 at the IRR. Long-dated cash flows are MORE sensitive to the discount rate, so back-loaded projects have STEEPER profiles; III is false.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-306","question":"For a new plant, a firm lists: (a) ₹40 lakh already spent on R&D; (b) a building it owns that could be rented out for ₹12 lakh a year; (c) ₹8 lakh a year of head-office overhead that will be reallocated but not increased; (d) extra inventory of ₹15 lakh needed at the start, recovered at the end. Which items belong in the project's incremental cash flows?","options":["(a), (b) and (d)","(b) and (d) only","(b), (c) and (d)","(d) only"],"answer":1,"explanation":"The forgone rent is an opportunity cost and the inventory is working capital invested and recovered. R&D already spent is sunk, and reallocated overhead does not change total company cash flow.","difficulty":"moderate","source":"MBA finance · Consulting"},
  {"id":"mgmt-finance-307","question":"Mutually exclusive projects: A costs ₹1,000 and returns ₹1,200 in a year; B costs ₹10,000 and returns ₹11,000 in a year. The cost of capital is 8%. Which choice is correct?","options":["A, because its IRR (20%) is higher","A, because its profitability index is higher","B, because its NPV (₹185.19) is higher","Either, because both IRRs exceed 8%"],"answer":2,"explanation":"NPVs are ₹111.11 for A and ₹185.19 for B. With mutually exclusive projects and no capital shortage, choose the higher NPV; IRR ignores scale.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-308","question":"A project's cash flows are ₹100 crore a year for 3 years in TODAY's (real) rupees. The nominal cost of capital is 10.24% and expected inflation is 6%. What is the PV of the inflows?","options":["₹247.64 crore","₹276.25 crore","₹311.69 crore","₹277.51 crore"],"answer":3,"explanation":"Real rate = 1.1024/1.06 − 1 = 4%; discount real flows at the real rate: 100 × 2.7751 = ₹277.51 crore. Discounting real flows at the nominal rate understates value.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-309","question":"A project costs ₹500 lakh and returns ₹200 lakh a year for 4 years. At 12%, what is its equivalent annual annuity (EAA)?","options":["₹35.38 lakh","₹107.47 lakh","₹26.87 lakh","₹75.00 lakh"],"answer":0,"explanation":"NPV = 200 × 3.0373 − 500 = ₹107.47 lakh; EAA = NPV / annuity factor = ₹35.38 lakh. Dividing NPV by 4 ignores time value.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-310","question":"A project's NPV is positive at 12% and its IRR is 15%. The firm learns that its true risk-adjusted cost of capital is 16%. What follows?","options":["The NPV stays positive because IRR exceeds the old rate","The NPV at 16% is negative, so the project should be rejected","The IRR falls to 11% (15% − 4%)","The decision cannot change, because the cash flows are unchanged"],"answer":1,"explanation":"For a conventional project NPV is positive only below the IRR. At 16% > 15% the NPV is negative, so reject. The IRR itself does not depend on the cost of capital.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-311","question":"A ₹15 lakh machine has a 5-year life and a salvage value of ₹3 lakh at the end. At 10%, what equal annual cash inflow makes its NPV exactly zero?","options":["₹3,95,696","₹3,16,557","₹3,46,557","₹3,90,000"],"answer":2,"explanation":"PV of salvage = 3,00,000/1.1⁵ = ₹1,86,276; inflow = (15,00,000 − 1,86,276)/3.7908 = ₹3,46,557. Subtracting the undiscounted salvage overstates its value.","difficulty":"very-hard","source":"IB analyst test · Bank MT"},
  {"id":"mgmt-finance-312","question":"A coal mine's cash flow will be ₹100 crore next year and then DECLINE by 5% a year forever as output falls. At a 10% discount rate, what is the mine worth?","options":["₹2,000.00 crore","₹1,000.00 crore","₹633.33 crore","₹666.67 crore"],"answer":3,"explanation":"With negative growth the growing-perpetuity formula still holds: 100/(0.10 − (−0.05)) = ₹666.67 crore. Using r − g = 0.05 treats the decline as growth.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-313","question":"A bond (face ₹1,000) pays an 8% coupon semi-annually and has exactly 8 coupons left; the last coupon was paid 60 days ago in a 180-day period (30/360). Its yield is 6% per annum (semi-annual). What are its full (dirty) price and clean price?","options":["Full ₹1,080.79; clean ₹1,067.46","Full ₹1,070.20; clean ₹1,056.86","Full ₹1,083.53; clean ₹1,070.20","Full ₹1,080.79; clean ₹1,040.79"],"answer":0,"explanation":"Price on the last coupon date = ₹1,070.20; roll it forward 60/180 of a period: full = ₹1,070.20 × 1.03^(1/3) = ₹1,080.79. Accrued interest = 40 × 60/180 = ₹13.33, so clean = ₹1,067.46.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-314","question":"A ₹100-face government bond pays a 7.2% coupon in two equal half-yearly instalments. A buyer settles 75 days after the last coupon date (30/360 convention, 180-day period). How much accrued interest does she pay the seller?","options":["₹1.20","₹1.50","₹3.00","₹1.48"],"answer":1,"explanation":"Half-yearly coupon = ₹3.60; accrued = 3.60 × 75/180 = ₹1.50. ₹3.00 uses the full annual coupon over 90 days; ₹1.48 uses actual/365 on the annual coupon.","difficulty":"moderate","source":"Treasury · Bank MT · CFA Level I"},
  {"id":"mgmt-finance-315","question":"A bond with face value ₹1,000 and a 10% annual coupon has 8 years to maturity and trades at ₹1,080. It is callable in 3 years at ₹1,030. What is its yield to call?","options":["8.58%","9.26%","7.83%","6.95%"],"answer":2,"explanation":"Solve 1,080 = 100/(1+y) + 100/(1+y)² + 1,130/(1+y)³: y = 7.83%. The YTM to maturity is 8.58%; for a premium bond likely to be called, the lower yield-to-call is the relevant 'yield to worst'.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-316","question":"A 3-year bond pays a 6% annual coupon and yields 8%. What is its Macaulay duration?","options":["3.000 years","2.833 years","2.847 years","2.829 years"],"answer":3,"explanation":"Weights are the PVs of 60, 60 and 1,060 at 8% divided by the price; Σ t × weight = 2.829 years. 2.833 uses a 6% yield, and weighting by undiscounted cash flows gives 2.847.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-317","question":"A perpetual bond yields 8% a year. What are its Macaulay and modified durations?","options":["13.5 and 12.5 years","12.5 and 11.57 years","Infinite, because it never matures","12.5 and 13.5 years"],"answer":0,"explanation":"Macaulay duration of a level perpetuity = (1 + y)/y = 1.08/0.08 = 13.5; modified = Macaulay/(1 + y) = 1/y = 12.5. Duration is finite because far-off coupons carry tiny PV weights.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-318","question":"A 5-year bond pays a 7% coupon semi-annually and yields 8% (semi-annual basis). Its Macaulay duration is 4.287 years. What is its modified duration?","options":["3.969","4.122","4.287","3.963"],"answer":1,"explanation":"With semi-annual compounding, modified duration = Macaulay/(1 + y/2) = 4.287/1.04 = 4.122. Dividing by 1.08 uses the annual convention and understates sensitivity.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-319","question":"A bond has a modified duration of 8 and convexity of 90. Using the duration-plus-convexity approximation, what are the percentage price changes for a 100 bp FALL and a 100 bp RISE in yield?","options":["+8.00% and −8.00%","+7.55% and −8.45%","+8.45% and −7.55%","+8.90% and −7.10%"],"answer":2,"explanation":"%ΔP ≈ −D × Δy + ½ × C × Δy². The convexity term (½ × 90 × 0.0001 = +0.45%) is added in both directions: +8.45% for a fall, −7.55% for a rise. Positive convexity makes gains bigger than losses.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-320","question":"A callable bond priced at ₹100 is valued at ₹103.50 if the yield curve shifts down 50 bp and at ₹96.70 if it shifts up 50 bp (with the call option revalued each time). What is its effective duration?","options":["3.40","13.60","7.00","6.80"],"answer":3,"explanation":"Effective duration = (P₋ − P₊)/(2 × P₀ × Δy) = (103.50 − 96.70)/(2 × 100 × 0.005) = 6.80. Using only the downward move (7.00) misstates it because a callable bond's price is capped as yields fall.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-321","question":"A treasury desk holds bonds with face value ₹10 crore priced at ₹105 per ₹100 face. Their modified duration is 7. What is the price value of a basis point (PVBP) of the holding?","options":["₹73,500","₹70,000","₹73,50,000","₹68,692"],"answer":0,"explanation":"PVBP = market value × modified duration × 0.0001 = 10.5 crore × 7 × 0.0001 = ₹73,500. Using face value instead of market value gives ₹70,000.","difficulty":"hard","source":"Treasury · Bank MT · CFA Level I"},
  {"id":"mgmt-finance-322","question":"A 1-year zero-coupon bond yields 5%. A 2-year bond with a 6% annual coupon trades at ₹100.50 (face ₹100). What is the 2-year spot (zero) rate implied by bootstrapping?","options":["5.728%","5.750%","6.000%","5.500%"],"answer":1,"explanation":"Strip the first coupon at the 1-year spot: 100.50 − 6/1.05 = 94.7857 = 106/(1 + s₂)², so s₂ = 5.750%. The bond's YTM (5.728%) is a blend of s₁ and s₂, not the 2-year spot.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-323","question":"The 1-year spot rate is 6% and the 2-year spot rate is 7% (annual compounding). What is the 1-year rate one year from now (the 1y1y forward rate) implied by the curve?","options":["7.000%","6.500%","8.009%","8.000%"],"answer":2,"explanation":"(1.07)² = 1.06 × (1 + f), so f = 1.1449/1.06 − 1 = 8.009%. The approximation 2 × 7% − 6% = 8% ignores compounding.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-324","question":"The 1-year spot rate is 5.0% and the 3-year spot rate is 6.5%. What is the annualised 2-year rate starting one year from now (1y2y forward)?","options":["15.043%","7.250%","8.000%","7.258%"],"answer":3,"explanation":"(1.065)³ = 1.05 × (1 + f)², so f = (1.207950/1.05)^0.5 − 1 = 7.258%. 15.043% is the total two-year forward return, not an annual rate.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-325","question":"Spot rates are 4%, 5% and 6% for 1, 2 and 3 years. What is the no-arbitrage price of a 3-year bond with a 5% annual coupon (face ₹100)?","options":["₹97.503","₹97.327","₹100.000","₹108.626"],"answer":0,"explanation":"Discount each cash flow at its own spot rate: 5/1.04 + 5/1.05² + 105/1.06³ = ₹97.503. Discounting everything at 6% ignores the cheaper early cash flows; ₹100 assumes the 5% average.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-326","question":"A 6-year bond with a 10% annual coupon is bought at a yield of 8% for ₹1,092.46. If its yield is still 8% a year later (just after the coupon), what is its price and the investor's total return for the year?","options":["₹1,092.46; 10.00%","₹1,079.85; 8.00%","₹1,079.85; 10.00%","₹1,079.85; 9.15%"],"answer":1,"explanation":"A premium bond's price drifts toward par: at 5 years it is ₹1,079.85. Return = (100 + 1,079.85 − 1,092.46)/1,092.46 = 8%, exactly the yield, since the yield did not change. The 10% coupon overstates return because of the capital loss.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-327","question":"An investor buys a 3-year, 10% annual-coupon bond at par (₹1,000) and holds it to maturity, reinvesting each coupon at 6%. What is her realised annual (horizon) return?","options":["10.00%","6.00%","9.65%","9.14%"],"answer":2,"explanation":"Terminal wealth = 100 × 1.06² + 100 × 1.06 + 1,100 = ₹1,318.36; return = (1,318.36/1,000)^(1/3) − 1 = 9.65%. The YTM of 10% is earned only if coupons are reinvested at 10%.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-328","question":"A bond's yield to maturity is quoted as 8% on a semi-annual bond-equivalent basis. What is the equivalent effective annual yield?","options":["8.00%","8.24%","7.85%","8.16%"],"answer":3,"explanation":"Effective annual = (1 + 0.08/2)² − 1 = 1.0816 − 1 = 8.16%. 8.24% is quarterly compounding; a semi-annual BEY always understates the effective annual yield.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-329","question":"Which statements about term-structure theories are correct? I. Under the pure expectations theory, an upward-sloping curve means short rates are expected to rise. II. The liquidity preference theory says long yields include a premium, so the curve can slope upward even if short rates are expected to stay flat. III. The segmented-markets theory says the shape of the curve is set by expected future short rates alone.","options":["I and II only","I, II and III","II and III only","I only"],"answer":0,"explanation":"Expectations theory reads the slope purely as expected short-rate changes; liquidity preference adds a term premium. Segmented markets says each maturity's yield is set by its own supply and demand, not by expectations, so III is false.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-330","question":"A portfolio holds ₹30 crore in bonds with duration 2, ₹50 crore with duration 6 and ₹20 crore with duration 12 (market values). If all yields rise by 40 bp, what is the approximate fall in the portfolio's value?","options":["₹2.67 crore","₹2.40 crore","₹24.00 crore","₹0.24 crore"],"answer":1,"explanation":"Portfolio duration = 0.3 × 2 + 0.5 × 6 + 0.2 × 12 = 6.0; loss ≈ 100 × 6.0 × 0.004 = ₹2.40 crore. A simple average of durations ignores the weights.","difficulty":"moderate","source":"Treasury · Bank MT · CFA Level I"},
  {"id":"mgmt-finance-331","question":"An insurer must pay ₹50 crore in exactly 6 years. To immunise this single liability against a parallel shift in rates, which bond portfolio is most appropriate?","options":["A bond maturing in 6 years, regardless of its coupon rate","A portfolio of 1-year bills rolled over each year to year 6","Duration of 6 years, with PV matching the liability's PV","The highest-yielding bonds available for the credit risk taken"],"answer":2,"explanation":"Matching Macaulay duration (and PV) to the liability horizon balances price risk against reinvestment risk. A 6-year coupon bond has duration below 6, and rolling bills leaves full reinvestment risk.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-332","question":"Which of these bonds, all yielding 8%, has the HIGHEST interest-rate sensitivity? (A) 10-year, 12% coupon; (B) 10-year zero-coupon; (C) 15-year, 12% coupon; (D) 5-year zero-coupon.","options":["A, the 10-year 12% bond","C, the 15-year 12% bond, because it has the longest maturity","D, the 5-year zero","B, the 10-year zero"],"answer":3,"explanation":"Durations: 10-year zero = 10; 15-year 12% coupon = 8.57; 10-year 12% coupon = 6.74; 5-year zero = 5. High coupons pull duration well below maturity, so the 10-year zero is the most sensitive.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-333","question":"A 20-year zero-coupon bond yields 7% (annual). If its yield jumps to 9%, what is the exact percentage price change, and what does the modified-duration estimate give?","options":["Exact −30.95%; duration estimate −37.38%","Exact −37.38%; duration estimate −30.95%","Exact −40.00%; duration estimate −37.38%","Exact −30.95%; duration estimate −40.00%"],"answer":0,"explanation":"Exact: (1.07/1.09)²⁰ − 1 = −30.95%. Modified duration = 20/1.07 = 18.69, so the estimate is −18.69 × 2% = −37.38%. Duration overstates the loss for a large move because it ignores convexity.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-334","question":"A floating-rate note pays a coupon equal to the 6-month reference rate plus a fixed quoted margin of 1%, reset every six months. The issuer's credit quality is unchanged since issue. On a reset date, the note will trade:","options":["At a premium, because the 1% margin is added to the reference rate","At or very near par, with duration close to the time to next reset","At a discount whenever the reference rate has risen since issue","At par only if the reference rate equals the original coupon"],"answer":1,"explanation":"If the required margin still equals the quoted margin, the next coupon resets to the market rate, so the note is worth par at each reset and behaves like a 6-month instrument. A credit downgrade, not a rate change, would push it below par.","difficulty":"hard","source":"Treasury · Bank MT · CFA Level I"},
  {"id":"mgmt-finance-335","question":"A bond trades at a premium to its face value. Which ordering is correct?","options":["YTM exceeds current yield, which exceeds coupon rate","Current yield exceeds coupon rate, which exceeds YTM","Coupon rate exceeds current yield, which exceeds YTM","Coupon rate equals current yield, and both exceed YTM"],"answer":2,"explanation":"Current yield = coupon/price is below the coupon rate because price > face. YTM is lower still because it also counts the certain capital loss as the price pulls back to par.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-336","question":"A 5-year inflation-indexed bond with face ₹1,000 pays a 2% real coupon annually on the inflation-adjusted principal. Inflation is 6% in year 1 and 4% in year 2. What is the coupon paid at the end of year 2?","options":["₹20.00","₹22.00","₹20.80","₹22.05"],"answer":3,"explanation":"Indexed principal after 2 years = 1,000 × 1.06 × 1.04 = ₹1,102.40; coupon = 2% × 1,102.40 = ₹22.05. Adding the inflation rates (₹22) ignores compounding of the index.","difficulty":"moderate","source":"Treasury · Bank MT · CFA Level I"},
  {"id":"mgmt-finance-337","question":"Assertion (A): At low yields, a callable bond's price rises less than an otherwise identical option-free bond when yields fall further. Reason (R): As yields fall, the issuer's call option gains value, and the investor is short that option.","options":["Both A and R are true, and R explains A","Both are true, but R does not explain A","A is true, R is false","A is false, R is true"],"answer":0,"explanation":"Callable bond = straight bond − call. Near the call price, falling yields raise the call's value almost as fast as the straight bond's, capping the price (negative convexity).","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-338","question":"A bond with a modified duration of 7 falls in price by 3.5% after a rate change. Ignoring convexity, by roughly how much did its yield change?","options":["Up about 24.5 bp","Up about 50 bp","Up about 200 bp","Down about 50 bp"],"answer":1,"explanation":"%ΔP ≈ −D × Δy, so Δy ≈ 3.5%/7 = 0.50% = 50 bp, and it must be a rise because the price fell.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-339","question":"A 10-year zero-coupon bond (face ₹100) is priced at a yield of 7%. What is its price if the 7% is quoted with annual compounding, and if it is quoted with semi-annual compounding?","options":["₹50.257 and ₹50.835","₹50.835 and ₹50.835 (no difference for a zero)","₹50.835 and ₹50.257","₹52.614 and ₹50.257"],"answer":2,"explanation":"Annual: 100/1.07¹⁰ = ₹50.835. Semi-annual: 100/1.035²⁰ = ₹50.257. More frequent compounding at the same quoted rate means a higher effective rate, so a lower price.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-340","question":"A 4-year bond with a 7% annual coupon (face ₹1,000) trades at ₹935. What is its yield to maturity?","options":["7.49%","8.91%","7.00%","9.01%"],"answer":3,"explanation":"Solve 935 = 70 × annuity factor + 1,000/(1+y)⁴: y = 9.01%. The current yield (7.49%) ignores the ₹65 gain to par; the approximation formula gives 8.91%, close but not exact.","difficulty":"hard","source":"IB analyst test · Bank MT"},
  {"id":"mgmt-finance-341","question":"An investor buys a 5-year, 8% annual-coupon bond at par. One year later, just after the first coupon, the market yield on the bond is 9%. What is her one-year holding-period return?","options":["4.76%","8.00%","4.11%","−1.00%"],"answer":0,"explanation":"Price with 4 years left at 9% = ₹967.60; return = (80 + 967.60 − 1,000)/1,000 = 4.76%. Pricing with 5 years left forgets that a year has passed.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-342","question":"An option-free bond is worth ₹104. An embedded call option (held by the issuer) on an otherwise identical bond is worth ₹3, and an embedded put option (held by investors) is worth ₹2. What are the values of the callable bond and of the putable bond?","options":["₹107 and ₹102","₹101 and ₹106","₹101 and ₹102","₹107 and ₹106"],"answer":1,"explanation":"Callable = straight − call = 104 − 3 = ₹101 (investor is short the call). Putable = straight + put = 104 + 2 = ₹106 (investor is long the put).","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-343","question":"Which statement about bond spread measures is correct?","options":["The G-spread is added to each spot rate, while the Z-spread uses only the YTM","The option-adjusted spread of a callable bond is larger than its Z-spread","The Z-spread is a constant spread over the spot curve that prices the bond","The Z-spread equals the OAS for every bond, callable or not"],"answer":2,"explanation":"Z-spread uses the whole spot curve. For a callable bond, OAS = Z-spread − option cost, so OAS is SMALLER; they are equal only for option-free bonds. The G-spread is a simple YTM difference.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-344","question":"The 1-year rate today is 5% and the 1-year forward rate one year from now is 7%. What is the price of a 2-year bond with a 7% annual coupon (face ₹100)?","options":["₹100.000","₹101.833","₹100.125","₹101.905"],"answer":3,"explanation":"Discount year 2 through both periods: 7/1.05 + 107/(1.05 × 1.07) = ₹101.905. Using 1.07² for year 2 applies the forward rate to the first year too.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-345","question":"A bond priced at ₹100.00 would be worth ₹104.25 if yields fell 50 bp and ₹96.10 if they rose 50 bp. What is its effective convexity?","options":["140.0","70.0","8.2","280.0"],"answer":0,"explanation":"Effective convexity = (P₋ + P₊ − 2P₀)/(P₀ × Δy²) = (104.25 + 96.10 − 200)/(100 × 0.000025) = 140.0. 8.2 is the effective duration.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-346","question":"Yields fall by 1% across the curve. Which holding gains the most in rupees? (A) ₹50 lakh of bonds with modified duration 9; (B) ₹80 lakh with modified duration 5; (C) ₹1 crore with modified duration 4; (D) ₹30 lakh with modified duration 14.","options":["D (about ₹4.2 lakh)","A (about ₹4.5 lakh)","C (about ₹4.0 lakh)","B (about ₹4.0 lakh)"],"answer":1,"explanation":"Rupee gain ≈ value × duration × 1%: A = 4.5, B = 4.0, C = 4.0, D = 4.2 (₹ lakh). The highest duration (D) is not the biggest rupee gain because its holding is small.","difficulty":"moderate","source":"Treasury · Bank MT · CFA Level I"},
  {"id":"mgmt-finance-347","question":"A ₹20 crore bond position has a Macaulay duration of 6.42 years and a yield of 7% (annual). What is its money duration, and the approximate loss for a 25 bp rise in yields?","options":["₹128.40 crore; ₹0.32 crore","₹120.00 crore; ₹3.00 crore","₹120.00 crore; ₹0.30 crore","₹6.00 crore; ₹0.015 crore"],"answer":2,"explanation":"Modified duration = 6.42/1.07 = 6.00; money duration = 20 × 6.00 = ₹120 crore, so a 25 bp rise costs about 120 × 0.0025 = ₹0.30 crore. Using Macaulay duration directly overstates the sensitivity.","difficulty":"very-hard","source":"Treasury · Bank MT · CFA Level I"},
  {"id":"mgmt-finance-348","question":"Which statements are correct for an investor with a 3-year horizon? I. Holding a 10-year bond exposes her mainly to price risk. II. Rolling over 1-year deposits exposes her mainly to reinvestment risk. III. A zero-coupon bond maturing in 3 years carries neither risk for this horizon (ignoring default).","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":3,"explanation":"A long bond must be sold before maturity (price risk); short deposits must be reinvested at unknown rates (reinvestment risk). A zero maturing exactly at the horizon locks in its yield, so all three hold.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-349","question":"A 3-year corporate bond pays a 9% coupon semi-annually (face ₹100). The government yield is 7.5% and the bond's required spread is 250 bp (both semi-annual). What is its price?","options":["₹97.462","₹97.513","₹103.964","₹98.721"],"answer":0,"explanation":"Required yield = 7.5% + 2.5% = 10% → 5% per half-year over 6 periods: price = 4.5 × 5.0757 + 100/1.05⁶ = ₹97.462. Using annual compounding gives ₹97.513.","difficulty":"hard","source":"IB analyst test · Bank MT"},
  {"id":"mgmt-finance-350","question":"A 2-year bond with a 10% annual coupon yields 12%. Which statement about its durations is correct?","options":["Macaulay = 2.000 years, modified ≈ 1.786","Macaulay ≈ 1.908 years, modified ≈ 1.703","Macaulay ≈ 1.908 years, modified ≈ 2.137","Macaulay ≈ 1.703 years, modified ≈ 1.908"],"answer":1,"explanation":"PVs: 10/1.12 = 8.929 and 110/1.12² = 87.691; Macaulay = (1 × 8.929 + 2 × 87.691)/96.620 = 1.908; modified = 1.908/1.12 = 1.703.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-351","question":"Two 10-year bonds have the same yield of 8%; bond X has a 4% coupon and bond Y a 12% coupon. If yields fall to 7%, which is correct?","options":["Both rise about 7.0% because maturity is the same","Y rises more, because it pays larger coupons","X rises about 7.9% and Y about 6.5%","X rises about 6.5% and Y about 7.9%"],"answer":2,"explanation":"The low-coupon bond has more of its value in the distant principal, hence a longer duration and a larger percentage price gain: compute each price at 8% and 7% to see the gap.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-352","question":"Which statement about yield to maturity is correct?","options":["It equals the return earned by any investor who buys the bond, whenever she sells it","It always equals the coupon rate for a government bond, at any price","It assumes coupons are reinvested at the then-prevailing market rate","It is the single discount rate equating price with the PV of promised cash flows"],"answer":3,"explanation":"YTM is an internal rate of return. It is realised only if the bond is held to maturity, there is no default and coupons are reinvested at the YTM itself, not at whatever rate prevails.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-353","question":"A company has just paid a dividend of ₹5. Its dividend growth is 14% now and is expected to decline linearly to a long-run 6% over the next 8 years. Investors require 11%. Using the H-model, what is the share worth?","options":["₹138.00","₹106.00","₹114.00","₹170.00"],"answer":0,"explanation":"H-model: V = D₀(1 + g_L)/(r − g_L) + D₀ × H × (g_S − g_L)/(r − g_L), with H = 8/2 = 4: 106 + 5 × 4 × 0.08/0.05 = ₹138.00. Using the full 8 years as H double-counts the extra growth.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-354","question":"A firm pays out 40% of earnings, its dividends grow at 6% forever and the required return is 11%. What are its justified leading (forward) and trailing P/E ratios?","options":["8.48 and 8.00","8.00 and 8.48","7.55 and 8.00","8.00 and 3.64"],"answer":1,"explanation":"Leading P/E = payout/(r − g) = 0.40/0.05 = 8.00. Trailing P/E = payout × (1 + g)/(r − g) = 8.00 × 1.06 = 8.48, higher because it divides by the smaller current EPS.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-355","question":"A bank earns a sustainable ROE of 18%, grows at 8% a year and has a cost of equity of 12%. What price-to-book ratio is justified?","options":["1.50","4.50","2.50","1.25"],"answer":2,"explanation":"Justified P/B = (ROE − g)/(r − g) = (0.18 − 0.08)/(0.12 − 0.08) = 2.50. 1.50 is ROE/r, which ignores growth; P/B exceeds 1 only because ROE exceeds the cost of equity.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-356","question":"Next year's EPS is ₹10. The firm retains 60% of earnings and earns a 10% return on reinvested equity forever; its cost of equity is 12%. What is the share worth, and how does that compare with paying out all earnings?","options":["₹66.67; ₹16.67 MORE than with full payout","₹166.67; growth adds value","₹83.33; retention does not matter","₹66.67; ₹16.67 LESS than with full payout"],"answer":3,"explanation":"g = 0.6 × 10% = 6%; value = 4/(0.12 − 0.06) = ₹66.67 against 10/0.12 = ₹83.33 with no retention. Reinvesting at 10% below the 12% cost of equity destroys value even though EPS grows.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-357","question":"A firm's book value per share is ₹100. It will earn a constant ROE of 15% on beginning book value, its cost of equity is 12% and residual income will grow at 5% a year forever. Using the residual income model, what is the share worth?","options":["₹142.86","₹125.00","₹214.29","₹145.00"],"answer":0,"explanation":"First-year residual income = (15% − 12%) × 100 = ₹3; value = book + RI/(r − g) = 100 + 3/0.07 = ₹142.86. Ignoring growth of RI gives ₹125.00.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-358","question":"A company's enterprise value is ₹1,200 crore. It has debt of ₹300 crore, preference shares of ₹50 crore, minority (non-controlling) interest of ₹40 crore and cash of ₹90 crore, with 20 crore shares. What is the implied equity value per share?","options":["₹49.50","₹45.00","₹36.00","₹60.00"],"answer":1,"explanation":"Equity = EV − debt − preference − minority interest + cash = 1,200 − 300 − 50 − 40 + 90 = ₹900 crore, i.e. ₹45.00 a share. Subtracting cash, or ignoring preference and minority claims, misstates it.","difficulty":"hard","source":"IB analyst test · Equity research"},
  {"id":"mgmt-finance-359","question":"A company reports net income of ₹100 crore, depreciation ₹30 crore, capital expenditure ₹60 crore, an increase in working capital of ₹10 crore and net new borrowing of ₹20 crore. What is its free cash flow to equity (FCFE)?","options":["₹60 crore","₹100 crore","₹80 crore","₹40 crore"],"answer":2,"explanation":"FCFE = NI + depreciation − capex − ΔWC + net borrowing = 100 + 30 − 60 − 10 + 20 = ₹80 crore. ₹60 crore omits the borrowing that is available to shareholders.","difficulty":"moderate","source":"IB analyst test · Equity research"},
  {"id":"mgmt-finance-360","question":"Net income is ₹120 crore, interest expense ₹40 crore, tax rate 25%, depreciation ₹50 crore, capital expenditure ₹80 crore and the increase in working capital ₹15 crore. What is free cash flow to the firm (FCFF)?","options":["₹115 crore","₹75 crore","₹145 crore","₹105 crore"],"answer":3,"explanation":"FCFF = NI + interest × (1 − t) + depreciation − capex − ΔWC = 120 + 30 + 50 − 80 − 15 = ₹105 crore. Adding back the full ₹40 crore of interest (₹115 crore) ignores its tax shield.","difficulty":"hard","source":"IB analyst test · Equity research"},
  {"id":"mgmt-finance-361","question":"A share trades at ₹400. It has just paid a dividend of ₹12 and investors require 11%. What constant dividend growth rate is the market implying?","options":["7.77%","8.00%","8.25%","3.00%"],"answer":0,"explanation":"400 = 12(1 + g)/(0.11 − g) → 44 − 400g = 12 + 12g → g = 32/412 = 7.77%. Using 12/400 as the dividend yield forgets that next year's dividend is 12(1 + g).","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-362","question":"A young company will pay no dividends for the next three years. It will then pay ₹5 a share at the end of year 4, growing at 5% a year forever. At a 13% required return, what is the share worth today?","options":["₹38.33","₹43.32","₹62.50","₹45.48"],"answer":1,"explanation":"The Gordon value at the end of year 3 is 5/(0.13 − 0.05) = ₹62.50; discount 3 years: 62.50/1.13³ = ₹43.32. Discounting 4 years is the off-by-one trap.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-363","question":"Stock A trades at a P/E of 30 with expected EPS growth of 25%; stock B at a P/E of 18 with growth of 10%; stock C at a P/E of 12 with growth of 4%. Ranked by PEG ratio, which looks cheapest and which most expensive?","options":["C cheapest (3.0), A most expensive (1.2)","C cheapest (P/E 12), A most expensive (P/E 30)","A cheapest (1.2), C most expensive (3.0)","B cheapest (1.8), C most expensive (3.0)"],"answer":2,"explanation":"PEG = P/E ÷ growth (in %): A = 30/25 = 1.2, B = 18/10 = 1.8, C = 12/4 = 3.0. The lowest P/E is not the cheapest once growth is accounted for.","difficulty":"moderate","source":"IB analyst test · Equity research"},
  {"id":"mgmt-finance-364","question":"A company has 1 crore shares outstanding and 10 lakh in-the-money options with an exercise price of ₹80; the average share price is ₹100. Under the treasury stock method, how many shares are added for diluted EPS?","options":["10 lakh","8 lakh","1.25 lakh","2 lakh"],"answer":3,"explanation":"Exercise brings in 10 lakh × ₹80 = ₹8 crore, which buys back 8 lakh shares at ₹100; net new shares = 10 − 8 = 2 lakh. Adding all 10 lakh ignores the buyback.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-365","question":"A company's tax burden (NI/EBT) is 0.75, interest burden (EBT/EBIT) 0.80, EBIT margin 15%, asset turnover 1.2 and equity multiplier 2.0. What is its ROE?","options":["21.6%","36.0%","27.0%","10.8%"],"answer":0,"explanation":"Five-part DuPont: ROE = 0.75 × 0.80 × 0.15 × 1.2 × 2.0 = 21.6%. 10.8% is ROA (it leaves out leverage).","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-366","question":"A firm's ROA (net income/total assets) is 8% and its debt-to-equity ratio is 1.5 (all liabilities treated as debt). What is its ROE?","options":["12.0%","20.0%","13.3%","9.5%"],"answer":1,"explanation":"Equity multiplier = assets/equity = 1 + D/E = 2.5, so ROE = 8% × 2.5 = 20%. 12% multiplies by D/E instead of 1 + D/E; 13.3% uses debt/assets.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-367","question":"A retailer has EBIT of ₹60 crore, interest of ₹12 crore and lease payments of ₹10 crore (already deducted in arriving at EBIT). What are its interest coverage and fixed-charge coverage ratios?","options":["5.00× and 2.73×","5.83× and 3.18×","5.00× and 3.18×","5.00× and 2.27×"],"answer":2,"explanation":"Interest coverage = 60/12 = 5.00×. Fixed-charge coverage adds the lease back to EBIT and to the charges: (60 + 10)/(12 + 10) = 3.18×. It is lower, showing the lease burden.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-368","question":"In a period of rising input prices with stable inventory quantities, a firm using LIFO, compared with an identical firm using FIFO, will report:","options":["Lower COGS, higher inventory, higher current ratio and higher margin","Higher COGS, higher inventory, higher current ratio and lower turnover","Identical pre-tax cash flows and higher reported net income","Higher COGS, lower inventory, lower current ratio and higher turnover"],"answer":3,"explanation":"LIFO expenses the newest (costliest) units, raising COGS and leaving old cheap costs in inventory, so the inventory balance and current ratio fall while turnover (COGS/inventory) rises. Lower taxable profit actually raises LIFO's after-tax cash flow.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-369","question":"A distributor prices goods at a 25% markup on cost. Its operating expenses are 12% of sales. What is its operating profit as a percentage of sales?","options":["8%","13%","10%","12%"],"answer":0,"explanation":"A 25% markup on cost is a 25/125 = 20% gross margin on sales; operating margin = 20% − 12% = 8%. Treating markup as margin (25% − 12% = 13%) is the trap.","difficulty":"moderate","source":"MBA finance · Big 4 advisory"},
  {"id":"mgmt-finance-370","question":"A company with book value of ₹100 per share buys back 10% of its shares at the market price of ₹150. What happens to book value per share?","options":["Rises to ₹111.11","Falls to ₹94.44","Stays at ₹100.00","Falls to ₹85.00"],"answer":1,"explanation":"Per original share, equity falls by 0.1 × 150 = ₹15 to ₹85, spread over 0.9 shares: 85/0.9 = ₹94.44. Buying back above book always dilutes BVPS; below book it raises it.","difficulty":"very-hard","source":"MBA finance · Big 4 advisory"},
  {"id":"mgmt-finance-371","question":"A firm's debt-to-equity ratio is 0.6. What are its debt-to-capital ratio and its equity multiplier (assets/equity), assuming debt is its only liability?","options":["60.0% and 1.6","37.5% and 2.67","37.5% and 1.6","40.0% and 1.67"],"answer":2,"explanation":"D/(D + E) = 0.6/1.6 = 37.5%; assets/equity = (D + E)/E = 1.6. 40% wrongly uses 1 − 0.6.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-372","question":"A company has net income of ₹80 crore, interest expense of ₹20 crore, a 30% tax rate and average total assets of ₹1,000 crore. What is its return on assets measured before financing costs (adding back after-tax interest)?","options":["8.0%","10.0%","10.8%","9.4%"],"answer":3,"explanation":"Operating ROA = (NI + interest × (1 − t))/assets = (80 + 14)/1,000 = 9.4%. Adding back gross interest (10%) ignores the tax saving; 8% is the plain NI-based ROA.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-373","question":"A company has a net profit margin of 8% and trades at a P/E of 20. Its sales are ₹500 crore. What are its price-to-sales ratio and market capitalisation?","options":["1.6× and ₹800 crore","2.5× and ₹1,250 crore","1.6× and ₹10,000 crore","0.4× and ₹200 crore"],"answer":0,"explanation":"P/S = P/E × net margin = 20 × 0.08 = 1.6, so market cap = 1.6 × 500 = ₹800 crore (= 20 × ₹40 crore of profit). 2.5 divides P/E by the margin.","difficulty":"moderate","source":"IB analyst test · Equity research"},
  {"id":"mgmt-finance-374","question":"Net income is ₹50 crore. Depreciation is ₹20 crore, receivables rose by ₹15 crore, inventory rose by ₹10 crore, payables rose by ₹8 crore and there was a ₹5 crore gain on sale of equipment (included in net income). What is cash flow from operations?","options":["₹58 crore","₹48 crore","₹53 crore","₹38 crore"],"answer":1,"explanation":"CFO = 50 + 20 − 15 − 10 + 8 − 5 = ₹48 crore. The gain is removed because the sale proceeds belong in investing cash flow; forgetting that gives ₹53 crore.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-375","question":"Two identical firms spend ₹10 crore on software development; firm X capitalises it (amortised over 5 years) while firm Y expenses it. In the year of spending, compared with Y, X reports:","options":["Higher net income but exactly the same operating cash flow","Lower net income and a smaller investing cash outflow","Higher net income and CFO, with a larger investing outflow","Higher operating cash flow and higher total cash flow"],"answer":2,"explanation":"Capitalising moves the outflow from operating to investing activities and spreads the expense, so profit and CFO are higher while CFI is lower. Total cash flow (before tax effects) is the same.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-376","question":"A borrower's covenant caps net debt/EBITDA at 3.0×. EBITDA is ₹200 crore, gross debt ₹400 crore and cash ₹50 crore. If new borrowing will be fully spent on an acquisition that adds no EBITDA this year, how much more can it borrow?","options":["₹200 crore","₹300 crore","₹600 crore","₹250 crore"],"answer":3,"explanation":"Allowed net debt = 3 × 200 = ₹600 crore; current net debt = 400 − 50 = ₹350 crore; headroom = ₹250 crore. Ignoring the cash gives ₹200 crore, and ₹600 crore forgets existing debt.","difficulty":"hard","source":"MBA finance · Big 4 advisory"},
  {"id":"mgmt-finance-377","question":"Peers trade at 10× EV/EBITDA. A target has sales of ₹800 crore and an EBITDA margin of 15%; its net debt is ₹300 crore and it has 15 crore shares. What equity value per share does this imply?","options":["₹60","₹80","₹100","₹53.33"],"answer":0,"explanation":"EBITDA = 0.15 × 800 = ₹120 crore; EV = ₹1,200 crore; equity = 1,200 − 300 = ₹900 crore; per share = ₹60. ₹80 forgets to subtract net debt.","difficulty":"hard","source":"IB analyst test · Equity research"},
  {"id":"mgmt-finance-378","question":"A firm's net margin is 6%, asset turnover 1.8 and equity multiplier 2.0; it pays out 30% of earnings. If it keeps these ratios unchanged, what is its sustainable growth rate (using ROE on beginning equity)?","options":["21.60%","15.12%","6.48%","7.56%"],"answer":1,"explanation":"ROE = 0.06 × 1.8 × 2.0 = 21.6%; g = ROE × retention = 21.6% × 0.70 = 15.12%. Using payout instead of retention gives 6.48%.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-379","question":"Two firms have identical operations, EBITDA and EV, but firm L is financed 50% with debt while firm U has no debt. Which statement is most accurate?","options":["L has a higher EV/EBITDA, because debt adds to EV","Their P/E ratios must be identical because operations are identical","Same EV/EBITDA, but P/E can differ as interest changes net income","U has a lower EV/EBITDA because it carries no interest burden"],"answer":2,"explanation":"EV/EBITDA is capital-structure neutral: both numerator and denominator are measured before financing. P/E depends on leverage through interest and the equity slice of value.","difficulty":"hard","source":"IB analyst test · Equity research"},
  {"id":"mgmt-finance-380","question":"A company writes down obsolete inventory by ₹20 crore (a non-cash charge). Ignoring tax, what is the immediate effect?","options":["Current ratio falls, and operating cash flow falls by the full ₹20 crore","Current ratio is unchanged because inventory is a current asset","Net income falls, but total assets stay unchanged as no cash moves","Current ratio and net income fall; operating cash flow is unchanged"],"answer":3,"explanation":"The write-down cuts inventory (a current asset) and profit, but no cash moves; in the indirect method it is added back, so CFO is unaffected.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-381","question":"A company has just paid ₹4. Dividends will grow 15% a year for three years, then 6% forever. The required return is 12%. What is the share worth today?","options":["₹89.15","₹80.96","₹70.67","₹84.82"],"answer":0,"explanation":"Dividends: 4.60, 5.29, 6.08; terminal value at year 3 = 6.08 × 1.06/0.06 = ₹107.48. PV of all = ₹89.15. Forgetting to grow the year-3 dividend before applying Gordon understates value.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-382","question":"Last year a firm had ROE of 15% (margin 5%, turnover 1.5, equity multiplier 2.0). This year margin is 6%, turnover 1.25 and equity multiplier 2.4. What is this year's ROE, and what drove the change?","options":["15.0%; the three ratio changes exactly offset one another","18.0%; margin and leverage gains outweighed lower turnover","18.0%; driven by better asset turnover and a higher margin","16.5%; driven mainly by the higher leverage of 2.4 times"],"answer":1,"explanation":"ROE = 0.06 × 1.25 × 2.4 = 18.0%. Margin rose 20% and leverage 20% while turnover fell about 17%, so the gain came from margin and leverage, not efficiency.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-383","question":"A share's required return is 12% and its dividend yield on the next dividend is 4%. If the Gordon model holds, what price change does an investor expect over the next year?","options":["+12%, the full required return on the share","+4%, matching the dividend yield","+8%, as price grows at the dividend growth rate","0%, because all of the return comes from dividends"],"answer":2,"explanation":"Under Gordon, r = D₁/P₀ + g, so g = 12% − 4% = 8%, and the price grows at g each year. Total return 12% = 4% yield + 8% capital gain.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-384","question":"A firm with EBITDA of ₹100 crore is valued at 9× EV/EBITDA. It has no debt and 10 crore shares. It borrows ₹300 crore and uses all of it to buy back shares at a fair price; EV is unchanged (ignore taxes). What is the share price after the buyback?","options":["₹60","₹128.57","₹120","₹90"],"answer":3,"explanation":"Before: equity = EV = ₹900 crore, ₹90 a share. Buying back ₹300 crore at ₹90 retires 3.33 crore shares; remaining equity ₹600 crore over 6.67 crore shares = ₹90. A fairly priced buyback does not change the price; ₹60 divides by the old share count.","difficulty":"very-hard","source":"IB analyst test · Equity research"},
  {"id":"mgmt-finance-385","question":"A firm will earn EPS of ₹8 next year, retain 50% of earnings and earn a 16% ROE on reinvestment forever. The cost of equity is 12%. What is the share price, and how much of it is the present value of growth opportunities (PVGO)?","options":["₹100.00; PVGO ₹33.33","₹200.00; PVGO ₹133.33","₹100.00; PVGO ₹66.67","₹66.67; PVGO ₹0.00"],"answer":0,"explanation":"g = 0.5 × 16% = 8%; P = 4/(0.12 − 0.08) = ₹100. No-growth value = EPS/r = 8/0.12 = ₹66.67, so PVGO = ₹33.33. Comparing with dividend/r instead of EPS/r misstates PVGO.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-386","question":"A firm's sales are ₹730 crore with a 25% gross margin, and average inventory is ₹60 crore. An analyst computes days of inventory as 365 × inventory/sales. By how many days does this understate the correct (COGS-based) figure?","options":["30.0 days","10.0 days","40.0 days","7.5 days"],"answer":1,"explanation":"Correct DIO = 365 × 60/547.5 = 40.0 days; the sales-based figure is 30.0 days, so it understates by 10.0 days. Inventory is carried at cost, so COGS is the consistent denominator.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-387","question":"Under Ind AS 116 (IFRS 16), when a lessee brings a lease that was earlier an operating lease onto its balance sheet, what is the typical effect?","options":["Debt and assets rise, but EBITDA falls because of depreciation","EBITDA and operating cash flow are unchanged","Debt, assets, EBITDA and operating cash flow all rise","Only disclosure changes; no ratio is affected"],"answer":2,"explanation":"The lessee records a right-of-use asset and lease liability. Rent is replaced by depreciation and interest (both below EBITDA), and the principal portion of payments moves to financing activities, lifting CFO.","difficulty":"very-hard","source":"MBA finance · Big 4 advisory"},
  {"id":"mgmt-finance-388","question":"A share trades at 3× book value and its ROE is 15%. What is its P/E (on current earnings)?","options":["45×","5×","18×","20×"],"answer":3,"explanation":"P/E = (P/B)/(E/B) = P/B ÷ ROE = 3/0.15 = 20. Multiplying gives 0.45 (or 45×), which is meaningless.","difficulty":"moderate","source":"IB analyst test · Equity research"},
  {"id":"mgmt-finance-389","question":"A firm's enterprise value is ₹2,000 crore and its net debt ₹500 crore, which includes ₹200 crore of convertible bonds convertible into 4 crore shares (₹50 a share). It has 20 crore shares outstanding. If the implied share price is above ₹50, what is the per-share equity value?","options":["₹70.83","₹75.00","₹62.50","₹85.00"],"answer":0,"explanation":"If conversion is in the money, treat the convertible as equity: net debt excl. convertible = ₹300 crore, equity = 2,000 − 300 = ₹1,700 crore over 24 crore shares = ₹70.83 (above ₹50, so consistent). ₹75 subtracts all net debt over 20 crore shares, ignoring dilution.","difficulty":"very-hard","source":"IB analyst test · Equity research"},
  {"id":"mgmt-finance-390","question":"A share pays a dividend of ₹2 (just paid) growing at 5% forever. If its required return rises from 10% to 11%, by how much does its price fall?","options":["−10.00%","−16.67%","−9.09%","−20.00%"],"answer":1,"explanation":"Price falls from 2.10/0.05 = ₹42.00 to 2.10/0.06 = ₹35.00, i.e. −16.67%. A 1-point rise in r is a 20% rise in (r − g), which is why long-duration growth stocks are so rate-sensitive.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-391","question":"Firm M reports net income of ₹150 crore and operating cash flow of ₹60 crore; firm N reports net income of ₹150 crore and operating cash flow of ₹170 crore. Both have similar assets. Which conclusion is most reasonable?","options":["M's earnings are higher quality because it is reinvesting more cash","Both are equal because net income is the same","N's earnings are higher quality; M's big accruals need scrutiny","N must be using aggressive revenue recognition"],"answer":2,"explanation":"A large gap of profit over operating cash (high accruals) is a classic warning sign that earnings may not convert to cash. N's cash backing of earnings is stronger.","difficulty":"hard","source":"MBA finance · Big 4 advisory"},
  {"id":"mgmt-finance-392","question":"A firm with EPS of ₹10 (next year) currently pays out all earnings and its share is worth ₹80 (r = 12.5%). It switches to paying out 40% and reinvesting the rest at an ROE of 12.5% forever. What is the new share value?","options":["₹100.00","₹53.33","₹64.00","₹80.00"],"answer":3,"explanation":"g = 0.6 × 12.5% = 7.5%; value = 4/(0.125 − 0.075) = ₹80. When ROE equals the cost of equity, retention adds growth but no value; ₹53.33 divides ₹4 by 7.5%.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-393","question":"Assets A (σ = 30%) and B (σ = 20%) have a correlation of −1. What weight in A produces a portfolio with zero risk?","options":["40%","60%","50%","30.8%"],"answer":0,"explanation":"With ρ = −1, σp = |w × 30 − (1 − w) × 20| = 0 when w = 20/(30 + 20) = 40%. 60% puts more in the riskier asset; 30.8% is the uncorrelated minimum-variance weight.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-394","question":"A fund returned 14% with a standard deviation of 25%. The market returned 11% with a standard deviation of 20%, and the risk-free rate was 6%. What is the fund's M² (Modigliani) measure relative to the market?","options":["+3.0 percentage points","+1.4 percentage points","+1.8 percentage points","+0.07 percentage points"],"answer":1,"explanation":"Fund Sharpe = 8/25 = 0.32. Lever it to the market's 20% risk: return = 6 + 0.32 × 20 = 12.4%; M² = 12.4 − 11 = +1.4 pp. The raw 3-point excess ignores the fund's extra risk.","difficulty":"very-hard","source":"IB analyst test · Asset management"},
  {"id":"mgmt-finance-395","question":"Portfolio A returned 15% with a beta of 1.5; portfolio B returned 12% with a beta of 0.8. The risk-free rate is 6% and the market returned 12%. Ranked by the Treynor ratio, which is correct?","options":["A ranks first (9.0 vs 6.0), beating the market","A and B tie at 7.5, both beating the market (6.0)","B ranks first (7.5); A merely matches the market","B ranks first (15.0), then A (10.0), using R ÷ β"],"answer":2,"explanation":"Treynor = (R − Rf)/β: A = 9/1.5 = 6.0, B = 6/0.8 = 7.5, market = 6/1 = 6.0. B earns the most excess return per unit of systematic risk; A merely matches the market.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-396","question":"An active fund beat its benchmark by an average of 2% a year with a tracking error of 4%. Another fund beat its benchmark by 3% with a tracking error of 8%. Which has the better information ratio?","options":["The second (0.375 vs 0.50)","The second, because its active return is higher","They are equal, because both have positive alpha","The first (0.50 vs 0.375)"],"answer":3,"explanation":"Information ratio = active return/tracking error: 2/4 = 0.50 versus 3/8 = 0.375. The higher active return came with disproportionately more active risk.","difficulty":"moderate","source":"IB analyst test · Asset management"},
  {"id":"mgmt-finance-397","question":"The market portfolio has an expected return of 12% and σ = 20%; the risk-free rate is 6%. An investor on the capital market line wants σ = 15%. What is her expected return and how much does she put in the market portfolio?","options":["10.5%, with 75% in the market","9.0%, with 75% in the market","10.5%, with 25% in the market","15.0%, with 125% in the market"],"answer":0,"explanation":"Weight in market = 15/20 = 75%; return = 6 + 0.75 × (12 − 6) = 10.5%. The CML slope is (12 − 6)/20 = 0.3 per unit of σ.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-398","question":"With a risk-free rate of 6% and the market at E(R) = 12%, σ = 20%, an investor borrows at the risk-free rate to reach σ = 30%. What is her expected return?","options":["18%","15%","12%","13.5%"],"answer":1,"explanation":"Weight in the market = 30/20 = 150% (borrowing 50%). E(R) = 6 + 1.5 × 6 = 15%. 18% scales the whole 12% by 1.5 and forgets the cost of borrowing.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-399","question":"A stock's returns have σ = 30% and a correlation of 0.6 with the market, whose σ is 20%. What is the stock's beta?","options":["1.50","0.60","0.90","0.40"],"answer":2,"explanation":"β = ρ × σᵢ/σₘ = 0.6 × 30/20 = 0.90. 1.50 omits the correlation; a high-volatility stock can have a beta below 1.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-400","question":"An investment returned a total of 30% over 18 months. What is its annualised (compound) return?","options":["20.00%","22.00%","15.00%","19.11%"],"answer":3,"explanation":"Annualised = (1.30)^(12/18) − 1 = 19.11%. Simple division (30%/1.5 = 20%) ignores compounding; 15% treats 18 months as two years.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-401","question":"An investor buys one share for ₹100. After one year it is worth ₹120 and she buys a second share at ₹120. At the end of year 2 she sells both at ₹130 each. No dividends. What are her annual time-weighted and money-weighted returns?","options":["TWR 14.02%; MWR 12.05%","TWR 12.05%; MWR 14.02%","TWR 15.00%; MWR 12.05%","TWR 14.02%; MWR 15.00%"],"answer":0,"explanation":"TWR links sub-period returns: √(1.20 × 1.0833) − 1 = 14.02%. MWR is the IRR of −100, −120, +260 = 12.05%, lower because more money was invested before the weaker second year.","difficulty":"very-hard","source":"IB analyst test · Asset management"},
  {"id":"mgmt-finance-402","question":"Stocks in a market have an average variance of 0.09 and an average pairwise covariance of 0.02. What is the standard deviation of an equally weighted portfolio of 10 such stocks, and the lowest it can reach with very many stocks?","options":["9.49% and 0","16.43% and 14.14%","2.70% and 2.00%","17.03% and 14.14%"],"answer":1,"explanation":"σp² = σ̄²/N + (1 − 1/N) × cov = 0.009 + 0.018 = 0.027, so σp = 16.43%. As N grows only the average covariance remains: √0.02 = 14.14% (systematic risk cannot be diversified away).","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-403","question":"An investor wants to minimise the chance of a return below 5%. Portfolio A: E(R) 12%, σ 15%. Portfolio B: E(R) 10%, σ 8%. Portfolio C: E(R) 14%, σ 20%. By Roy's safety-first criterion, which should she choose?","options":["C, because it has the highest expected return","A (ratio 0.80)","B (ratio 0.625)","A, because its Sharpe-like ratio is 0.47"],"answer":2,"explanation":"SFRatio = (E(R) − threshold)/σ: A = 7/15 = 0.467, B = 5/8 = 0.625, C = 9/20 = 0.45. Highest ratio = lowest shortfall probability under normality, so B.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-404","question":"An investor's utility is U = E(R) − 0.5 × A × σ² with risk aversion A = 4. Which portfolio should she prefer: X (E = 10%, σ = 12%), Y (E = 14%, σ = 22%) or Z (E = 12%, σ = 16%)?","options":["Y (U = 0.0432)","Z (U = 0.0688)","Y, because it has the highest return per unit of risk","X (U = 0.0712)"],"answer":3,"explanation":"U_X = 0.10 − 2 × 0.0144 = 0.0712; U_Y = 0.14 − 2 × 0.0484 = 0.0432; U_Z = 0.12 − 2 × 0.0256 = 0.0688. X gives the highest certainty-equivalent return for this fairly risk-averse investor.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-405","question":"A ₹10 crore portfolio has a daily return standard deviation of 1.5% and a mean daily return of about zero. Assuming normality, what are its 1-day and 10-day 95% value at risk (VaR)?","options":["₹24,67,500 and ₹78,02,920","₹24,67,500 and ₹2,46,75,000","₹29,40,000 and ₹92,97,096","₹34,95,000 and ₹1,10,52,160"],"answer":0,"explanation":"One-tailed 95% z = 1.645: VaR = 1.645 × 1.5% × ₹10 crore = ₹24,67,500. Scale by √10 for 10 days: ₹78,02,920. Multiplying by 10 assumes losses add linearly; 1.96 is a two-tailed value.","difficulty":"very-hard","source":"Bank MT · Risk management"},
  {"id":"mgmt-finance-406","question":"An investor puts 70% of her money in a stock with a beta of 1.4 and 30% in Treasury bills. What is the portfolio's beta?","options":["1.40","0.98","1.28","0.70"],"answer":1,"explanation":"Treasury bills have a beta of 0, so βp = 0.7 × 1.4 + 0.3 × 0 = 0.98. Treating the T-bill beta as 1 gives 1.28.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-407","question":"A portfolio's annual return is normally distributed with a mean of 10% and a standard deviation of 20%. What is the probability that it loses money in a year?","options":["15.87%","50.00%","30.85%","15.43%"],"answer":2,"explanation":"z = (0 − 10)/20 = −0.5; P(Z < −0.5) = 30.85%. A one-standard-deviation cut-off (z = −1) would give 15.87%, which is the probability of losing more than 10%.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-408","question":"Under the CAPM, a stock with a NEGATIVE beta should have an expected return that is:","options":["Equal to the risk-free rate, because negative risk cannot be priced","Above the market return, because it is unusual","Negative in every period","Below the risk-free rate, because it hedges market risk"],"answer":3,"explanation":"E(R) = Rf + β(Rm − Rf) is below Rf when β < 0. Investors accept a lower return because the asset tends to pay off when the market falls, acting as insurance.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-409","question":"An investor buys shares worth ₹2 lakh with 50% initial margin, borrowing the rest at 8% a year. The share price rises 10% over the year (no dividends). What is her return on equity?","options":["12%","20%","10%","16%"],"answer":0,"explanation":"Gain = ₹20,000; interest = 8% × ₹1 lakh = ₹8,000; return = 12,000/1,00,000 = 12%. 20% ignores the borrowing cost.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-410","question":"An investor buys a share at ₹200 with 50% initial margin. The maintenance margin is 30%. Below what price will she receive a margin call?","options":["₹140.00","₹142.86","₹100.00","₹171.43"],"answer":1,"explanation":"Loan per share = ₹100. Call when (P − 100)/P = 0.30, i.e. P = 100/0.70 = ₹142.86. ₹140 applies the 30% to the original price.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-411","question":"An investor short-sells 100 shares at ₹500, posting 50% margin. The company pays a dividend of ₹10 a share and she covers at ₹450. Ignoring interest, what is her return on the margin posted?","options":["20%","10%","16%","8%"],"answer":2,"explanation":"Profit = (500 − 450 − 10) × 100 = ₹4,000 on margin of ₹25,000 = 16%. The short seller must pay the dividend; ignoring it gives 20%.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-412","question":"Under a two-factor APT model, the risk-free rate is 5%, the factor risk premiums are 4% (GDP) and 2% (inflation), and a stock's sensitivities are 1.2 and 0.5. What is its expected return?","options":["11.0%","15.8%","6.8%","10.8%"],"answer":3,"explanation":"E(R) = 5 + 1.2 × 4 + 0.5 × 2 = 10.8%. Adding the raw premiums (5 + 4 + 2 = 11%) ignores sensitivities.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-413","question":"A stock's daily return volatility is 1.2%. Assuming 250 trading days and independent returns, what is its annualised volatility?","options":["18.97%","300.00%","22.93%","4.16%"],"answer":0,"explanation":"Variance scales with time, so σ scales with √time: 1.2% × √250 = 18.97%. Multiplying by 250 treats volatility as additive.","difficulty":"moderate","source":"Bank MT · Risk management"},
  {"id":"mgmt-finance-414","question":"In a boom (probability 0.3), normal year (0.4) and recession (0.3), stock A returns 20%, 10% and −5%, and stock B returns 5%, 8% and 12%. What is the covariance of their returns (in %²) and their correlation?","options":["−13.89 and −0.471","−12.00 and −0.424","−12.00 and −0.015","−41.50 and −0.424"],"answer":1,"explanation":"E(A) = 8.5%, E(B) = 9.0%; cov = Σ p(Aᵢ − E(A))(Bᵢ − E(B)) = −12.00; σA = 9.76, σB = 2.90, so ρ = −0.424. The negative correlation makes B a useful diversifier; ignoring the probabilities (equal weights) gives a different answer.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-415","question":"Asset A has σ = 25% and asset B has σ = 15%; their correlation is 0.2. What weight in A gives the minimum-variance portfolio of the two?","options":["26.5%","37.5%","21.4%","78.6%"],"answer":2,"explanation":"w_A = (σB² − ρσAσB)/(σA² + σB² − 2ρσAσB) = (0.0225 − 0.0075)/(0.0625 + 0.0225 − 0.015) = 21.4%. Ignoring correlation gives 26.5%.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-416","question":"An investor holds on to shares that have fallen well below her purchase price 'until they get back to what I paid', while quickly selling shares that have risen. Which bias does this best describe?","options":["Overconfidence (illusion of control)","Herding (following the crowd)","Confirmation bias (selective evidence)","Disposition effect (loss aversion)"],"answer":3,"explanation":"The disposition effect is the tendency to realise gains too early and hold losers too long, driven by loss aversion and anchoring on the purchase price.","difficulty":"moderate","source":"IB analyst test · Asset management"},
  {"id":"mgmt-finance-417","question":"If a market is semi-strong-form efficient, which statement is correct?","options":["Public-information analysis cannot beat the market; inside information might","Technical analysis fails, but fundamental analysis of public data still works","No investor can ever earn excess returns, even with inside information","Only the weak form implies a random walk, so trend-following still pays"],"answer":0,"explanation":"Semi-strong efficiency means prices reflect all public information (past prices and published data). Only strong-form efficiency rules out profits from private (insider) information.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-418","question":"A fund returned 12% with a standard deviation of 16% and a downside deviation (below a 5% minimum acceptable return) of 10%. The risk-free rate is 6%. What are its Sharpe and Sortino ratios?","options":["Sharpe 0.44; Sortino 0.60","Sharpe 0.375; Sortino 0.70","Sharpe 0.375; Sortino 0.60","Sharpe 0.70; Sortino 0.375"],"answer":1,"explanation":"Sharpe = (12 − 6)/16 = 0.375. Sortino = (12 − MAR 5)/downside deviation 10 = 0.70; it penalises only harmful volatility and measures excess over the MAR, not the risk-free rate.","difficulty":"hard","source":"IB analyst test · Asset management"},
  {"id":"mgmt-finance-419","question":"An investor's entire wealth is in a single sector fund. Which performance measure best captures the risk she actually bears?","options":["The Treynor ratio, because only beta risk is priced in markets","Jensen's alpha, because it adjusts for beta","The Sharpe ratio, as her total risk includes unsystematic risk","The information ratio against a broad market index"],"answer":2,"explanation":"Treynor and alpha use beta, which suits a fund held within a diversified portfolio. For an undiversified holding, total volatility matters, so the Sharpe ratio is appropriate.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-420","question":"An index rises 10% on day 1 and falls 10% on day 2. A 2× daily-leveraged fund tracks it exactly each day. Over the two days, what are the index's and the fund's cumulative returns?","options":["Index −1.00%; fund −2.00%","Index 0.00%; fund 0.00%","Index −1.00%; fund +0.00%","Index −1.00%; fund −4.00%"],"answer":3,"explanation":"Index: 1.10 × 0.90 − 1 = −1%. Fund: 1.20 × 0.80 − 1 = −4%, worse than 2 × (−1%) because daily rebalancing compounds volatility (volatility decay).","difficulty":"very-hard","source":"IB analyst test · Asset management"},
  {"id":"mgmt-finance-421","question":"A bond fund is expected to return 8% and an equity fund 15%. What proportion in the equity fund gives a portfolio expected return of 12%?","options":["57.14%","42.86%","80.00%","50.00%"],"answer":0,"explanation":"Solve 8 + w(15 − 8) = 12: w = 4/7 = 57.14% in equity. 42.86% is the bond weight.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-422","question":"A price-weighted index has three stocks priced ₹100, ₹50 and ₹30, with a divisor of 3 (index = 60). The ₹100 stock then splits 2-for-1. The next day the prices are ₹55, ₹50 and ₹33. What is the index value?","options":["46.00","63.69","64.33","64.00"],"answer":1,"explanation":"After the split the divisor must keep the index at 60: (50 + 50 + 30)/d = 60, so d = 2.1667. Next day: 138/2.1667 = 63.69. Keeping divisor 3 makes the split look like a crash.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-423","question":"An index contains stock P (market cap ₹800 crore, return +5%) and stock Q (market cap ₹200 crore, return +20%). What are the equal-weighted and value-weighted index returns?","options":["8.0% and 12.5%","12.5% and 17.0%","12.5% and 8.0%","12.5% and 12.5%"],"answer":2,"explanation":"Equal weighting: (5 + 20)/2 = 12.5%. Value weighting: 0.8 × 5 + 0.2 × 20 = 8%. Small-cap outperformance lifts the equal-weighted index.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-424","question":"Two well-diversified portfolios both have a beta of 1.0; X is expected to return 12% and Y 10%. What does arbitrage pricing theory imply?","options":["No arbitrage, because their returns differ only by chance","Buy Y, because its lower expected return means lower risk","None, as arbitrage requires portfolios with different betas","Buy X, short Y: a riskless 2% on zero net investment"],"answer":3,"explanation":"Equal betas on well-diversified portfolios mean equal systematic risk and no diversifiable risk, so they must offer the same expected return. Long X/short Y earns 2% riskless until prices adjust.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-425","question":"A portfolio manager earned 18% with a beta of 1.3. The risk-free rate was 6% and the market returned 13%. Which statement is correct?","options":["Alpha is +2.9%, and Treynor (9.23) beats the market's 7.00","Alpha is +5.0%, because 18 − 13 = 5 percentage points","Alpha is −2.9% after the return is adjusted for beta","Alpha is +2.9% but the Treynor ratio trails the market's 7.00"],"answer":0,"explanation":"Required = 6 + 1.3 × 7 = 15.1%; alpha = 18 − 15.1 = +2.9%. Treynor = 12/1.3 = 9.23 > 7.00 for the market, consistent with positive alpha.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-426","question":"A risky portfolio offers E(R) = 14% with σ = 20%; the risk-free rate is 6%. An investor with risk-aversion coefficient A = 3 (U = E − 0.5Aσ²) chooses how much to put in the risky portfolio. What is her optimal weight?","options":["40.0%","66.7%","133.3%","33.3%"],"answer":1,"explanation":"Optimal y* = (E(R) − Rf)/(Aσ²) = 0.08/(3 × 0.04) = 66.7%, so she keeps 33.3% in the risk-free asset. Including the ½ in the denominator doubles the answer.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-427","question":"Which of the following is an example of unsystematic (diversifiable) risk for an Indian cement company?","options":["A rise in the RBI's policy repo rate","A nationwide recession hitting demand","A fire that shuts down one of its plants","A general rise in inflation across the economy"],"answer":2,"explanation":"Firm-specific events such as a plant fire can be diversified away across many stocks. Interest rates, recessions and inflation affect most firms together, so they are systematic.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-428","question":"An investor puts ₹6 lakh in a risky fund (E(R) = 13%, σ = 18%) and ₹4 lakh in a risk-free deposit at 6%. What are her portfolio's expected return and standard deviation?","options":["10.2% and 18.0%","9.5% and 10.8%","10.2% and 7.2%","10.2% and 10.8%"],"answer":3,"explanation":"Weights 0.6/0.4: E = 0.6 × 13 + 0.4 × 6 = 10.2%; σ = 0.6 × 18 = 10.8% because the risk-free asset has zero variance and zero covariance.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-429","question":"Over 3 years an investor earns 15%, −10% and 20%, while inflation runs at 5% each year. What is her annualised real return?","options":["2.37%","3.33%","2.49%","7.49%"],"answer":0,"explanation":"Nominal CAGR = (1.15 × 0.90 × 1.20)^(1/3) − 1 = 7.49%; real = (1 + nominal)/1.05 − 1 = 2.37%. Subtracting 5% approximates; the arithmetic average ignores compounding.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-430","question":"A share now at ₹210 is expected to pay a ₹5 dividend and trade at ₹240 in a year. Its beta is 1.2, the risk-free rate 6% and the market risk premium 8%. Which statement is correct?","options":["16.67% expected vs 15.60% required: below the SML, so sell","16.67% expected vs 15.60% required: above the SML, so buy","14.29% expected vs 15.60% required: below the SML, so sell","Required return is 21.60%, so the share is fairly priced"],"answer":1,"explanation":"Expected return = (240 − 210 + 5)/210 = 16.67%; CAPM required = 6 + 1.2 × 8 = 15.60%. Leaving out the dividend (14.29%) reverses the conclusion.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-431","question":"Which statements about a two-asset portfolio are correct? I. If ρ = +1, the portfolio σ is the weighted average of the two σs. II. Any ρ < +1 gives some diversification benefit. III. With ρ = 0, a portfolio can never have lower σ than the less risky asset.","options":["I, II and III","II and III only","I and II only","I only"],"answer":2,"explanation":"With ρ = +1 there is no diversification, so σ is the weighted average; any ρ below 1 lowers σ below that average. With ρ = 0 the minimum-variance portfolio has σ below the less risky asset's σ, so III is false.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-432","question":"A regression of a stock's excess returns on the market's excess returns gives an intercept of 0.4% a month and a slope of 1.1, with R² = 0.36. Which interpretation is correct?","options":["Beta is 0.36 and the monthly alpha is 1.1%","Correlation with the market is 0.36, while beta is 1.1 and alpha 0.4%","Beta is 1.1 and 64% of the stock's total risk is systematic","Beta 1.1, alpha 0.4% a month; market explains 36% of variance"],"answer":3,"explanation":"In the characteristic line, the slope is beta and the intercept is Jensen's alpha. R² is the share of variance that is systematic (36%); correlation is √0.36 = 0.6, and 64% is diversifiable.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-433","question":"A share is at ₹100. In one year it will be ₹120 or ₹90. The risk-free rate is 5% (annual). Using a one-period binomial model, what is a one-year European call with strike ₹105 worth?","options":["₹7.14","₹9.52","₹7.50","₹14.29"],"answer":0,"explanation":"Risk-neutral probability of an up-move = (1.05 − 0.90)/(1.20 − 0.90) = 0.50. Call = (0.50 × 15 + 0.50 × 0)/1.05 = ₹7.14. Using the real-world probability or skipping the discounting is wrong.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-434","question":"In a one-period binomial model the share is at ₹100 and will move to ₹120 or ₹90. To hedge one written call with strike ₹105, how many shares must be bought, and what is the hedged portfolio worth at expiry in either state?","options":["1 share; ₹105 in both states","0.5 share; ₹45 in both states","0.5 share; ₹60 or ₹45","0.33 share; ₹30 in both states"],"answer":1,"explanation":"Delta = (15 − 0)/(120 − 90) = 0.5. Long 0.5 share, short one call: up = 60 − 15 = 45, down = 45 − 0 = 45. The riskless payoff is what lets the call be priced by discounting at the risk-free rate.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-435","question":"A share is at ₹100 and will be ₹120 or ₹90 in one year; the risk-free rate is 5%. What are the binomial values of one-year European call and put options, both with strike ₹110?","options":["Call ₹9.52; put ₹4.76","Call ₹4.76; put ₹4.76","Call ₹4.76; put ₹9.52","Call ₹5.00; put ₹10.00"],"answer":2,"explanation":"With q = 0.5: call = 0.5 × 10/1.05 = ₹4.76; put = 0.5 × 20/1.05 = ₹9.52. Check with put-call parity: C − P = S − K/1.05 = 100 − 104.76 = −4.76.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-436","question":"Three months ago a trader entered a long 6-month forward on a non-dividend share at ₹520. The share is now ₹530 and the risk-free rate is 8% a year (annual compounding). What is the forward contract worth to the trader today?","options":["₹10.00","₹20.30","₹29.63","₹19.91"],"answer":3,"explanation":"Value of a long forward = S₀ − K/(1 + r)^T = 530 − 520/1.08^0.25 = ₹19.91. The ₹10 spot difference ignores that ₹520 is paid only in three months.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-437","question":"A company buys (goes long) a 3×6 FRA on ₹10 crore at a contract rate of 7% to hedge future borrowing. On the settlement date the 3-month reference rate is 8%. Using a 90/360 day count with settlement at the start of the borrowing period, what does the company receive?","options":["₹2,45,098","₹2,50,000","₹10,00,000","₹2,31,481"],"answer":0,"explanation":"Interest difference = 10 crore × 1% × 90/360 = ₹2,50,000, paid at the end of the period, so discount it for three months: 2,50,000/(1 + 0.08 × 0.25) = ₹2,45,098. The long (borrower) receives because rates rose.","difficulty":"very-hard","source":"Bank MT · Treasury · FRM pattern"},
  {"id":"mgmt-finance-438","question":"Discount factors for 1, 2 and 3 years are 0.95, 0.90 and 0.85. What is the fixed rate on a 3-year plain-vanilla interest rate swap with annual payments?","options":["5.567%","5.556%","5.000%","5.263%"],"answer":1,"explanation":"The fixed leg must equal par: rate = (1 − DF₃)/(DF₁ + DF₂ + DF₃) = 0.15/2.70 = 5.556%. The 3-year zero rate (5.567%) is not the par swap rate.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-439","question":"A trader buys a ₹90-strike put for ₹3 and a ₹110-strike call for ₹4 on the same share and expiry. What are the break-even prices at expiry and the maximum loss?","options":["₹87 and ₹114; maximum loss ₹7","₹83 and ₹117; maximum loss ₹20","₹83 and ₹117; maximum loss ₹7","₹86 and ₹113; maximum loss ₹4"],"answer":2,"explanation":"Total premium = ₹7. Lower break-even = 90 − 7 = 83; upper = 110 + 7 = 117. Between ₹90 and ₹110 both options expire worthless, so the most the trader can lose is ₹7.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-440","question":"A trader buys a ₹90 call for ₹14, sells two ₹100 calls for ₹8 each and buys a ₹110 call for ₹4 (same share and expiry). What are the maximum profit and the break-even prices at expiry?","options":["₹10 at ₹100; break-evens ₹90 and ₹110","₹8 at ₹100; break-evens ₹90 and ₹110","₹6 at ₹100; break-evens ₹94 and ₹106","₹8 at ₹100; break-evens ₹92 and ₹108"],"answer":3,"explanation":"Net cost = 14 − 16 + 4 = ₹2. At ₹100 the payoff is 10, so profit = 8. Break-evens = 90 + 2 = 92 and 110 − 2 = 108; beyond the wings the loss is limited to ₹2.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-441","question":"An investor buys a ₹120-strike put for ₹12 and sells a ₹100-strike put for ₹4 on the same share and expiry. What are the maximum profit, maximum loss and break-even price?","options":["Max profit ₹12; max loss ₹8; break-even ₹112","Max profit ₹20; max loss ₹8; break-even ₹112","Max profit ₹12; max loss ₹8; break-even ₹108","Max profit ₹16; max loss ₹4; break-even ₹116"],"answer":0,"explanation":"Net cost = 12 − 4 = ₹8. Maximum payoff = strike difference 20, so maximum profit = 12 (at ₹100 or below). Break-even = higher strike − net cost = 120 − 8 = ₹112.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-442","question":"An investor owns a share bought at ₹500. She buys a ₹480-strike put for ₹10 and sells a ₹540-strike call for ₹12 (same expiry). What are her maximum loss and maximum gain at expiry?","options":["Max loss ₹20; max gain ₹40","Max loss ₹18; max gain ₹42","Max loss ₹22; max gain ₹38","Max loss ₹30; max gain ₹52"],"answer":1,"explanation":"The collar gives a net credit of ₹2. Floor: 480 − 500 + 2 = −18. Cap: 540 − 500 + 2 = +42. Ignoring the premiums gives −20/+40.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-443","question":"A farmer sells wheat futures at ₹2,500 a quintal to hedge his harvest. At harvest the spot price is ₹2,380 and the futures price ₹2,410; he sells his wheat in the spot market and closes the futures. What effective price does he receive?","options":["₹2,500","₹2,380","₹2,470","₹2,410"],"answer":2,"explanation":"Futures gain = 2,500 − 2,410 = ₹90; effective price = 2,380 + 90 = ₹2,470 = initial futures price + closing basis (2,380 − 2,410 = −30). The hedge removes price risk but leaves basis risk.","difficulty":"hard","source":"IB analyst test · Treasury"},
  {"id":"mgmt-finance-444","question":"Other things equal, which change raises the value of a European call AND lowers the value of a European put on the same non-dividend share?","options":["A rise in the volatility of the share","A longer time to expiry","A higher strike price","A rise in the risk-free interest rate"],"answer":3,"explanation":"Higher rates reduce the PV of the strike, helping calls and hurting puts. Volatility raises both; a higher strike lowers calls and raises puts; time generally raises both (for European puts it can cut either way).","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-445","question":"Why is it never optimal to exercise an American call on a non-dividend-paying share before expiry?","options":["The call is worth at least S − PV(K), which exceeds S − K","Because early exercise is prohibited by the exchange","Because the call's delta is always below 1 before its expiry","Because the share price is expected to fall over time"],"answer":0,"explanation":"A call's value is at least S − K/(1 + r)^T, which exceeds the exercise value S − K when rates are positive; early exercise also gives up the remaining time value. Dividends can change this.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-446","question":"Assertion (A): A deep in-the-money European put on a non-dividend share can trade below its intrinsic value (K − S). Reason (R): The European holder must wait until expiry to receive K, so the lower bound is K/(1 + r)^T − S, not K − S.","options":["Both are true, but R does not explain A","Both A and R are true, and R explains A","A is false, because arbitrageurs would exercise immediately","A is true, R is false"],"answer":1,"explanation":"The European put cannot be exercised early, so its value is bounded by the PV of the strike less the share price, which is less than K − S when rates are positive. An American put would be exercised instead.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-447","question":"A one-year European call on a non-dividend share has a strike of ₹95. The share is ₹100 and the risk-free rate is 8%. What is the lowest price the call can trade at without arbitrage?","options":["₹5.00","₹4.63","₹12.04","₹0.00"],"answer":2,"explanation":"Lower bound = S − K/(1 + r)^T = 100 − 95/1.08 = ₹12.04. The intrinsic value of ₹5 is a weaker bound for a European call.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-448","question":"A one-year European put has a strike of ₹110 on a non-dividend share priced at ₹95. The risk-free rate is 10%. What is the no-arbitrage lower bound on the put's price?","options":["₹15.00","₹13.64","₹0.00","₹5.00"],"answer":3,"explanation":"Lower bound = K/(1 + r)^T − S = 100 − 95 = ₹5.00, below the intrinsic ₹15 because the strike is received only at expiry.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-449","question":"A dealer has sold 50 call contracts, each on 100 shares; the call delta is 0.6. How should she delta-hedge, and how does the hedge change if delta rises to 0.7?","options":["Buy 3,000 shares, then buy 500 more","Sell 3,000 shares, then sell 500 more","Buy 5,000 shares and hold","Buy 3,000 shares, then sell 500"],"answer":0,"explanation":"Short calls lose when the share rises, so she buys delta × 5,000 = 3,000 shares. When delta rises to 0.7 she needs 3,500 shares, so buys 500 more (short gamma: she buys high and sells low).","difficulty":"moderate","source":"IB analyst test · Treasury"},
  {"id":"mgmt-finance-450","question":"A bank receives 7% fixed and pays floating on a ₹100 crore interest-rate swap with exactly 2 annual payments left (a floating reset has just occurred). Two-year swap rates have risen to 8% (flat curve). What is the swap worth to the bank?","options":["₹1.78 crore in the bank's favour","−₹1.78 crore (a loss to the bank)","−₹2.00 crore (1% × ₹100 crore × 2)","−₹1.65 crore (a loss to the bank)"],"answer":1,"explanation":"Receive-fixed = long a fixed bond, short a floater worth par. Fixed leg = 7/1.08 + 107/1.08² = 98.22; value = 98.22 − 100 = −₹1.78 crore. Rising rates hurt the fixed receiver.","difficulty":"very-hard","source":"Bank MT · Treasury · FRM pattern"},
  {"id":"mgmt-finance-451","question":"An importer must pay $1 lakh in 3 months. She buys a USD call (right to buy dollars) with strike ₹84.00 for a premium of ₹0.50 per dollar. If the spot rate at maturity is ₹83.00, what is her effective cost per dollar (ignoring time value of the premium)?","options":["₹84.50","₹84.00","₹83.50","₹83.00"],"answer":2,"explanation":"She lets the option lapse and buys at spot ₹83.00, plus the ₹0.50 premium: ₹83.50. Had spot been above ₹84, her cost would cap at ₹84.50; that asymmetry is the option's advantage over a forward.","difficulty":"hard","source":"IB analyst test · Treasury"},
  {"id":"mgmt-finance-452","question":"Gold is ₹50,000 per 10 g spot. Storage and insurance cost ₹500 per 10 g, payable at the end of 6 months. The risk-free rate is 8% a year (annual compounding). What is the no-arbitrage 6-month futures price?","options":["₹51,961.52","₹52,500.00","₹52,481.14","₹52,461.52"],"answer":3,"explanation":"F = S × (1 + r)^T + storage paid at expiry = 50,000 × 1.08^0.5 + 500 = ₹52,461.52. Compounding the storage cost too would apply only if it were paid upfront.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-453","question":"Crude oil futures for delivery in 6 months trade BELOW the spot price even though interest and storage costs are positive. Which explanation is most consistent with cost-of-carry theory?","options":["A high convenience yield from holding physical oil","Arbitrageurs are buying spot and selling futures","Futures markets always predict price falls accurately","Interest rates must be negative"],"answer":0,"explanation":"F = S × e^((r + storage − convenience yield)T). When the benefit of having the physical commodity (convenience yield) exceeds carrying costs, futures trade below spot (backwardation).","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-454","question":"A trader writes a put with strike ₹200 for a premium of ₹9. At expiry the share is at ₹180. What is the trader's profit or loss, and what is her break-even price?","options":["Loss of ₹20; break-even ₹209","Loss of ₹11; break-even ₹191","Profit of ₹9; break-even ₹191","Loss of ₹29; break-even ₹191"],"answer":1,"explanation":"The put is exercised: she pays 200 for a share worth 180 (−20) but kept the ₹9 premium, so −₹11. Break-even = 200 − 9 = ₹191.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-455","question":"An Indian importer must pay $10 lakh in 6 months. Spot is ₹83.00/$. Six-month interest rates are 4% a year in the US and 7% a year in India (simple, pro-rated). Using a money-market hedge (borrow rupees, convert, invest dollars), what is the effective rupee cost per dollar?","options":["₹85.90","₹85.49","₹84.22","₹85.39"],"answer":2,"explanation":"Invest 10 lakh/1.02 = $9,80,392 today, costing ₹8,13,72,549, borrowed at 3.5% for 6 months: repay ₹8,42,20,588, i.e. ₹84.22 per dollar, equal to the parity forward rate.","difficulty":"very-hard","source":"IB analyst test · Treasury"},
  {"id":"mgmt-finance-456","question":"A borrower has a ₹50 crore floating-rate loan reset quarterly and buys a cap at 8%. For one quarter the reference rate is 9%. Using a 90/360 day count, what does the cap pay for that quarter?","options":["₹50 lakh","₹1.25 crore","₹4.17 lakh","₹12.5 lakh"],"answer":3,"explanation":"Cap payoff = notional × (rate − cap rate) × period = 50 crore × 1% × 0.25 = ₹12.5 lakh. ₹50 lakh forgets that the rate applies to a quarter only.","difficulty":"hard","source":"Bank MT · Treasury · FRM pattern"},
  {"id":"mgmt-finance-457","question":"A European call on a non-dividend share has a delta of 0.62. What is the delta of a European put with the same strike and expiry, and what does it mean?","options":["−0.38: the put loses about ₹0.38 per ₹1 rise in the share","+0.38: the put gains about ₹0.38 per ₹1 rise in the share","−0.62: the put moves exactly opposite to the call","1.62: puts are more sensitive than calls to the share"],"answer":0,"explanation":"Put-call parity (C − P = S − PV(K)) implies Δ_put = Δ_call − 1 = −0.38. A put falls as the share rises.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-458","question":"A trader buys an at-the-money straddle. Which describes the position's main risk exposures?","options":["Short gamma and short vega, long theta","Long gamma and long vega, short theta","Large positive delta and long vega","Long theta and short vega"],"answer":1,"explanation":"Owning both options benefits from big moves (long gamma) and rising volatility (long vega), while time decay erodes both premiums every day (short theta). Its delta is close to zero.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-459","question":"Using European options on the same share, strike and expiry, which combination replicates a long forward contract (to buy at the strike)?","options":["Long a put and short a call","Long a call and long a put","Long a call and short a put","Short a call and long the share"],"answer":2,"explanation":"Payoff of long call − short put at expiry = S − K whatever the price, exactly a forward to buy at K. Short call + long share is a covered call.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-460","question":"The spot rate is ₹83.20/$ and 3-month forward points are +45 paise. What is the 3-month outright forward rate and the annualised forward premium on the dollar?","options":["₹82.75; 2.16%","₹83.65; 0.54%","₹83.65; 6.49%","₹83.65; 2.16%"],"answer":3,"explanation":"Outright = 83.20 + 0.45 = ₹83.65; premium = (0.45/83.20) × (12/3) = 2.16% a year. Not annualising gives 0.54%.","difficulty":"moderate","source":"IB analyst test · Treasury"},
  {"id":"mgmt-finance-461","question":"A trader goes long 2 futures lots of 100 units each at ₹1,000. Initial margin is ₹30,000 and maintenance margin ₹20,000 for the position. Settlement prices are ₹985 on day 1 and ₹940 on day 2. What margin call (variation margin) does she receive, and on which day?","options":["₹12,000 on day 2","₹2,000 on day 2","₹12,000 on day 1","₹10,000 on day 2"],"answer":0,"explanation":"Day 1: loss 15 × 200 = ₹3,000, balance ₹27,000 (above ₹20,000). Day 2: loss 45 × 200 = ₹9,000, balance ₹18,000 < ₹20,000, so she must top up to the INITIAL margin: ₹12,000, not just to the maintenance level.","difficulty":"very-hard","source":"IB analyst test · Treasury"},
  {"id":"mgmt-finance-462","question":"In a typical fixed-for-fixed currency swap between an Indian firm and a US firm, which statement is correct?","options":["Only net interest in one currency changes hands; principal is never exchanged","Principals are exchanged at inception and swapped back at the initial rate","Principals are re-exchanged at maturity at the spot rate then prevailing","It eliminates the need for any interest payments"],"answer":1,"explanation":"Unlike an interest-rate swap, a currency swap normally exchanges principal at inception and re-exchanges it at the initial rate at maturity, with interest paid in each currency in between.","difficulty":"moderate","source":"Bank MT · Treasury · FRM pattern"},
  {"id":"mgmt-finance-463","question":"A share at ₹100 moves up by 10% or down by 5% each period; the risk-free rate is 3% per period. Using a two-period binomial tree, what is a European call with strike ₹100 expiring in two periods worth?","options":["₹5.63","₹7.97","₹7.74","₹7.07"],"answer":2,"explanation":"q = (1.03 − 0.95)/(1.10 − 0.95) = 0.5333. Terminal prices: 121, 104.5, 90.25 → payoffs 21, 4.5, 0. C = [q² × 21 + 2q(1 − q) × 4.5]/1.03² = ₹7.74. Dropping the middle node or discounting one period only are the traps.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-464","question":"An exporter will receive $5 lakh in 3 months. Which hedge locks in a minimum rupee amount while keeping the upside if the rupee weakens (₹/$ rises)?","options":["Selling the dollars forward","Buying a USD call option","Borrowing dollars today and converting them is not a hedge","Buying a USD put (right to sell dollars at a strike)"],"answer":3,"explanation":"A USD put sets a floor on the rupee value of the receipt but can be left unexercised if the dollar strengthens. A forward locks the rate both ways; a USD call would suit an importer.","difficulty":"hard","source":"IB analyst test · Treasury"},
  {"id":"mgmt-finance-465","question":"An index is at 22,000. The risk-free rate is 7% and the dividend yield 1.5% a year (simple, pro-rated). The 3-month index futures trade at 22,400. What arbitrage is available?","options":["Sell futures and buy the index basket (fair value ≈ 22,302.5)","Buy futures and short the index basket (fair value ≈ 22,302.5)","None, since 22,400 is within the cost of carry","Buy futures and short the basket, because the dividend yield lowers the basket's carry return"],"answer":0,"explanation":"Fair value = 22,000 × [1 + (7% − 1.5%) × 0.25] = 22,302.5. The futures are rich, so cash-and-carry: buy the basket, sell futures, and lock in the 97.5-point mispricing.","difficulty":"very-hard","source":"IB analyst test · Treasury"},
  {"id":"mgmt-finance-466","question":"A firm will receive ₹20 crore in 3 months and plans to deposit it for 6 months. It fears interest rates will fall. Which FRA position hedges this, and when does it gain?","options":["Buy (long) a 3×9 FRA; it gains if rates rise above the FRA rate","Sell a 3×9 FRA; it gains if rates fall below the FRA rate","Sell a 3×6 FRA; it gains if rates rise above the FRA rate","Buy a 6×9 FRA; it gains if rates fall below the FRA rate"],"answer":1,"explanation":"A future depositor is like a lender: the FRA seller (lender) receives when the reference rate settles below the FRA rate. The period starts in 3 months and ends in 9, so it is a 3×9 FRA.","difficulty":"very-hard","source":"Bank MT · Treasury · FRM pattern"},
  {"id":"mgmt-finance-467","question":"A put with strike ₹350 trades at ₹28 when the share is at ₹330. What are its intrinsic value and time value, and is it in the money?","options":["Intrinsic ₹0, time value ₹28; out of the money","Intrinsic ₹20, time value ₹48; in the money","Intrinsic ₹20, time value ₹8; in the money","Intrinsic ₹8, time value ₹20; at the money"],"answer":2,"explanation":"A put is in the money when S < K: intrinsic = 350 − 330 = ₹20; time value = 28 − 20 = ₹8.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-468","question":"An investor buys a share at ₹400 and writes a 3-month call with strike ₹420 for ₹12. If the share is at ₹450 at expiry, what is her 3-month return on the ₹388 net investment?","options":["15.98%","8.00%","12.89%","8.25%"],"answer":3,"explanation":"The call is exercised: she receives ₹420 for the share, having paid 400 − 12 = ₹388 net. Profit = 420 − 388 = ₹32, i.e. 8.25%. The upside above ₹420 belongs to the call buyer.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-469","question":"A jeweller wants to hedge 500 kg of silver purchases. The standard deviation of monthly spot price changes is 2.5%, of futures price changes 2.0%, and their correlation is 0.9. One futures contract covers 30 kg. How many contracts minimise variance (nearest whole)?","options":["19 contracts","17 contracts","15 contracts","12 contracts"],"answer":0,"explanation":"Minimum-variance hedge ratio = ρ × σS/σF = 0.9 × 2.5/2.0 = 1.12; contracts = 1.12 × 500/30 = 18.75 → 19. Inverting the volatility ratio gives 12.","difficulty":"hard","source":"IB analyst test · Treasury"},
  {"id":"mgmt-finance-470","question":"The spot rate is ₹82.00/$. One-year interest rates are 7.5% in India and 4.5% in the US. A bank quotes the one-year forward at ₹85.00/$. What should an arbitrageur do?","options":["Borrow dollars, buy rupees, invest at 7.5% and then buy dollars forward","Borrow rupees, buy dollars, invest at 4.5% and sell dollars forward","Nothing; the forward premium equals the 3% interest differential","Buy dollars forward only, as parity forward is ≈ ₹84.46"],"answer":1,"explanation":"Parity forward = 82 × 1.075/1.045 = ₹84.35. The quoted ₹85.00 is too high, so sell dollars forward: borrow ₹82 at 7.5%, buy $1, grow it to $1.045 and sell forward for ₹88.825, repaying ₹88.15 for a riskless ₹0.675 per dollar.","difficulty":"very-hard","source":"IB analyst test · Treasury"},
  {"id":"mgmt-finance-471","question":"A share trades at ₹150. Which European call premium (any strike, any expiry) would definitely allow riskless arbitrage?","options":["₹149","₹5","₹155","₹60"],"answer":2,"explanation":"A call can never be worth more than the share itself (upper bound C ≤ S). At ₹155 one would sell the call and buy the share, pocketing ₹5 with no risk.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-472","question":"Which statements about hedging with futures are correct? I. A short hedger gains if the basis (spot − futures) strengthens. II. A perfect hedge requires the basis at close-out to be known in advance. III. Cross-hedging with a related commodity's futures adds basis risk.","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":3,"explanation":"A short hedger's effective price = initial futures + closing basis, so a stronger basis helps; certainty requires knowing that basis. Using a different but related asset makes the basis less predictable.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-473","question":"A company has 5 lakh bonds (face ₹1,000) trading at ₹950 with a YTM of 9%, and 2 crore shares (face ₹10) trading at ₹120 with a beta of 1.1. The risk-free rate is 7%, the market risk premium 6% and the tax rate 25%. What is its WACC using market-value weights?","options":["12.47%","12.84%","8.71%","10.18%"],"answer":0,"explanation":"Ke = 7 + 1.1 × 6 = 13.6%; after-tax Kd = 9% × 0.75 = 6.75%. Market values: debt ₹47.50 crore, equity ₹240 crore, so WACC = 12.47%. Book weights or a pre-tax Kd give wrong answers.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-474","question":"A firm's only debt is a 5-year bond with an 8% annual coupon, face ₹1,000, now trading at ₹960. The tax rate is 30%. What after-tax cost of debt should go into its WACC?","options":["5.60%","6.32%","9.03%","5.83%"],"answer":1,"explanation":"The market cost of debt is the YTM, 9.03% (solve 960 = 80 × annuity factor + 1,000/(1 + y)⁵), not the coupon. After tax: 9.03% × 0.70 = 6.32%.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-475","question":"A project has an NPV of ₹2 crore before financing costs. It needs ₹50 crore of new equity, and issue (flotation) costs are 3% of the amount raised. What is the correct treatment, and the resulting NPV?","options":["Raise the cost of equity for all future projects; NPV stays ₹2 crore","Ignore flotation costs because they are financing flows: NPV = ₹2 crore","Deduct ₹1.5 crore of flotation cost upfront: NPV = ₹0.5 crore","Deduct 3% of NPV: NPV = ₹1.94 crore"],"answer":2,"explanation":"The preferred approach treats flotation costs as an actual upfront cash cost of the project (3% × 50 = ₹1.5 crore), giving NPV = ₹0.5 crore, rather than permanently adjusting the cost of capital.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-476","question":"To value an emerging-market project, an analyst uses a developed-market risk-free rate of 4%, a beta of 1.2 and a mature-market equity premium of 5%. The country's sovereign bond spread is 3%, and its equity market is 1.5 times as volatile as its bond market. What cost of equity does the CAPM-with-country-risk approach give?","options":["13.0%","15.4%","10.0%","14.5%"],"answer":3,"explanation":"Country risk premium = sovereign spread × (σ equity/σ bond) = 3% × 1.5 = 4.5%; Ke = 4 + 1.2 × 5 + 4.5 = 14.5%. Adding the raw 3% spread understates the equity risk.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-477","question":"A company's 8% preference shares (face ₹100) trade at ₹90, and its bonds yield 9%. Analysts add a 4% risk premium to the bond yield to estimate the cost of equity. What are the costs of preference capital and of equity?","options":["8.89% and 13.00%","8.00% and 13.00%","8.89% and 12.00%","8.00% and 12.89%"],"answer":0,"explanation":"Kp = dividend/price = 8/90 = 8.89% (preference dividends are not tax-deductible, so no adjustment). Bond-yield-plus-risk-premium: Ke = 9% + 4% = 13%.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-478","question":"Under Modigliani–Miller with corporate taxes, an unlevered firm's cost of equity is 12%. A similar firm has a debt–equity ratio of 1, a cost of debt of 8% and a tax rate of 25%. What is the levered firm's cost of equity?","options":["16.00%","15.00%","12.00%","13.00%"],"answer":1,"explanation":"Proposition II with taxes: Ke = Ku + (Ku − Kd)(1 − t)(D/E) = 12 + 4 × 0.75 × 1 = 15.00%. 16% is the no-tax version.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-479","question":"Continuing with Modigliani–Miller with taxes: Ku = 12%, Kd = 8%, t = 25% and debt is 50% of firm value (D/E = 1). What is the levered firm's WACC?","options":["12.00%","11.50%","10.50%","11.00%"],"answer":2,"explanation":"WACC = 0.5 × 8% × 0.75 + 0.5 × 15% = 10.50%, which equals Ku × (1 − t × D/V) = 12% × 0.875. Using Ke = 16% (no-tax) with an after-tax Kd mixes models.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-480","question":"Which statements about capital-structure theories are correct? I. The static trade-off theory balances the tax benefit of debt against expected costs of financial distress. II. The pecking-order theory predicts firms prefer internal funds, then debt, then new equity. III. Under the pecking-order theory, profitable firms tend to have higher leverage.","options":["I, II and III","II and III only","I and III only","I and II only"],"answer":3,"explanation":"Pecking order arises from information asymmetry: profitable firms fund themselves internally and so tend to have LOWER leverage, the opposite of the trade-off prediction. I and II are correct.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-481","question":"A firm pays interest of ₹20 lakh and preference dividends of ₹15 lakh a year; the tax rate is 25%. At what EBIT does its EPS become exactly zero (financial break-even point)?","options":["₹40 lakh","₹35 lakh","₹46.67 lakh","₹38.75 lakh"],"answer":0,"explanation":"Preference dividends come from after-tax profit, so EBIT must cover interest plus pref/(1 − t): 20 + 15/0.75 = ₹40 lakh. Adding them directly (₹35 lakh) ignores tax.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-482","question":"Weekly usage of a part is 400 units minimum, 500 normal and 600 maximum. Lead time is 4–6 weeks (5 normal) and the reorder quantity is 3,000 units. What are the reorder level, minimum stock level and maximum stock level?","options":["2,500, 1,100 and 5,000","3,600, 1,100 and 5,000","3,600, 2,000 and 6,600","3,600, 1,100 and 4,100"],"answer":1,"explanation":"Reorder level = max usage × max lead time = 600 × 6 = 3,600. Minimum = ROL − normal usage × normal lead time = 1,100. Maximum = ROL + reorder qty − min usage × min lead time = 5,000.","difficulty":"very-hard","source":"MBA finance · Bank MT"},
  {"id":"mgmt-finance-483","question":"Sales are ₹10 lakh in January, ₹12 lakh in February and ₹15 lakh in March. 20% is collected in the month of sale, 50% in the next month and 30% in the month after. What are March's cash collections?","options":["₹15.0 lakh","₹12.9 lakh","₹12.0 lakh","₹11.1 lakh"],"answer":2,"explanation":"March collects 20% of March (3.0) + 50% of February (6.0) + 30% of January (3.0) = ₹12.0 lakh. Reversing the 50%/30% lags gives ₹11.1 lakh.","difficulty":"moderate","source":"MBA finance · Bank MT"},
  {"id":"mgmt-finance-484","question":"A supplier offers 2/10 net 30. The buyer skips the discount and, without penalty, pays on day 60 instead of day 30. What is the effective annual cost of the forgone discount (compound basis, 365-day year)?","options":["44.59%","14.90%","37.24%","15.89%"],"answer":3,"explanation":"Forgoing 2% buys 50 extra days (day 10 to day 60): (1 + 2/98)^(365/50) − 1 = 15.89%. Paying on day 30 would cost 44.59%; stretching payables lowers the cost but can damage supplier relations.","difficulty":"very-hard","source":"MBA finance · Bank MT"},
  {"id":"mgmt-finance-485","question":"Annual credit sales are ₹73 lakh and the average collection period is 50 days. Variable costs are 60% of sales. What is the average investment in receivables measured at cost (365-day year)?","options":["₹6 lakh","₹10 lakh","₹4 lakh","₹12 lakh"],"answer":0,"explanation":"Average receivables = 73 × 50/365 = ₹10 lakh at selling price; the firm's money tied up is only the variable cost: 10 × 60% = ₹6 lakh.","difficulty":"hard","source":"MBA finance · Bank MT"},
  {"id":"mgmt-finance-486","question":"Under the Miller–Orr model, a firm's transaction cost per securities trade is ₹200, the variance of daily net cash flows is (₹10,000)², the daily interest rate is 0.03% and the minimum cash balance is ₹1,00,000. What are the return point and the upper limit (nearest ₹100)?","options":["Return point ₹1,55,300; upper limit ₹2,10,500","Return point ₹1,36,800; upper limit ₹2,10,500","Return point ₹36,800; upper limit ₹1,10,500","Return point ₹1,36,800; upper limit ₹4,31,600"],"answer":1,"explanation":"Spread = 3 × (¾ × 200 × 10⁸/0.0003)^(1/3) = ₹1,10,521. Return point = lower limit + spread/3 = ₹1,36,840; upper limit = lower limit + spread = ₹2,10,521.","difficulty":"very-hard","source":"MBA finance · Bank MT"},
  {"id":"mgmt-finance-487","question":"A share trades at ₹500 cum-bonus. The company issues bonus shares in the ratio 1:4 (one new share for every four held). What is the theoretical ex-bonus price, and what happens to a holder of 100 shares?","options":["₹375; she has 125 shares worth ₹46,875","₹400; she has 125 shares worth ₹62,500","₹400; she has 125 shares worth ₹50,000","₹500; she has 125 shares worth ₹62,500"],"answer":2,"explanation":"Five shares now represent what four did: 500 × 4/5 = ₹400. 125 × 400 = ₹50,000, so a bonus issue creates no value by itself.","difficulty":"moderate","source":"MBA finance · Bank MT"},
  {"id":"mgmt-finance-488","question":"A share is about to go ex-dividend with a ₹10 dividend. Its marginal investors pay 20% tax on dividends and 10% on capital gains. If tax-driven arbitrage sets the ex-dividend price drop, how much should the price fall?","options":["₹10.00","₹8.00","₹11.25","₹8.89"],"answer":3,"explanation":"Indifference: ΔP × (1 − t_g) = D × (1 − t_d), so ΔP = 10 × 0.80/0.90 = ₹8.89. The price falls by less than the dividend because dividends are taxed more heavily.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-489","question":"A firm with 1 crore shares at ₹200 has ₹20 crore of surplus cash. It can pay a ₹20 dividend or buy back 10 lakh shares at ₹200. Ignoring taxes and signalling, what is the share price after each, and how is a shareholder with 1,000 shares affected?","options":["₹180 after the dividend, ₹200 after the buyback; ₹2,00,000 either way","₹200 after both; the dividend makes her richer by ₹20,000","₹180 after both; the buyback makes her poorer by ₹20,000","₹180 after the dividend, ₹222 after the buyback; the buyback is better"],"answer":0,"explanation":"Dividend: price drops to ₹180, plus ₹20,000 cash = ₹2,00,000. Buyback: ₹180 crore of value over 90 lakh shares keeps the price at ₹200, so 1,000 × 200 = ₹2,00,000.","difficulty":"hard","source":"IB analyst test · Corporate finance"},
  {"id":"mgmt-finance-490","question":"Which statements are correct? I. The clientele effect suggests firms attract investors whose tax and income needs suit their payout policy. II. Signalling theory implies an unexpected dividend increase is usually read as good news. III. The 'bird-in-hand' argument is consistent with MM dividend irrelevance.","options":["I, II and III","I and II only","II and III only","I only"],"answer":1,"explanation":"Clienteles and signalling are standard explanations of why payout policy matters in practice. The bird-in-hand view (dividends lower perceived risk) contradicts MM irrelevance, so III is false.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-491","question":"A firm has assets of ₹100 crore and EBIT of either ₹8 crore or ₹20 crore with equal probability; the tax rate is 25%. Plan U is all equity; Plan L is 50% debt at 10%. What is the range of ROE under each plan?","options":["U: 6.0% to 15.0%; L: 6.0% to 15.0%","U: 8.0% to 20.0%; L: 6.0% to 30.0%","U: 6.0% to 15.0%; L: 4.5% to 22.5%","U: 6.0% to 15.0%; L: 1.5% to 25.5%"],"answer":2,"explanation":"U: 8 × 0.75/100 = 6% and 20 × 0.75/100 = 15%. L: interest ₹5 crore; (8 − 5) × 0.75/50 = 4.5% and (20 − 5) × 0.75/50 = 22.5%. Leverage raises expected ROE but widens its spread.","difficulty":"very-hard","source":"IB analyst test · Corporate finance"},
  {"id":"mgmt-finance-492","question":"Lenders require interest coverage (EBIT/interest) of at least 4×. A firm's EBIT is ₹80 crore and new debt would cost 10%. It already has ₹50 crore of debt at 8%. How much additional debt can it raise?","options":["₹200 crore","₹150 crore","₹120 crore","₹160 crore"],"answer":3,"explanation":"Maximum interest = 80/4 = ₹20 crore; existing interest = ₹4 crore, so new interest up to ₹16 crore, i.e. ₹160 crore at 10%. ₹200 crore ignores the existing debt.","difficulty":"hard","source":"MBA finance · Bank MT"},
  {"id":"mgmt-finance-493","question":"Raw material consumed ₹36.5 lakh (average RM stock ₹4 lakh); cost of production ₹54.75 lakh (average WIP ₹3 lakh); cost of goods sold ₹73 lakh (average finished goods ₹6 lakh); credit sales ₹91.25 lakh (average debtors ₹10 lakh); credit purchases ₹36.5 lakh (average creditors ₹3 lakh). Using a 365-day year, what are the operating cycle and the cash conversion cycle?","options":["130 days and 100 days","130 days and 90 days","100 days and 70 days","120 days and 90 days"],"answer":0,"explanation":"RM 40 + WIP 20 + FG 30 + debtors 40 = 130 days gross operating cycle; minus creditors 30 days gives a net (cash) cycle of 100 days.","difficulty":"very-hard","source":"MBA finance · Bank MT"},
  {"id":"mgmt-finance-494","question":"A firm's current assets never fall below ₹40 crore (permanent) and rise to ₹70 crore in peak season. Under a matching (hedging) approach to working-capital finance, how should it fund them?","options":["All ₹70 crore short-term, since they are all current assets","₹40 crore long-term; the seasonal ₹30 crore short-term","All ₹70 crore from long-term sources, to be safe","₹30 crore long-term and ₹40 crore short-term"],"answer":1,"explanation":"Matching funds permanent current assets (like fixed assets) with long-term money and the fluctuating part with short-term credit. Funding everything short-term is aggressive; everything long-term is conservative.","difficulty":"moderate","source":"MBA finance · Bank MT"},
  {"id":"mgmt-finance-495","question":"A venture fund invests ₹10 crore in a start-up expected to be worth ₹200 crore on exit in 5 years. The fund targets a 50% annual return. Using the venture capital method, what stake must it demand and what is the pre-money valuation?","options":["5.0%; ₹190.00 crore","38.0%; ₹26.34 crore","38.0%; ₹16.34 crore","19.0%; ₹16.34 crore"],"answer":2,"explanation":"Post-money = 200/1.5⁵ = ₹26.34 crore; stake = 10/26.34 = 38.0%; pre-money = post − investment = ₹16.34 crore.","difficulty":"very-hard","source":"IB analyst test · Corporate finance"},
  {"id":"mgmt-finance-496","question":"A company sells 1 crore new shares in its IPO at ₹300. The shares close the first day at ₹390. What was the first-day return and the 'money left on the table'?","options":["23%; ₹90 crore","30%; ₹390 crore","90%; ₹30 crore","30%; ₹90 crore"],"answer":3,"explanation":"First-day return = (390 − 300)/300 = 30%. Money left on the table = (390 − 300) × 1 crore = ₹90 crore, which the issuer could have raised. 23% divides by the closing price.","difficulty":"moderate","source":"IB analyst test · Corporate finance"},
  {"id":"mgmt-finance-497","question":"An unlevered firm is worth ₹500 crore. It issues ₹200 crore of permanent debt to buy back shares; the tax rate is 25%. The PV of expected financial distress costs at this leverage is ₹30 crore. Under the trade-off theory, what is the levered firm's value?","options":["₹520 crore","₹550 crore","₹470 crore","₹700 crore"],"answer":0,"explanation":"V_L = V_U + t × D − PV(distress) = 500 + 50 − 30 = ₹520 crore. Ignoring distress costs gives the MM-with-taxes value of ₹550 crore.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-498","question":"A company's asset (unlevered) beta is 0.9. It plans a capital structure with a debt–equity ratio of 0.8; the tax rate is 25%. With a risk-free rate of 7% and market risk premium of 6%, what is its cost of equity?","options":["16.72%","15.64%","12.40%","10.38%"],"answer":1,"explanation":"Relever: β_L = 0.9 × [1 + 0.75 × 0.8] = 1.44; Ke = 7 + 1.44 × 6 = 15.64%. Ignoring the tax term gives β = 1.62.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-499","question":"A company's current market-value mix is 20% debt, but management has committed to a target of 40% debt over the next two years. For evaluating a long-lived project, which weights belong in the WACC, and why?","options":["The 20% current weights, because they are observable","Book-value weights, because they are stable and audited","The 40% target weights, reflecting future financing","The weights of whichever source funds this particular project"],"answer":2,"explanation":"WACC should reflect the long-run financing mix; using the specific source for one project (e.g. all debt) is a classic error, since it ignores the equity capacity that debt uses up.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-500","question":"A firm sells at ₹100 with variable cost ₹60, fixed operating costs ₹4 lakh and interest ₹2 lakh. What is its degree of total leverage at 20,000 units, and what does it become at 30,000 units?","options":["4.00 at both volumes","2.00 at 20,000; 1.50 at 30,000","4.00 at 20,000; 6.00 at 30,000","4.00 at 20,000; 2.00 at 30,000"],"answer":3,"explanation":"At 20,000: contribution ₹8 lakh, EBIT ₹4 lakh, EBT ₹2 lakh, DTL = 8/2 = 4.00. At 30,000: contribution ₹12 lakh, EBT ₹6 lakh, DTL = 2.00. Leverage falls as volume moves away from break-even.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-501","question":"Which is an example of the agency cost of DEBT (a conflict between shareholders and lenders)?","options":["A distressed, levered firm gambling on negative-NPV risk","Managers building empires through unprofitable acquisitions","Managers consuming excessive perks at shareholders' expense","Shareholders failing to monitor the board and its decisions"],"answer":0,"explanation":"When default is likely, shareholders gain from risk-shifting (asset substitution) because they keep the upside while lenders bear the downside. Empire building and perks are agency costs of equity (managers vs owners).","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-502","question":"A share trades at ₹150; next year's dividend is ₹9 and growth is 6%. New shares would net 95% of the market price after issue costs. What are the costs of retained earnings and of new equity?","options":["12.00% for both","12.00% and 12.32%","12.32% and 12.00%","6.00% and 6.32%"],"answer":1,"explanation":"Retained earnings: 9/150 + 6% = 12.00%. New equity uses the net proceeds: 9/142.50 + 6% = 12.32%. Retained earnings carry an opportunity cost, not zero cost.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-503","question":"A firm plans annual sales of ₹120 lakh (all on 2 months' credit) with total costs at 80% of sales, materials being 50% of sales. It holds 1 month of raw materials (at material cost) and 1 month of finished goods (at total cost), and suppliers give 1.5 months' credit on materials. Ignoring cash and WIP, what is the net working capital requirement (debtors at cost)?","options":["₹25.5 lakh","₹29.0 lakh","₹21.5 lakh","₹17.0 lakh"],"answer":2,"explanation":"Monthly: sales 10, total cost 8, materials 5. Debtors at cost 2 × 8 = 16, RM 5, FG 8, less creditors 1.5 × 5 = 7.5: NWC = ₹21.5 lakh. Valuing debtors at sales gives 25.5; forgetting creditors gives 29.","difficulty":"very-hard","source":"MBA finance · Bank MT"},
  {"id":"mgmt-finance-504","question":"Annual demand is 12,000 units, ordering cost ₹300 per order and holding cost ₹6 per unit per year. If the firm orders 2,000 units at a time instead of the EOQ, by how much do its annual ordering-plus-holding costs rise?","options":["₹7,800","₹6,573","₹2,714","₹1,227"],"answer":3,"explanation":"EOQ = √(2 × 12,000 × 300/6) = 1095, total cost ₹6,573. At 2,000 units: 6 orders × 300 + 1,000 × 6 = ₹7,800. Extra cost = ₹1,227; the cost curve is flat near the EOQ.","difficulty":"hard","source":"MBA finance · Bank MT"},
  {"id":"mgmt-finance-505","question":"A firm's long-run target payout is 50% and it adjusts 30% of the gap each year. Last year's DPS was ₹6 and this year's EPS is ₹16. What dividend does Lintner's model predict?","options":["₹6.60","₹8.00","₹7.40","₹6.30"],"answer":0,"explanation":"DPS = previous DPS + adjustment × (target payout × EPS − previous DPS) = 6 + 0.3 × (8 − 6) = ₹6.60. Paying the full target ₹8 ignores dividend smoothing.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-506","question":"A firm's cost of debt is 7% after tax and its WACC is 11%. A project earning an IRR of 9% will be fully financed by a new loan. The manager argues it should be accepted because 9% > 7%. What is the correct view?","options":["Accept it, because the specific financing source sets the hurdle","Reject if its risk matches the firm's: the hurdle is the 11% WACC","Accept it, since its IRR exceeds the after-tax cost of debt of 7%","Reject it only if the loan's pre-tax cost exceeds 9%"],"answer":1,"explanation":"The hurdle rate depends on the project's risk, not on how it is financed; borrowing for this project reduces capacity for later ones, so using the debt rate alone is wrong.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-507","question":"A firm finances itself 40% with debt at 10% and 60% with equity at 15%. If the corporate tax rate is cut from 30% to 25% (costs of debt and equity unchanged), what happens to its WACC?","options":["Falls from 11.80% to 11.60%","Stays the same, because pre-tax costs are unchanged","Rises from 11.80% to 12.00%","Rises from 11.80% to 13.80%"],"answer":2,"explanation":"A lower tax rate shrinks the interest tax shield: after-tax Kd goes from 7.0% to 7.5%, so WACC rises by 0.4 × 0.5% = 0.2 pp, from 11.80% to 12.00%.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-508","question":"A company with 50 lakh shares, EPS ₹40 and a price of ₹1,200 does a 1-to-4 stock split (each share becomes four). Assuming no change in total value, what are the new EPS, share price and P/E?","options":["₹40, ₹300 and 7.5×","₹10, ₹1,200 and 120×","₹10, ₹300 and 7.5×","₹10, ₹300 and 30×"],"answer":3,"explanation":"Shares become 2 crore: EPS = 40/4 = ₹10, price = 1,200/4 = ₹300, P/E = 300/10 = 30× (unchanged). A split only changes the unit size.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-509","question":"A firm keeps 50% debt (after-tax 7%) and 50% equity. Equity costs 14% from retained earnings (₹40 crore available) and 16% from new shares. A ₹100 crore capital budget has projects with IRRs of 12% (₹50 crore) and 11.8% (₹50 crore). Which projects should it take?","options":["Both: WACC is 10.50%, then 11.50% above ₹80 crore","Only the 12% project, because WACC rises to 11.50%","Neither, because new equity costs 16%, above both IRRs","Both, because the WACC stays at 10.50% throughout"],"answer":0,"explanation":"Break point = ₹40 crore/0.5 = ₹80 crore. WACC is 0.5 × 7 + 0.5 × 14 = 10.50% below it and 0.5 × 7 + 0.5 × 16 = 11.50% above it; even the last ₹20 crore, costing 11.50%, earns 11.8%, so accept both. Comparing IRRs with the 16% cost of new equity alone is wrong.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-510","question":"A firm with an asset beta of 1.0 moves from a debt–equity ratio of 0.25 to 1.0 (tax rate 25%). The risk-free rate is 6% and the market risk premium 7%. By how much does its cost of equity rise?","options":["From 14.75% to 20.00%","From 14.31% to 18.25%","From 13.00% to 13.00%: beta is unaffected by leverage","From 13.00% to 18.25%"],"answer":1,"explanation":"β_L = 1.0 × [1 + 0.75 × D/E]: 1.1875 at 0.25 and 1.75 at 1.0. Ke = 6 + β × 7 goes from 14.31% to 18.25%. Ignoring the tax term overstates both betas.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-511","question":"Using the Baumol model, a firm needs ₹36 lakh of cash a year, each conversion costs ₹150 and short-term securities yield 9%. What is the minimum total annual cost (conversion + opportunity cost)?","options":["₹4,930","₹14,789","₹9,859","₹19,718"],"answer":2,"explanation":"Optimal C = √(2 × 36,00,000 × 150/0.09) = ₹1,09,545. At the optimum, conversion cost = opportunity cost = ₹4,930 each, so total = ₹9,859.","difficulty":"very-hard","source":"MBA finance · Bank MT"},
  {"id":"mgmt-finance-512","question":"Which statements about beta and leverage are correct? I. An all-equity firm's equity beta equals its asset beta. II. Adding debt raises equity beta even if operating risk is unchanged. III. A firm's asset beta is a weighted average of its equity beta and debt beta.","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":3,"explanation":"With no debt, equity bears all asset risk. Debt concentrates that risk on equity. In general β_asset = (E/V)β_equity + (D/V)β_debt, which collapses to the unlevering formula when debt beta is zero.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-513","question":"An acquirer pays ₹450 crore in cash for a target worth ₹400 crore on a standalone basis. Merger synergies have a PV of ₹100 crore. What are the gains to the target's shareholders and the NPV to the acquirer?","options":["Target gains ₹50 crore; acquirer NPV ₹50 crore","Target gains ₹50 crore; acquirer NPV ₹100 crore","Target gains ₹0; acquirer NPV ₹50 crore","Target gains ₹100 crore; acquirer NPV −₹50 crore"],"answer":0,"explanation":"Target premium = 450 − 400 = ₹50 crore. Acquirer NPV = synergies − premium = 100 − 50 = ₹50 crore. The synergies are split between the two sets of shareholders by the price.","difficulty":"hard","source":"IB analyst test · M&A"},
  {"id":"mgmt-finance-514","question":"Acquirer A (100 crore shares, value ₹1,000 crore) buys target T (standalone value ₹400 crore) by issuing 40 crore new A shares. Synergies are worth ₹100 crore. What is the NPV of the deal to A's original shareholders?","options":["₹100.0 crore","₹71.4 crore","₹0.0 crore","₹28.6 crore"],"answer":1,"explanation":"Combined value ₹1,500 crore over 140 crore shares = ₹10.7143 a share. A's holders own 100/140 = ₹1071.4 crore, a gain of ₹71.4 crore; T's holders get ₹428.6 crore (a ₹28.6 crore premium). In a stock deal targets share in the synergies.","difficulty":"very-hard","source":"IB analyst test · M&A"},
  {"id":"mgmt-finance-515","question":"A private equity fund invests ₹300 crore of equity in a buyout and receives ₹900 crore at exit after 5 years (no interim cash flows). What are the multiple of invested capital (MOIC) and the IRR?","options":["3.0× and 40.00%","2.0× and 24.57%","3.0× and 24.57%","3.0× and 14.87%"],"answer":2,"explanation":"MOIC = 900/300 = 3.0×; IRR = 3^(1/5) − 1 = 24.57%. Dividing the 200% gain by 5 years (40%) ignores compounding.","difficulty":"hard","source":"IB analyst test · M&A"},
  {"id":"mgmt-finance-516","question":"A buyout fund acquires a company with EBITDA of ₹125 crore at 8× (₹1,000 crore), funded 60% with debt. Over 5 years EBITDA grows to ₹160 crore and debt is paid down to ₹350 crore; it exits at the same 8× multiple. What is the equity IRR (no interim dividends)?","options":["5.06%","11.20%","9.16%","18.38%"],"answer":3,"explanation":"Entry equity = 40% × 1,000 = ₹400 crore. Exit EV = 8 × 160 = ₹1,280 crore; exit equity = 1,280 − 350 = ₹930 crore. IRR = (930/400)^(1/5) − 1 = 18.38%. Debt paydown and EBITDA growth both drive the return.","difficulty":"very-hard","source":"IB analyst test · M&A"},
  {"id":"mgmt-finance-517","question":"An acquirer earns ₹100 crore on 20 crore shares. It buys a target earning ₹30 crore a year for ₹400 crore, financed entirely with new debt at 8% pre-tax (tax rate 25%). Ignoring synergies, what is the effect on its EPS?","options":["Accretive: EPS rises from ₹5.00 to ₹5.30","Dilutive: EPS falls from ₹5.00 to ₹4.90","Accretive: EPS rises from ₹5.00 to ₹6.50","Neutral, because the price paid equals the target's value"],"answer":0,"explanation":"After-tax interest = 400 × 8% × 0.75 = ₹24 crore; new EPS = (100 + 30 − 24)/20 = ₹5.30. It is accretive because the target's earnings yield (30/400 = 7.5%) exceeds the after-tax cost of debt (6%). Accretion does not by itself mean value creation.","difficulty":"very-hard","source":"IB analyst test · M&A"},
  {"id":"mgmt-finance-518","question":"A bank holds high-quality liquid assets of ₹1,200 crore. Under a 30-day stress scenario, expected cash outflows are ₹2,000 crore and expected inflows ₹1,000 crore. What is its liquidity coverage ratio, and does it meet the 100% minimum?","options":["60%; no","120%; yes","40%; no","120%; no, because inflows cannot be counted"],"answer":1,"explanation":"LCR = HQLA/net cash outflows over 30 days = 1,200/(2,000 − 1,000) = 120%. Dividing by gross outflows (60%) ignores the inflows that Basel III allows (subject to a cap of 75% of outflows, not binding here).","difficulty":"hard","source":"Bank MT · Banking & finance"},
  {"id":"mgmt-finance-519","question":"Under the RBI's income recognition norms, a term loan becomes a non-performing asset when interest or instalment remains overdue for more than how long, and how is an NPA classified after 12 months in the sub-standard category?","options":["60 days; it becomes a loss asset","90 days; it becomes a loss asset","90 days; it becomes a doubtful asset","180 days; it becomes a doubtful asset"],"answer":2,"explanation":"A loan is an NPA once dues are overdue beyond 90 days. It stays sub-standard for up to 12 months, then becomes doubtful; a loss asset is one identified as uncollectible.","difficulty":"hard","source":"Bank MT · Banking & finance"},
  {"id":"mgmt-finance-520","question":"A bank has assets of ₹1,000 crore with a duration of 5 years and liabilities of ₹900 crore with a duration of 2 years. If all rates rise by 1% (ignore the 1 + r adjustment), roughly how much does its equity value change?","options":["Falls by about ₹30 crore","Rises by about ₹32 crore","Falls by about ₹3.2 crore","Falls by about ₹32 crore"],"answer":3,"explanation":"Duration gap = D_A − (L/A) × D_L = 5 − 0.9 × 2 = 3.2; ΔE ≈ −3.2 × 1,000 × 1% = −₹32 crore, a large hit on ₹100 crore of equity. Ignoring the L/A weight gives −₹30 crore.","difficulty":"very-hard","source":"Bank MT · Banking & finance"},
  {"id":"mgmt-finance-521","question":"Mutually exclusive projects: A lasts 2 years with NPV ₹10 lakh; B lasts 4 years with NPV ₹15 lakh. Both can be repeated identically and the cost of capital is 10%. Using the replacement-chain (common life) method, which is better?","options":["A, with a 4-year chain NPV of ₹18.26 lakh","B, because its NPV of ₹15 lakh is higher","A, with a 4-year chain NPV of ₹20.00 lakh","They are equivalent over 4 years"],"answer":0,"explanation":"Repeat A at year 2: 10 + 10/1.1² = ₹18.26 lakh > ₹15 lakh, so A wins. Adding the two NPVs without discounting the second gives ₹20 lakh.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-522","question":"For a project with a long life and even annual cash flows, the reciprocal of the payback period:","options":["Equals the NPV per rupee invested in the project","Approximates the IRR, more closely as the life lengthens","Equals the accounting rate of return on the initial investment","Approximates the cost of capital used for discounting"],"answer":1,"explanation":"For an even perpetuity, IRR = annual cash flow/cost = 1/payback exactly; for a long but finite life, 1/payback slightly overstates the IRR, with the gap shrinking as the life grows.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-523","question":"A ₹30 lakh home loan at 8% for 20 years (monthly EMIs) is reset to 9% on day one, and the bank keeps the EMI unchanged by extending the tenure. Roughly how long does the loan now run?","options":["About 22.5 years","About 21.0 years","About 25.3 years","About 22.8 years"],"answer":2,"explanation":"EMI = ₹25,093. Solve 30,00,000 = EMI × [1 − (1.0075)⁻ⁿ]/0.0075: n ≈ 304 months ≈ 25.3 years. A 1-point rise adds far more than proportional time because so much of the EMI is interest.","difficulty":"very-hard","source":"MBA finance · Personal finance"},
  {"id":"mgmt-finance-524","question":"An office building generates net operating income of ₹60 lakh a year. Comparable buildings sell at a capitalisation rate of 7.5%. If NOI is expected to grow 2% a year and investors require 9.5%, are the two valuations consistent?","options":["No: ₹8 crore vs ₹6.32 crore (60/0.095)","No: ₹8 crore vs ₹8.16 crore (using next year's NOI)","Yes: both give ₹6.32 crore (60/0.095)","Yes: both give ₹8 crore (cap rate = r − g)"],"answer":3,"explanation":"Direct capitalisation: 60/0.075 = ₹8 crore. Growing perpetuity: 60/(0.095 − 0.02) = ₹8 crore. A cap rate is simply r − g applied to current NOI (strictly, next year's NOI).","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-525","question":"A firm worth ₹2,000 crore has 100 crore shares. 20 crore warrants allow holders to buy one new share each at ₹15. If all warrants are exercised, what is the share price after exercise, and the gain per warrant?","options":["₹19.17; ₹4.17","₹20.00; ₹5.00","₹16.67; ₹1.67","₹19.17; ₹5.00"],"answer":0,"explanation":"The ₹300 crore of exercise cash joins the firm: (2,000 + 300)/120 = ₹19.17. Each warrant gains ₹19.17 − 15 = ₹4.17, less than the naive ₹5 because exercise dilutes existing holders.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-526","question":"A dealer sells a government bond for ₹99.50 and agrees to buy it back after 7 days for ₹99.62. What is the implied repo rate (365-day year), and which side is borrowing?","options":["6.29%; the dealer is lending cash","6.29%; the dealer is borrowing cash","0.12%; the dealer is borrowing cash","6.20%; the dealer is lending cash"],"answer":1,"explanation":"Repo interest = 0.12 on 99.50 for 7 days: (0.12/99.50) × 365/7 = 6.29%. A repo is economically a collateralised loan from the cash lender to the dealer.","difficulty":"hard","source":"Bank MT · Banking & finance"},
  {"id":"mgmt-finance-527","question":"A ₹100 crore loan pool backs three tranches: senior ₹85 crore, mezzanine ₹10 crore and equity (first-loss) ₹5 crore. If the pool suffers ₹12 crore of losses, how are they allocated?","options":["All tranches lose 12% of their value pro rata","Senior loses ₹12 crore first because it is largest","Equity loses ₹5 crore, mezzanine ₹7 crore, senior nothing","Equity loses ₹5 crore, mezzanine ₹7 crore and senior ₹0.85 crore"],"answer":2,"explanation":"Losses run bottom-up: the first ₹5 crore wipes out equity, the next ₹7 crore hits mezzanine (70% of its ₹10 crore); senior is protected by the ₹15 crore of subordination.","difficulty":"hard","source":"Bank MT · Banking & finance"},
  {"id":"mgmt-finance-528","question":"A retiree wants ₹8 lakh at the START of the first year of retirement, increasing by 6% each year for 25 years in total. Her corpus earns 9%. What corpus does she need on the day she retires?","options":["₹1,33,94,161","₹85,65,289","₹1,41,97,811","₹1,45,99,636"],"answer":3,"explanation":"PV of a growing annuity due = 8,00,000 × [1 − (1.06/1.09)²⁵]/(0.09 − 0.06) × 1.09 = ₹1,45,99,636. Leaving out the ×1.09 treats withdrawals as year-end; ignoring growth badly understates the need.","difficulty":"very-hard","source":"MBA finance · Personal finance"},
  {"id":"mgmt-finance-529","question":"An investor puts ₹10,000 into a fund at the START of every month for 15 years. The fund earns 12% a year compounded monthly. What is the corpus at the end of 15 years (nearest rupee)?","options":["₹50,45,760","₹49,95,802","₹44,73,566","₹42,11,218"],"answer":0,"explanation":"Monthly rate 1%, 180 payments, annuity due: FV = 10,000 × [(1.01¹⁸⁰ − 1)/0.01] × 1.01 = ₹50,45,760. Yearly lumps of ₹1.2 lakh at 12% give ₹44,73,566, missing intra-year compounding.","difficulty":"hard","source":"MBA finance · Personal finance"},
  {"id":"mgmt-finance-530","question":"Nominal one-year interest rates are 8% in India and 4% in the US, and real rates are equal across countries. By the international Fisher effect, what is the expected change in the rupee over the year?","options":["Appreciate by about 3.85% against the dollar","Depreciate by about 3.85% against the dollar","Depreciate by exactly 4.00% (8% − 4%)","No change, since real rates are equal"],"answer":1,"explanation":"Expected ₹/$ change = (1 + i_INR)/(1 + i_USD) − 1 = 1.08/1.04 − 1 = 3.85%. The higher nominal rate reflects higher expected inflation, which erodes the rupee.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-531","question":"Which statement linking EVA and NPV is correct?","options":["A project with positive EVA in year 1 must have positive NPV","EVA uses cash flows while NPV uses accounting profits","The PV of future EVAs at WACC equals the project's NPV","EVA ignores the cost of equity capital entirely"],"answer":2,"explanation":"EVA = NOPAT − WACC × capital. Discounting all future EVAs at WACC reproduces the NPV. A single year's EVA can mislead, since early years may show negative EVA even for good projects.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-532","question":"In a DCF, the terminal value at year 5 is set at ₹2,000 crore using an exit multiple of 10× EBITDA. The year-6 free cash flow is expected to be ₹120 crore and WACC is 11%. What perpetual growth rate does this terminal value imply?","options":["6.00%","4.70%","1.00%","5.00%"],"answer":3,"explanation":"Gordon: 2,000 = 120/(0.11 − g), so g = 11% − 6% = 5.00%. Cross-checking an exit multiple against implied growth flags terminal values that assume unrealistic growth.","difficulty":"very-hard","source":"IB analyst test · M&A"},
  {"id":"mgmt-finance-533","question":"A business generates ₹100 crore of free cash flow evenly through each of the next 3 years. At a 10% discount rate, what is the PV using the mid-year convention, compared with the year-end convention?","options":["₹260.82 crore vs ₹248.69 crore","₹248.69 crore vs ₹260.82 crore","₹273.55 crore vs ₹248.69 crore","₹248.69 crore under both"],"answer":0,"explanation":"Mid-year discounts each year's flow by t − 0.5 years: Σ 100/1.1^(t − 0.5) = ₹260.82 crore, which is year-end PV × 1.1^0.5. Multiplying by a full 1.1 overstates value.","difficulty":"very-hard","source":"IB analyst test · M&A"},
  {"id":"mgmt-finance-534","question":"A company with a market cap of ₹40,000 crore pays dividends of ₹800 crore and spends ₹1,200 crore on share buybacks in a year. What are its dividend yield and total shareholder payout yield?","options":["2.0% and 3.0%","2.0% and 5.0%","5.0% and 2.0%","3.0% and 5.0%"],"answer":1,"explanation":"Dividend yield = 800/40,000 = 2%. Total payout yield adds buybacks: (800 + 1,200)/40,000 = 5%. Ignoring buybacks understates cash returned to shareholders.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-535","question":"An education loan of ₹5 lakh at 12% a year (1% a month) has a 12-month moratorium during which interest accrues and is added to the balance. It is then repaid by 60 monthly EMIs. What is the EMI?","options":["₹11,122","₹12,457","₹12,533","₹9,775"],"answer":2,"explanation":"Balance after the moratorium = 5,00,000 × 1.01¹² = ₹5,63,413; EMI = balance × 0.01/(1 − 1.01⁻⁶⁰) = ₹12,533. Adding simple interest (₹60,000) misses monthly compounding.","difficulty":"very-hard","source":"MBA finance · Personal finance"},
  {"id":"mgmt-finance-536","question":"A credit-card balance of ₹50,000 accrues interest at 3.5% a month. If the holder pays ₹2,000 a month and makes no new purchases, roughly how long will it take to clear the balance?","options":["25 months","About 200 months","It will never be cleared","About 60 months"],"answer":3,"explanation":"Solve 50,000 = 2,000 × [1 − 1.035⁻ⁿ]/0.035: 1.035⁻ⁿ = 1 − 0.875 = 0.125, so n = ln 8/ln 1.035 ≈ 60 months. Only ₹250 of the first payment reduces principal; ₹2,000 must exceed the ₹1,750 monthly interest or the debt never ends.","difficulty":"very-hard","source":"MBA finance · Personal finance"},
  {"id":"mgmt-finance-537","question":"A loan earns net interest and fee income of ₹12 crore a year, with operating costs of ₹4 crore and an expected loss of ₹2 crore. It requires economic capital of ₹50 crore. What is its RAROC, and is it acceptable if the bank's hurdle rate is 15%?","options":["12%; no","16%; yes","24%; yes","12%; yes, because it is profitable"],"answer":0,"explanation":"RAROC = (income − costs − expected loss)/economic capital = (12 − 4 − 2)/50 = 12%, below the 15% hurdle. Ignoring expected loss gives 16%.","difficulty":"hard","source":"Bank MT · Banking & finance"},
  {"id":"mgmt-finance-538","question":"A bank prices a corporate loan. Its cost of funds is 6%, operating cost 1% of the loan, expected loss 0.8% a year, and it must hold equity of 10% of the loan, costing 15% (that equity replaces funding that would cost 6%). Ignoring taxes, what is the minimum lending rate?","options":["9.30%","8.70%","7.80%","15.00%"],"answer":1,"explanation":"Capital charge = 10% × (15% − 6%) = 0.9%. Rate = 6 + 1 + 0.8 + 0.9 = 8.70%. Charging the full 15% on the equity slice double-counts the funding cost it replaces.","difficulty":"very-hard","source":"Bank MT · Banking & finance"},
  {"id":"mgmt-finance-539","question":"Suppose a bank has net demand and time liabilities of ₹10,000 crore, a cash reserve ratio of 4% and a statutory liquidity ratio of 18%. Ignoring other uses, how much is available for lending?","options":["₹9,600 crore","₹8,200 crore","₹7,800 crore","₹7,600 crore"],"answer":2,"explanation":"CRR (cash with the RBI) ₹400 crore and SLR (liquid assets such as government securities) ₹1,800 crore are both deducted: 10,000 − 2,200 = ₹7,800 crore.","difficulty":"hard","source":"Bank MT · Banking & finance"},
  {"id":"mgmt-finance-540","question":"Firm A can borrow fixed at 8.0% or floating at MIBOR + 0.5%; firm B can borrow fixed at 10.0% or floating at MIBOR + 1.5%. A wants floating and B wants fixed. What is the total saving available from an interest rate swap, and who should borrow which way?","options":["2.0%: A borrows floating, B fixed, and then they swap","1.0%: A borrows floating, B fixed, and then they swap","No saving, because A is cheaper in both markets","1.0%: A borrows fixed, B floating, and then they swap"],"answer":3,"explanation":"A's advantage is 2.0% in fixed and 1.0% in floating, so A has a comparative advantage in fixed. Total gain = 2.0 − 1.0 = 1.0%, to be shared via the swap (before any dealer fee).","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-541","question":"An insurer offers an annual premium of ₹12,000 paid at the start of the year, or 12 monthly premiums of ₹1,050 each paid at the start of every month. What effective annual interest rate is implied by choosing the monthly option?","options":["11.35%","5.00%","10.80%","10.00%"],"answer":0,"explanation":"Solve 12,000 = 1,050 × annuity-due factor (12 months): monthly rate ≈ 0.900%, so effective annual ≈ 11.35%. The flat '₹600 extra on ₹12,000 = 5%' badly understates the cost because the balance declines.","difficulty":"very-hard","source":"MBA finance · Personal finance"},
  {"id":"mgmt-finance-542","question":"Over 3 years a company's EPS grows 10% a year, its P/E rises from 15 to 18, and it pays a dividend yield of about 2% a year. What is the approximate annual total return to shareholders?","options":["About 12.0%","About 18.9%","About 16.9%","About 32.0%"],"answer":1,"explanation":"Price ratio = 1.1³ × (18/15) = 1.5972, an annual capital gain of 16.9%; adding ~2% dividend yield gives about 18.9%. Ignoring the multiple expansion gives 12%.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-543","question":"A conglomerate's two businesses have enterprise values of ₹500 crore and ₹300 crore. It also owns a listed stake worth ₹200 crore, to which analysts apply a 20% holding-company discount. Net debt is ₹150 crore and there are 10 crore shares. What is the sum-of-the-parts value per share?","options":["₹85","₹96","₹81","₹65"],"answer":2,"explanation":"SOTP equity = 500 + 300 + 200 × 0.8 − 150 = ₹810 crore = ₹81 a share. Without the holdco discount it would be ₹85; forgetting net debt gives ₹96.","difficulty":"hard","source":"IB analyst test · M&A"},
  {"id":"mgmt-finance-544","question":"A 3-year project's sales are ₹100, ₹120 and ₹130 crore in years 1–3. Working capital must be in place at the START of each year at 10% of that year's sales, and is fully recovered at the end of year 3. What are the working-capital cash flows at t = 0, 1, 2 and 3?","options":["−10, −12, −13, +35 (₹ crore)","0, −10, −2, −1 (₹ crore)","−10, −2, −1, 0 (₹ crore)","−10, −2, −1, +13 (₹ crore)"],"answer":3,"explanation":"Investment is the CHANGE in required working capital: 10 at t = 0, then 12 − 10 = 2 and 13 − 12 = 1; the full ₹13 crore is released at t = 3. Treating each year's level as a new outflow triple-counts.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-545","question":"A company's cash flow from operations is ₹200 crore, after deducting interest paid of ₹30 crore (tax rate 25%). Capital expenditure is ₹120 crore. What is its free cash flow to the firm (FCFF)?","options":["₹102.5 crore","₹80.0 crore","₹110.0 crore","₹132.5 crore"],"answer":0,"explanation":"FCFF = CFO + interest × (1 − t) − capex = 200 + 22.5 − 120 = ₹102.5 crore. Adding back the full ₹30 crore (₹110 crore) ignores the tax saving that belongs to the firm only once.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-546","question":"An investor's position has limited downside below ₹480 and unlimited upside, and at prices above the strike it behaves like owning the share less a fixed cost. Which position matches?","options":["Long share plus a short ₹480 call (covered call)","Long share plus a long ₹480 put (protective put)","Short ₹480 put","Long share plus a short ₹480 put"],"answer":1,"explanation":"A protective put floors the value at the strike while keeping the upside, at the cost of the premium. A covered call caps upside; writing a put has limited upside and large downside.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-547","question":"A non-dividend share is at ₹100. One-year European options with strike ₹100 trade at ₹12 (call) and ₹5 (put). What risk-free rate does put-call parity imply?","options":["7.00%","6.54%","7.53%","13.64%"],"answer":2,"explanation":"C − P = S − K/(1 + r): 7 = 100 − 100/(1 + r), so 100/(1 + r) = 93 and r = 7.53%. Treating 7% of the strike as the rate ignores discounting.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-548","question":"A firm can launch a product now for an NPV of ₹10 crore, or wait a year and learn demand. If demand is high (probability 0.5) launching then has an NPV of ₹40 crore (measured at year 1); if low, the NPV would be −₹20 crore and it would not launch. The discount rate is 10%. What should it do?","options":["Launch now, because the ₹10 crore NPV today is certain","Wait: its expected NPV is ₹10.00 crore, the same as now","Launch now: waiting is worth only ₹9.09 crore","Wait: waiting is worth ₹18.18 crore today"],"answer":3,"explanation":"With the option to delay, the bad outcome is avoided: 0.5 × 40/1.1 = ₹18.18 crore > ₹10 crore. Averaging in the −20 forgets that the firm would simply not launch.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-549","question":"A professional saves 10% of a ₹10 lakh salary at the end of the first year, and her salary (and savings) grow 8% a year. Savings earn 10%. What will she have after 25 years of saving?","options":["₹1,99,31,154","₹98,34,706","₹32,03,030","₹2,19,24,269"],"answer":0,"explanation":"FV of a growing annuity = C[(1 + r)ⁿ − (1 + g)ⁿ]/(r − g) = 1,00,000 × (1.1²⁵ − 1.08²⁵)/0.02 = ₹1,99,31,154. Ignoring salary growth gives only ₹98,34,706.","difficulty":"very-hard","source":"MBA finance · Personal finance"},
  {"id":"mgmt-finance-550","question":"An investor in the 30% tax bracket is choosing between a tax-free bond yielding 6% and a taxable bond of similar risk. What taxable yield would make the two equivalent?","options":["7.80%","8.57%","6.90%","4.62%"],"answer":1,"explanation":"Taxable equivalent = tax-free yield/(1 − t) = 6%/0.70 = 8.57%. Multiplying by 1.3 (7.80%) understates it.","difficulty":"moderate","source":"MBA finance · Personal finance"},
  {"id":"mgmt-finance-551","question":"A bank funds ₹50,000 crore of earning assets entirely with deposits: 40% CASA at an average cost of 3% and 60% term deposits at 7%. If its CASA share falls to 30% while asset yields stay at 9%, by how much does its net interest margin change?","options":["Falls by 10 percentage points","Rises by 0.40 percentage points","Falls by 0.40 percentage points","Falls by 4.00 percentage points"],"answer":2,"explanation":"Cost of funds rises from 5.40% to 5.80% (10% of funding shifts from 3% to 7%, +0.40 pp). NIM = 9% − cost of funds falls from 3.60% to 3.20%.","difficulty":"hard","source":"Bank MT · Banking & finance"},
  {"id":"mgmt-finance-552","question":"In an all-stock acquisition with no synergies, when will the deal be accretive to the acquirer's EPS?","options":["When the target's EPS is higher than the acquirer's EPS","When the target is larger than the acquirer","Always, because the combined earnings are larger","When its own P/E exceeds the P/E it pays for the target"],"answer":3,"explanation":"In a stock deal, the acquirer's 'cost' is its earnings yield (1/P/E). Buying earnings at a lower P/E than one's own is EPS-accretive; at a higher P/E it is dilutive, whatever the absolute EPS levels.","difficulty":"hard","source":"IB analyst test · M&A"},
  {"id":"mgmt-finance-553","question":"A 90-day money-market instrument gives a holding-period yield of 2.0%. What are its effective annual yield (365-day) and money-market yield (360-day, simple)?","options":["8.36% and 8.00%","8.11% and 8.00%","8.36% and 8.11%","8.00% and 8.36%"],"answer":0,"explanation":"EAY compounds: 1.02^(365/90) − 1 = 8.36%. MMY is simple on a 360-day year: 2% × 360/90 = 8.00%. 8.11% is the 365-day simple yield.","difficulty":"hard","source":"Bank MT · Treasury"},
  {"id":"mgmt-finance-554","question":"A 120-day Treasury bill with face value ₹100 is bought at ₹98. What are its bank discount yield and its money-market yield (both on a 360-day basis)?","options":["6.12% and 6.00%","6.00% and 6.12%","6.00% and 6.21%","2.04% and 6.00%"],"answer":1,"explanation":"Bank discount yield uses face value: (2/100) × 360/120 = 6.00%. Money-market yield uses the price paid: (2/98) × 360/120 = 6.12%. BDY understates the true return.","difficulty":"very-hard","source":"Bank MT · Treasury"},
  {"id":"mgmt-finance-555","question":"A firm's cost of goods sold is ₹365 crore a year. It cuts days of inventory from 60 to 50 while COGS stays the same. Roughly how much cash is released?","options":["₹60 crore","₹16.7 crore","₹10 crore","₹1 crore"],"answer":2,"explanation":"Inventory = COGS/365 × days: 1 × 60 = ₹60 crore falls to 1 × 50 = ₹50 crore, freeing ₹10 crore of cash once.","difficulty":"hard","source":"IB analyst test · Corporate finance"},
  {"id":"mgmt-finance-556","question":"A trader writes a put with strike ₹300 for a premium of ₹12. What is the trader's maximum possible loss, and at what share price at expiry does it occur?","options":["Unlimited, as the share can fall without limit","₹300, if the share falls to zero","₹12, if the share rises","₹288, if the share falls to zero"],"answer":3,"explanation":"The writer must buy at ₹300 a share that could be worth ₹0, losing 300 − 12 = ₹288. Unlimited loss applies to writing naked calls, not puts.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-557","question":"A 10-year, 9% annual-coupon bond (face ₹1,000) trades at ₹1,080. It is callable at ₹1,040 after 3 years or at ₹1,020 after 5 years. What is its yield to worst?","options":["7.18%","7.82%","7.37%","8.33%"],"answer":0,"explanation":"Yield to maturity = 7.82%; yield to first call (3 years, ₹1,040) = 7.18%; yield to second call (5 years, ₹1,020) = 7.37%. The lowest, 7.18%, is the yield to worst.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-558","question":"A company has cash of ₹20 crore, marketable securities of ₹10 crore and receivables of ₹30 crore. Its annual cash operating expenses are ₹219 crore. What is its defensive interval?","options":["50 days","100 days","137 days","83 days"],"answer":1,"explanation":"Defensive interval = (cash + marketable securities + receivables)/daily cash expenses = 60/(219/365) = 100 days. Counting only cash and securities gives 50 days.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-559","question":"COGS is ₹730 crore. Inventory rose from ₹100 crore to ₹130 crore during the year. Average trade payables are ₹76 crore. What is the payables period based on purchases (365-day year)?","options":["38.0 days","40.5 days","36.5 days","34.0 days"],"answer":2,"explanation":"Purchases = COGS + closing inventory − opening inventory = 730 + 30 = ₹760 crore; DPO = 76/(760/365) = 36.5 days. Using COGS (38 days) ignores the inventory build-up.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-560","question":"A bond trades at ₹1,050 (full price) and will pay a ₹40 coupon in 3 months. The risk-free rate is 8% a year (annual compounding). What is the no-arbitrage price of a 6-month forward contract on the bond (delivery just after nothing else is paid)?","options":["₹1,091.19","₹1,051.19","₹1,049.62","₹1,050.41"],"answer":3,"explanation":"Subtract the PV of the coupon received before delivery, then carry forward: (1,050 − 40/1.08^0.25) × 1.08^0.5 = ₹1,050.41. Subtracting the undiscounted ₹40 is slightly off.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-561","question":"Match the bias with the behaviour. (p) Mental accounting, (q) Availability, (r) Anchoring. Behaviours: (1) Estimating a share's value by adjusting too little from last year's price; (2) Treating a tax refund as 'fun money' to spend while carrying credit-card debt; (3) Overestimating the chance of a market crash after heavy news coverage of one.","options":["p-2, q-3, r-1","p-1, q-3, r-2","p-2, q-1, r-3","p-3, q-2, r-1"],"answer":0,"explanation":"Mental accounting treats money differently by its source; availability judges probability by how easily examples come to mind; anchoring under-adjusts from an initial reference point.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-562","question":"A perpetuity pays ₹10,000 every TWO years, the first payment two years from now. At an annual discount rate of 10%, what is it worth?","options":["₹50,000.00","₹47,619.05","₹57,619.05","₹90,909.09"],"answer":1,"explanation":"The two-year rate is 1.1² − 1 = 21%, so PV = 10,000/0.21 = ₹47,619.05. Spreading it as ₹5,000 a year (₹50,000) ignores compounding within each two-year gap; multiplying by 1.21 treats the first payment as immediate.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-563","question":"A project's revenues and costs are forecast in today's (real) rupees, but its tax depreciation is fixed in nominal rupees. Which discounting approach is correct?","options":["Discount everything at the real rate, as forecasts are real","Discount everything at the nominal rate, the market's rate","Real operating flows at the real rate; tax shields at the nominal rate","Ignore inflation entirely, since it lifts revenues and costs equally anyway"],"answer":2,"explanation":"Consistency requires matching each cash flow with its rate. Depreciation tax shields do not rise with inflation, so they are nominal flows; discounting them at the real rate overvalues them.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-564","question":"A bank opening a branch in a new town expects the branch's own NPV to be −₹1 crore. However, the branch will raise deposits at the bank's existing ATM network nearby, adding ₹1.5 crore of NPV there. What should it do?","options":["Reject it, because the branch's own NPV is negative","Open it only if the ATM gain exceeds ₹1.5 crore","Reject it, because spillovers to other units are ignored","Open it: the incremental NPV to the bank is +₹0.5 crore"],"answer":3,"explanation":"Capital budgeting counts all incremental cash flows to the firm, including positive spillovers on other units: −1 + 1.5 = +₹0.5 crore.","difficulty":"moderate","source":"IB analyst test · Corporate finance"},
  {"id":"mgmt-finance-565","question":"A company pays fixed 7% and receives 6-month MIBOR on a ₹50 crore swap with semi-annual settlement. For a period where MIBOR was set at 8% (use half a year exactly), what is the net payment?","options":["The company receives ₹25 lakh","The company pays ₹25 lakh","The company receives ₹50 lakh","The company receives ₹4 crore and pays ₹3.5 crore"],"answer":0,"explanation":"Only the net difference is exchanged: (8% − 7%) × 50 crore × 0.5 = ₹25 lakh, paid to the fixed payer because floating exceeded fixed. Notional is never exchanged in an interest-rate swap.","difficulty":"hard","source":"Bank MT · Treasury"},
  {"id":"mgmt-finance-566","question":"A barbell portfolio (2-year and 18-year bonds) and a bullet portfolio (10-year bonds) have the same duration. Which statement is correct?","options":["Both have identical convexity because their durations match","The barbell has more convexity, gaining more from big parallel moves","The bullet has higher convexity, so it gains more from any large moves","The barbell has lower interest-rate risk for any kind of shift"],"answer":1,"explanation":"Spreading cash flows widely around the same duration raises convexity. The barbell benefits from large parallel shifts but is exposed to non-parallel (twist) moves; it typically offers a lower yield for that convexity.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-567","question":"When short-term government yields are higher than long-term yields (an inverted curve), what is the most common interpretation under the expectations theory?","options":["Markets expect inflation to accelerate in the long run","Long-term bonds are riskier than short-term ones","Markets expect short rates to fall, often due to a slowdown","The central bank is cutting its policy rates aggressively right now"],"answer":2,"explanation":"Under expectations theory, long yields average expected future short rates; long yields below short yields mean rates are expected to fall, which historically often precedes slowdowns.","difficulty":"moderate","source":"Bank MT · Treasury"},
  {"id":"mgmt-finance-568","question":"A ₹10 lakh loan at 10% a year is repaid in equal PRINCIPAL instalments of ₹2 lakh at the end of each of 5 years, with interest on the outstanding balance. What is the total payment in year 2, and total interest over the loan?","options":["₹2,63,797 in year 2; ₹3,18,987 total interest","₹3,00,000 in year 2; ₹3,00,000 total interest","₹2,80,000 in year 2; ₹5,00,000 total interest","₹2,80,000 in year 2; ₹3,00,000 total interest"],"answer":3,"explanation":"Year 2 starts with ₹8 lakh outstanding: interest ₹80,000 + principal ₹2 lakh = ₹2.8 lakh. Interest totals 10% × (10 + 8 + 6 + 4 + 2) lakh = ₹3 lakh, less than an EMI loan's ₹3.19 lakh because principal falls faster.","difficulty":"hard","source":"Bank MT · Treasury"},
  {"id":"mgmt-finance-569","question":"Firm X trades at 8× EV/EBITDA with net debt of 3× EBITDA. Depreciation is 20% of EBITDA, interest is 9% of net debt, and the tax rate is 25%. What P/E does this imply?","options":["12.6×","13.3×","8.0×","9.4×"],"answer":0,"explanation":"Per ₹1 of EBITDA: equity value = 8 − 3 = 5; EBIT = 0.80; interest = 0.27; net income = (0.80 − 0.27) × 0.75 = 0.3975. P/E = 5/0.3975 = 12.6×. Leverage can make P/E far higher than EV/EBITDA.","difficulty":"very-hard","source":"IB analyst test · Corporate finance"},
  {"id":"mgmt-finance-570","question":"A project costs ₹150 lakh and is expected to return ₹100 lakh at the end of each of years 1 and 2. Certainty-equivalent coefficients are 0.9 for year 1 and 0.8 for year 2, and the risk-free rate is 6%. What is the NPV?","options":["₹33.34 lakh","₹6.11 lakh","−₹5.87 lakh","₹10.38 lakh"],"answer":1,"explanation":"Convert to certain flows (90 and 80) and discount at the RISK-FREE rate: 90/1.06 + 80/1.06² − 150 = ₹6.11 lakh. Discounting certainty equivalents at a risk-adjusted rate double-counts risk.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-571","question":"Which statement about risk-adjusted discount rates (RADR) is correct?","options":["A constant RADR treats each year's cash flow as equally risky in total","RADR and certainty-equivalent methods always give different decisions","A constant RADR implies risk compounds, so later flows are hit harder","RADR should be combined with certainty-equivalent cash flows"],"answer":2,"explanation":"Discounting at r + premium every year compounds the risk premium, so far-off flows are penalised progressively more. That suits risk that compounds over time but may overstate the risk of near-certain late cash flows.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-572","question":"A target's board adopts a shareholder-rights plan that lets every shareholder except a hostile bidder buy new shares at a deep discount once the bidder crosses 15% ownership. What is this defence called, and what is its main effect?","options":["A white knight; it invites a friendlier acquirer to outbid the raider","A golden parachute; it rewards managers if the firm is taken over","A crown-jewel defence; it sells off the most valuable assets","A poison pill; it makes the takeover costly by diluting the bidder"],"answer":3,"explanation":"Flip-in poison pills dilute the bidder's stake and value, forcing it to negotiate with the board. White knights, golden parachutes and crown-jewel sales are different defences.","difficulty":"hard","source":"IB analyst test · Corporate finance"},
  {"id":"mgmt-finance-573","question":"At 10%, which is worth more today: ₹1,000 a year for 10 years or ₹600 a year for 20 years (both paid at year-end)?","options":["The 10-year stream (₹6,144.57 vs ₹5,108.14)","The 20-year stream (₹5,108.14 vs ₹6,144.57), since it pays ₹12,000 in total","They are worth the same","The 20-year stream, because longer annuities have higher PV factors"],"answer":0,"explanation":"PV(10 × ₹1,000) = ₹6,144.57; PV(20 × ₹600) = ₹5,108.14. The extra ₹2,000 of nominal cash in the 20-year stream arrives too late to make up the gap.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-574","question":"An Indian investor buys a US share. Over the year the share rises 10% in dollars and the dollar appreciates 5% against the rupee. What is her return in rupees?","options":["15.0%","15.5%","5.0%","4.76%"],"answer":1,"explanation":"Rupee return = (1 + 0.10) × (1 + 0.05) − 1 = 15.5%; the cross term 0.5% is easily missed. If the dollar had fallen 5%, the return would be 4.5%.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-575","question":"A share trades at a forward P/E of 20. The company pays out 60% of earnings and dividends are expected to grow at 5% forever. What cost of equity does the market price imply?","options":["8.3%","11.0%","8.0%","5.0%"],"answer":2,"explanation":"Forward P/E = payout/(r − g), so r = payout/(P/E) + g = 0.60/20 + 5% = 8.0%. Using the earnings yield (5%) as the cost of equity ignores growth.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-576","question":"An Indian company's US subsidiary's balance sheet shrinks in rupee terms when the dollar weakens, though no cash moves. Which exposure is this?","options":["Transaction (contractual) exposure","Economic (operating) exposure","Settlement (delivery) exposure","Translation (accounting) exposure"],"answer":3,"explanation":"Translation exposure arises when foreign-currency financial statements are converted for consolidation. Transaction exposure involves actual contracted cash flows; economic exposure is the effect on future competitiveness.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-577","question":"A VC invests ₹5 crore for 20% of a start-up post-money, but requires a 10% (post-money) employee option pool to be created BEFORE the investment, out of the founders' share. What are the founders' resulting stake and the effective pre-money value of their shares?","options":["70%; ₹17.5 crore","80%; ₹20 crore","72%; ₹18 crore","70%; ₹20 crore"],"answer":0,"explanation":"Post-money = 5/0.20 = ₹25 crore. Investors 20% + pool 10% leave founders 70%, worth 0.70 × 25 = ₹17.5 crore, not the headline ₹20 crore pre-money; the pool is paid for by the founders.","difficulty":"very-hard","source":"MBA finance · Start-up finance"},
  {"id":"mgmt-finance-578","question":"A start-up raised a ₹2 crore convertible note with a 20% discount and a ₹40 crore pre-money valuation cap. It now raises a priced round at ₹60 crore pre-money, with 60 lakh shares outstanding before the round (₹100 a share). How many shares does the note convert into?","options":["2,50,000 shares","3,00,000 shares","2,00,000 shares","2,40,000 shares"],"answer":1,"explanation":"Cap price = 40 crore/60 lakh = ₹66.67; discount price = 0.8 × 100 = ₹80. The holder gets the LOWER price, ₹66.67: 2 crore/66.67 = 3,00,000 shares. Using the discount alone gives 2,50,000.","difficulty":"very-hard","source":"MBA finance · Start-up finance"},
  {"id":"mgmt-finance-579","question":"A division earns an ROI of 20% and its manager is rewarded on divisional ROI. A new project offers a 16% return; the company's cost of capital is 12%. What is likely to happen, and which measure fixes it?","options":["Accepts it, because 16% comfortably exceeds the 12% cost of capital","Rejects it, which is right because 16% is below 20%","Rejects it to protect ROI; residual income would favour it","ROI and residual income give the same decision here"],"answer":2,"explanation":"Taking the project drags average ROI below 20%, so an ROI-rewarded manager rejects it. Residual income (profit − 12% × capital) rises, aligning the decision with shareholder value.","difficulty":"hard","source":"IB analyst test · Corporate finance"},
  {"id":"mgmt-finance-580","question":"Fixed costs are ₹12 lakh and the contribution margin ratio is 30%. Current sales are ₹50 lakh. What are the break-even sales, margin of safety and degree of operating leverage?","options":["₹40 lakh, 25% and 4.0","₹36 lakh, 28% and 3.6","₹40 lakh, 20% and 1.25","₹40 lakh, 20% and 5.0"],"answer":3,"explanation":"Break-even = 12/0.30 = ₹40 lakh; margin of safety = (50 − 40)/50 = 20%; DOL = contribution/EBIT = 15/3 = 5.0 = 1/MOS.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-581","question":"A firm earns a 20% ROE on reinvested capital, grows at 8% a year (consistent with its retention) and has a 12% cost of equity. What justified forward P/E follows?","options":["15.0×","25.0×","5.0×","16.2×"],"answer":0,"explanation":"Retention b = g/ROE = 8/20 = 0.4, so payout = 0.6; forward P/E = payout/(r − g) = 0.6/0.04 = 15×. Using a full payout (1/0.04 = 25×) ignores the reinvestment needed for growth.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-582","question":"Switching tax depreciation on an asset from straight-line to an accelerated (written-down-value) method, with the same total depreciation, will usually:","options":["Leave NPV unchanged, because total depreciation is the same","Raise the project's NPV, because tax savings arrive earlier","Lower NPV, because reported profit is lower early on","Raise NPV only if the asset has salvage value"],"answer":1,"explanation":"Accelerated depreciation brings tax shields forward in time; with positive discount rates their PV rises. Reported accounting profit does not drive NPV.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-583","question":"Why do analysts often value early-stage, loss-making tech companies on EV/Sales rather than P/E?","options":["Sales multiples automatically adjust for profitability differences","EV/Sales ignores capital structure while P/E does not, so it is always superior","Earnings are negative or unstable, while sales are positive and steadier","SEBI regulations require it for all loss-making listed firms"],"answer":2,"explanation":"P/E is meaningless with negative EPS. EV/Sales works but must be interpreted alongside expected margins, since two firms with equal sales can have very different profit potential.","difficulty":"hard","source":"IB analyst test · Corporate finance"},
  {"id":"mgmt-finance-584","question":"A firm's ROA is 10% and it retains 60% of earnings. If it raises NO external finance at all (neither debt nor equity), what is the maximum growth rate it can sustain (internal growth rate)?","options":["6.00%","10.00%","5.66%","6.38%"],"answer":3,"explanation":"IGR = ROA × b/(1 − ROA × b) = 0.06/0.94 = 6.38%. The sustainable growth rate would be higher because it lets debt grow in line with equity.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-585","question":"Sales are ₹1,000 crore and will rise to ₹1,200 crore. Assets are 80% of sales and spontaneous liabilities 20% of sales, both proportional. The net margin is 5% and the payout ratio 40%. How much external financing is needed?","options":["₹84 crore","₹120 crore","₹90 crore","₹60 crore"],"answer":0,"explanation":"EFN = ΔAssets − ΔSpontaneous liabilities − retained earnings = 0.8 × 200 − 0.2 × 200 − 0.05 × 1,200 × 0.6 = 160 − 40 − 36 = ₹84 crore. Basing retained earnings on old sales gives ₹90 crore.","difficulty":"very-hard","source":"IB analyst test · Corporate finance"},
  {"id":"mgmt-finance-586","question":"A pension product costs ₹1,00,000 today and pays ₹13,000 at the end of each year for 15 years. What annual return does it offer?","options":["13.00%","9.80%","4.55%","6.33%"],"answer":1,"explanation":"Solve 1,00,000 = 13,000 × annuity factor (15 yrs): r ≈ 9.80%. 13% treats it as a perpetuity, and the CAGR of total cash (4.55%) treats all receipts as arriving at the end.","difficulty":"hard","source":"MBA finance · Start-up finance"},
  {"id":"mgmt-finance-587","question":"A contract pays ₹10,000 at the end of year 1, rising by ₹1,000 each year (₹11,000, ₹12,000, ...) for 5 payments in total. At 10%, what is its present value?","options":["₹45,489.44","₹45,078.89","₹44,769.67","₹45,454.55"],"answer":2,"explanation":"Discount each payment: 10,000/1.1 + 11,000/1.1² + … + 14,000/1.1⁵ = ₹44,769.67. Using the average ₹12,000 as a level annuity overvalues it because the larger amounts come later.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-588","question":"A project's cash flows are −100, +50, −20 and +120 at t = 0–3. The firm's finance rate is 8% and its reinvestment rate 12%. What is its MIRR?","options":["18.53%","17.04%","15.05%","15.97%"],"answer":3,"explanation":"PV of outflows at 8% = 100 + 20/1.08² = 117.15; FV of inflows at 12% = 50 × 1.12² + 120 = 182.72; MIRR = (182.72/117.15)^(1/3) − 1 = 15.97%.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-589","question":"An investor holding a share at ₹500 places a stop-loss sell order at ₹450 (a stop-market order). Overnight bad news makes the share open at ₹420. What happens?","options":["It triggers and fills at about ₹420, below the ₹450 stop","It executes at exactly ₹450, the stop price","It does not execute, because the price never traded at ₹450","It converts into a limit order at ₹450 and waits"],"answer":0,"explanation":"A stop-market order becomes a market order once the stop is reached or passed, so in a gap it fills at the next available price. A stop-limit order would protect the price but might not execute.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-590","question":"₹1,00,000 is due in 5 years. What is its present value at 8% compounded continuously, and at 8% compounded annually?","options":["₹68,058 and ₹67,032","₹67,032 and ₹68,058","₹60,000 and ₹68,058","₹71,429 and ₹68,058"],"answer":1,"explanation":"Continuous: 1,00,000 × e^(−0.40) = ₹67,032; annual: 1,00,000/1.08⁵ = ₹68,058. Continuous compounding is a higher effective rate, so its PV is lower.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-591","question":"A bond has Macaulay duration 7.2 years, convexity 60 and a yield to maturity of 8% (annual compounding). If its yield rises by 50 basis points, what is the best estimate of the percentage price change using both duration and convexity?","options":["-3.33%","-3.60%","-3.26%","-3.41%"],"answer":2,"explanation":"Modified duration = 7.2/1.08 = 6.667. Price change ≈ -6.667 x 0.005 + 0.5 x 60 x 0.005^2 = -3.333% + 0.075% = -3.26%. Convexity always adds to the price, so subtracting it, or using Macaulay duration (-3.60%), is wrong.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-592","question":"A 3-year bond with face value ₹100 pays a 12% annual coupon and is priced to yield 8%. What is its Macaulay duration?","options":["2.74 years","2.71 years","3.00 years","2.00 years"],"answer":1,"explanation":"Price = 110.31. Duration = Σ t x PV(CF)/Price = (1 x 11.11 + 2 x 10.29 + 3 x 88.91)/110.31 = 2.71. Weighting by undiscounted cash flows gives 2.74, and 3.00 would be a zero-coupon bond.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-593","question":"A project is expected to yield ₹1,00,000 a year for 3 years in today's purchasing power (real terms). Inflation is 4% a year and the nominal required return is 9.2% (so the real rate is 5%). What is the present value of the inflows?","options":["₹2,52,230","₹2,72,325","₹2,94,322","₹2,83,218"],"answer":1,"explanation":"Nominal flows are 1,00,000 x 1.04^t, discounted at 9.2% = 1.04 x 1.05 - 1, which equals discounting the real flows at 5%: 272,325. Discounting real flows at the nominal rate (252,230) mixes real and nominal; inflating flows but discounting at the real rate double-counts inflation.","difficulty":"very-hard","source":"MBA Finance · Big 4"},
  {"id":"mgmt-finance-594","question":"A firm has a ₹10 crore capital budget and four indivisible projects (investment, NPV in ₹ crore): A (6, 1.2), B (4, 1.0), C (5, 1.1), D (3, 0.6). What is the maximum total NPV it can obtain?","options":["₹2.1 crore","₹2.2 crore","₹1.8 crore","₹2.9 crore"],"answer":1,"explanation":"Evaluate feasible combinations: A + B uses exactly 10 for NPV 2.2; B + C (9) gives 2.1; A + D (9) gives 1.8. Ranking by profitability index (B 0.25, C 0.22, A 0.20 = D 0.20) picks B + C = 2.1, which is not optimal when projects are lumpy.","difficulty":"hard","source":"CAT · MBA placement"},
  {"id":"mgmt-finance-595","question":"Mutually exclusive projects X and Y have cash flows at t = 0, 1, 2 of X: -1,000, 1,000, 300 and Y: -1,000, 500, 850. Below which discount rate does Y have the higher NPV?","options":["10%","20.5%","24.2%","5%"],"answer":0,"explanation":"The difference Y - X is (0, -500, +550); its IRR (the crossover) solves -500/(1+r) + 550/(1+r)^2 = 0, i.e. r = 10%. IRR of X is 24.2% and of Y is 20.5%, but the crossover is what decides the ranking.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-596","question":"A company plans a new equity issue at ₹100 per share. Flotation costs are 5% of the issue price, the next dividend is ₹8 and dividends grow at 6% a year forever. What is the cost of new equity?","options":["14.42%","14.00%","8.42%","14.70%"],"answer":0,"explanation":"Net proceeds are 95 per share, so ke = 8/95 + 6% = 8.42% + 6% = 14.42%. Ignoring flotation gives 14.00%; adding flotation as a percentage uplift (14.70%) is wrong because it applies to the price, not the return.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-597","question":"A firm's equity has a market value of ₹60 crore (book ₹30 crore) and cost 14%; its debt has a market value of ₹40 crore (book ₹50 crore) and pre-tax cost 9%. The tax rate is 30%. What is the WACC?","options":["9.19%","10.92%","12.00%","10.88%"],"answer":1,"explanation":"Use market-value weights (60% / 40%) and after-tax debt cost 9% x 0.7 = 6.3%: 0.6 x 14 + 0.4 x 6.3 = 10.92%. Book weights give 9.19%, and omitting the tax shield gives 12.00%.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-598","question":"A comparable company has an equity beta of 1.4, a debt-to-equity ratio of 0.5 and a tax rate of 30% (debt beta zero). A project of similar business risk will be financed at D/E = 1.0. What equity beta should be used?","options":["1.76","1.87","1.04","2.38"],"answer":0,"explanation":"Unlever: 1.4/(1 + 0.7 x 0.5) = 1.037. Relever: 1.037 x (1 + 0.7 x 1.0) = 1.76. Ignoring the tax adjustment gives 1.87, and quoting the unlevered beta (1.04) understates the equity risk at higher leverage.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-599","question":"Under Modigliani-Miller with corporate taxes (and no distress costs), an unlevered firm is worth ₹100 crore. It borrows ₹40 crore permanently at a 30% tax rate and uses the proceeds to repurchase shares. What is the value of its equity after the recapitalisation?","options":["₹60 crore","₹112 crore","₹72 crore","₹88 crore"],"answer":2,"explanation":"V_L = V_U + t x D = 100 + 0.3 x 40 = 112. Equity = V_L - D = 112 - 40 = 72. Without taxes equity would be 60 (value unchanged); 112 is the total firm value, not equity.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-600","question":"A firm with 10 lakh shares trading at ₹50 (market value ₹5 crore, no debt) uses cash to repurchase 1 lakh shares at ₹55 in a tender offer. Assuming the market values the remaining business at the unchanged value less the cash paid, what is the share price after the buyback?","options":["₹50.00","₹44.50","₹49.44","₹55.00"],"answer":2,"explanation":"Firm value falls by the cash paid, 1 lakh x 55 = 55 lakh, to 4.45 crore, spread over 9 lakh shares = 49.44. Because the buyback is at a premium to market, continuing holders lose a little to those who tender.","difficulty":"hard","source":"MBA Finance · Big 4"},
  {"id":"mgmt-finance-601","question":"A share trades cum-dividend at ₹120, with a dividend of ₹8 to be paid. Investors pay 20% tax on dividends and no tax on capital gains, and the market is in equilibrium between buying before and after the ex-date. What is the theoretical ex-dividend price?","options":["₹112.00","₹118.40","₹120.00","₹113.60"],"answer":3,"explanation":"Holders must be indifferent between buying cum or ex: the dividend is worth only 8 x 0.8 = 6.40 after tax, so the price falls by 6.40 to 113.60. A full 8 fall (112) would only apply if dividends were untaxed.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-602","question":"Suppliers offer terms of 3/15 net 45. Using a 365-day year, what is the effective annual cost (with compounding) of NOT taking the discount and paying on day 45?","options":["37.6%","3.1%","44.9%","43.3%"],"answer":2,"explanation":"Each 30 extra days of credit costs 3/97 = 3.09%. Compounding over 365/30 = 12.17 periods gives (1.0309)^12.17 - 1 = 44.9%; the simple annualised rate is 37.6%.","difficulty":"hard","source":"MBA Finance · Big 4"},
  {"id":"mgmt-finance-603","question":"A firm needs ₹9,00,000 of cash a year, spread evenly, funded by selling securities. Each sale costs ₹100 and securities earn 5% a year. Using the Baumol model, what is the minimum total annual cost of cash management (transaction plus opportunity cost) at the optimal lot size?","options":["₹1,500","₹6,000","₹3,000","₹4,500"],"answer":2,"explanation":"Optimal lot C* = sqrt(2 x 9,00,000 x 100 / 0.05) = 60,000. Transactions cost = 15 x 100 = 1,500 and opportunity cost = 30,000 x 5% = 1,500, so the total is 3,000; at the optimum the two parts are equal.","difficulty":"hard","source":"MBA Finance · Big 4"},
  {"id":"mgmt-finance-604","question":"A firm has annual credit sales of ₹120 lakh, variable cost 75% of sales and an average collection period of 30 days. If it extends credit terms, sales will rise 15% and the collection period will become 45 days; extra bad debts will be 1% of the new sales. The cost of funds is 12% and investment in debtors is measured at variable cost (360-day year). What is the net annual benefit of the change?","options":["₹3,84,750","₹2,25,000","₹3,12,000","₹2,46,750"],"answer":3,"explanation":"Incremental contribution = 18 x 25% = 4.50 lakh. Bad debts = 1.38 lakh. Debtors at variable cost rise from 7.5 to 12.94 lakh, costing 5.44 x 12% = 0.65 lakh. Net = 4.50 - 1.38 - 0.65 = 2.4675 lakh. Ignoring bad debts or measuring debtors at sales value changes the answer.","difficulty":"hard","source":"MBA Finance · Big 4"},
  {"id":"mgmt-finance-605","question":"A firm can buy a ₹10 lakh machine (4-year life, straight-line depreciation to zero, no salvage) or lease it for ₹2.8 lakh a year payable at the start of each year. The tax rate is 25%, the after-tax discount rate is 9%, and tax effects occur in the same year as the payment or the depreciation charge. What is the net advantage to leasing (PV of buying minus PV of leasing)?","options":["₹-1.91 lakh (ignoring tax on rentals)","₹-0.56 lakh against leasing","₹0.56 lakh in favour of leasing","₹2.58 lakh in favour of leasing"],"answer":2,"explanation":"Buying: 10 - PV of depreciation tax shield (0.625 a year for 4 years) = 7.98. Leasing: after-tax rental 2.1 paid at t = 0, 1, 2, 3 has PV 7.42. Advantage = 0.56. Rentals paid in advance and the tax shield on rentals both matter.","difficulty":"very-hard","source":"MBA Finance · Big 4"},
  {"id":"mgmt-finance-606","question":"A European call on a non-dividend share (spot ₹100, strike ₹105, one year, call premium ₹9) trades while the risk-free rate is 6% (annual compounding). By put-call parity, what is the fair premium of the European put with the same strike and expiry?","options":["₹14.00","₹9.94","₹5.00","₹8.06"],"answer":3,"explanation":"Put = Call - S + K/(1 + r) = 9 - 100 + 99.06 = 8.06. Using the undiscounted strike gives 14.00, and reversing the sign of S gives 9.94.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-607","question":"An investor buys a share at ₹200 and writes a call with strike ₹220 for a premium of ₹8. What is her profit per share if the share is ₹240 at expiry?","options":["₹48","₹40","₹20","₹28"],"answer":3,"explanation":"The call is exercised, so she sells at 220: gain on stock = 20, plus premium 8 = 28. The upside is capped, so the 40 stock gain beyond that goes to the call holder.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-608","question":"An investor buys a call with strike ₹100 for ₹10 and sells a call with strike ₹110 for ₹4 (same expiry, same share). What is the break-even share price at expiry?","options":["₹104","₹106","₹110","₹114"],"answer":1,"explanation":"The net debit is 10 - 4 = 6, so the spread must be worth 6 at expiry: 100 + 6 = 106. Maximum profit is 4 (above 110) and maximum loss is 6 (below 100).","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-609","question":"A commodity spot price is ₹500. The risk-free rate is 8% and storage costs are 2% a year (both continuously compounded) and the convenience yield is 1% a year. What is the no-arbitrage 6-month futures price?","options":["₹523.0","₹517.8","₹525.6","₹528.3"],"answer":0,"explanation":"F = S e^{(r + u - y)T} = 500 e^{(0.08 + 0.02 - 0.01) x 0.5} = 500 e^{0.045} = 523.0. Omitting the convenience yield gives 525.6, adding it gives 528.3 and forgetting storage gives 517.8.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-610","question":"A fund holds ₹5 crore of equities with beta 1.2 and wants to cut the portfolio beta to 0.8 using index futures. The index is at 20,000 and one contract has a multiplier of 50 (contract value ₹10 lakh), with futures beta of 1. What should it do?","options":["Sell 60 contracts","Buy 20 contracts","Sell 20 contracts","Sell 40 contracts"],"answer":2,"explanation":"Contracts = (β_target - β_portfolio) x V / contract value = (0.8 - 1.2) x 5,00,00,000 / 10,00,000 = -20, i.e. sell 20. Selling 60 would remove the beta altogether (to zero).","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-611","question":"The spot rate is ₹83 per US dollar. Three-month money-market rates are 8% a year in India and 4% a year in the US (simple interest, quoted per annum). What is the 3-month forward rate that rules out covered-interest arbitrage?","options":["₹82.19","₹83.82","₹86.19","₹84.66"],"answer":1,"explanation":"F = S x (1 + r_INR x 0.25)/(1 + r_USD x 0.25) = 83 x 1.02/1.01 = 83.82. Inverting the ratio gives 82.19, and using annual rates without scaling to 3 months gives 86.19.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-612","question":"The 2-year spot rate is 5% and the 3-year spot rate is 8% (annual compounding, zero-coupon). What is the implied 1-year forward rate for the third year?","options":["14.00%","14.26%","11.00%","8.00%"],"answer":1,"explanation":"(1.08)^3/(1.05)^2 = 1.259712/1.1025 = 1.1426, so the forward rate is 14.26%. The shortcut 3 x 8 - 2 x 5 = 14% ignores compounding.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-613","question":"A pension fund must pay a single liability in exactly 5 years and wants to immunise it using zero-coupon bonds maturing in 3 years and 8 years, with the present value of assets equal to the present value of the liability. What proportion of the assets (by value) goes into the 3-year bond?","options":["60%","40%","62.5%","50%"],"answer":0,"explanation":"Duration of a zero equals its maturity, so match asset duration to 5: w x 3 + (1 - w) x 8 = 5, giving w = 0.6. 62.5% (5/8) is not a weight; 40% is the 8-year bond's share.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-614","question":"Asset A has a standard deviation of 20% and Asset B 30%; their correlation is 0.25. What is the standard deviation of the minimum-variance portfolio of A and B?","options":["18.37%","24.00%","20.00%","18.97%"],"answer":0,"explanation":"Weight in A = (0.09 - 0.25 x 0.06)/(0.04 + 0.09 - 2 x 0.25 x 0.06) = 0.075/0.10 = 75%. Variance = 0.03375, standard deviation 18.37%, below even A's 20% alone because of diversification.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-615","question":"The risk-free rate is 5% and the market return is 11%. Portfolio P returned 14% with standard deviation 18% and beta 1.1; Portfolio Q returned 12% with standard deviation 10% and beta 0.8. Which statement is correct?","options":["P is better on all three measures, given its higher return","Q is better on all three measures, given its lower risk","P has the higher Sharpe ratio, Q the higher Treynor ratio","Q wins on Sharpe and Treynor; P has the higher alpha"],"answer":3,"explanation":"Sharpe: P 0.50, Q 0.70. Treynor: P 8.18, Q 8.75. Jensen's alpha: P = 14 - (5 + 1.1 x 6) = 2.4, Q = 12 - (5 + 0.8 x 6) = 2.2. The rankings differ because alpha ignores the scale of beta.","difficulty":"very-hard","source":"CFA Level I"},
  {"id":"mgmt-finance-616","question":"A share has just paid a dividend of ₹10. Dividends will grow 15% a year for the next 3 years and 5% a year forever afterwards. The required return is 12%. What is the value of the share today?","options":["₹150.0","₹162.4","₹209.2","₹194.0"],"answer":3,"explanation":"Dividends: 11.50, 13.23, 15.21. Terminal value at year 3 = 15.21 x 1.05/0.07 = 228.1. PV = 194.0. Using 5% growth from today gives 150.0, and the terminal value alone discounted is only 162.4.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-617","question":"A firm earns a sustainable ROE of 18%, its dividends will grow at 8% a year, and its cost of equity is 13%. What is its justified price-to-book ratio?","options":["2.00","1.38","0.50","3.60"],"answer":0,"explanation":"Justified P/B = (ROE - g)/(k - g) = (0.18 - 0.08)/(0.13 - 0.08) = 2.0. ROE/k = 1.38 ignores growth; 3.60 uses ROE/(k - g), and 0.50 inverts the ratio.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-618","question":"A firm can invest ₹50 crore (all values are in present-value terms). With probability 0.6 the project succeeds and its continuing value is ₹120 crore; with probability 0.4 it fails and its continuing value is only ₹20 crore, but the assets could then be sold for ₹40 crore. What is the value of the option to abandon?","options":["₹8 crore","₹20 crore","₹12 crore","₹16 crore"],"answer":0,"explanation":"The option matters only in the failure state, where it adds 40 - 20 = 20, so its expected value is 0.4 x 20 = 8. Using the full 20 ignores the probability; 0.4 x 40 = 16 counts the salvage as if the project were otherwise worth nothing.","difficulty":"hard","source":"MBA Finance · Big 4"},
  {"id":"mgmt-finance-619","question":"A project costs ₹100 and returns ₹30 a year for 5 years; the discount rate is 10%. By what percentage can the annual cash flow fall (all years equally) before the NPV becomes zero?","options":["13.7%","33.3%","12.1%","10.0%"],"answer":2,"explanation":"Annuity factor = 3.7908, so NPV = 13.72 and PV of inflows = 113.72. Break-even cash flow = 100/3.7908 = 26.38, a fall of 12.1% (NPV divided by PV of inflows, not by the investment).","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-620","question":"A firm needs ₹1 crore and can raise it by issuing 10 lakh equity shares at ₹10 each (it already has 10 lakh shares) or by 10% debentures. The tax rate is 30%. At what EBIT are the EPS under the two plans equal?","options":["₹20 lakh","₹10 lakh","₹30 lakh","₹14 lakh"],"answer":0,"explanation":"Equity plan: 20 lakh shares. Debt plan: 10 lakh shares and interest 10 lakh. Equate EBIT/20 = (EBIT - 10)/10 (the common 0.7 cancels): EBIT = 2 EBIT - 20, so EBIT = 20 lakh. Above this, debt gives the higher EPS.","difficulty":"hard","source":"MBA Finance · Big 4"},
  {"id":"mgmt-finance-621","question":"Acquirer A has 10 crore shares at ₹200; target T has 2 crore shares at ₹80. Synergies are worth ₹50 crore. A offers 0.5 of its own share for each T share (worth ₹100 at A's current price). What is the gain to A's existing shareholders from the stock deal?","options":["₹10.00 crore","₹50.00 crore","₹9.09 crore","₹40.91 crore"],"answer":2,"explanation":"Combined value = 2,000 + 160 + 50 = 2,210 crore over 11 crore shares = ₹200.91 per share. A's holders own 10 crore shares: 2,009.09 against 2,000 before, a gain of 9.09. An all-cash offer at ₹100 would give 10.00 because A's holders keep all the synergy less the premium, while a stock deal shares the synergy.","difficulty":"very-hard","source":"MBA Finance · Big 4"},
  {"id":"mgmt-finance-622","question":"A bank has an exposure of ₹50 crore to a borrower with a one-year probability of default of 2%. If default occurs, the bank recovers 55% of the exposure. What is the expected loss?","options":["₹1.00 crore","₹0.45 crore","₹22.50 crore","₹0.55 crore"],"answer":1,"explanation":"Expected loss = PD x LGD x EAD = 0.02 x 0.45 x 50 = 0.45 crore, where LGD = 1 - recovery rate. PD x EAD alone (1.00) ignores recovery; 0.55 uses the recovery rate instead of the loss rate.","difficulty":"hard","source":"CFA Level I · Banking MT"},
  {"id":"mgmt-finance-623","question":"A portfolio worth ₹10 crore has a daily return standard deviation of 1.2%, returns are normal with zero mean, and the one-tailed 99% z-value is 2.33. What is the 10-day 99% parametric VaR, scaling by the square-root-of-time rule?","options":["₹88.4 lakh","₹28.0 lakh","₹279.6 lakh","₹62.4 lakh"],"answer":0,"explanation":"One-day VaR = 2.33 x 1.2% x 10 crore = 27.96 lakh. Over 10 days volatility scales with sqrt(10): 27.96 x 3.162 = 88.4 lakh. Multiplying by 10 overstates, and z = 1.645 would be the 95% level.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-624","question":"A scheme pays ₹1,00,000 at the end of the first year, with payments then growing 5% a year, for 10 years in all. At a discount rate of 9%, what is its present value?","options":["₹6,41,766","₹25,00,000","₹8,50,029","₹7,79,843"],"answer":3,"explanation":"Growing annuity: 1,00,000/(0.09 - 0.05) x [1 - (1.05/1.09)^10] = 779,843. The no-growth annuity gives 641,766 and the perpetuity formula gives 2,500,000; multiplying by 1.09 would treat the first payment as due today.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-625","question":"A ₹30 lakh home loan at 9% a year (monthly rests) is repaid over 20 years by equal monthly instalments of about ₹26,992. After 5 years (60 instalments) the borrower prepays ₹5 lakh and keeps the instalment unchanged. About how many months remain?","options":["About 159 months","About 123 months","About 161 months","180 months"],"answer":1,"explanation":"Balance after 60 instalments = 2,661,211; after the prepayment it is 2,161,211. Months n solve 26,992 x [1 - 1.0075^-n]/0.0075 = 2,161,211, giving n ≈ 123. Subtracting 5,00,000/26,992 = 18.5 months from 180 ignores interest saved; treating the balance as 25 lakh ignores principal already repaid.","difficulty":"very-hard","source":"MBA Finance · Big 4"},
  {"id":"mgmt-finance-626","question":"A convertible bond (face ₹1,000) can be converted into 20 equity shares. The share trades at ₹42, the bond at ₹950, and a comparable non-convertible bond would be worth ₹800. What is the conversion premium (the premium over conversion value)?","options":["18.75%","11.6%","13.1%","11.0%"],"answer":2,"explanation":"Conversion value = 20 x 42 = 840. Premium = (950 - 840)/840 = 13.1%. 18.75% is the premium over straight-bond value (950/800), and dividing by the bond price (11.6%) uses the wrong base.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-627","question":"A pension pays ₹20,000 a year for 10 years, the first payment being made at the end of year 5. The discount rate is 8%. What is its present value today?","options":["₹91,335","₹98,642","₹1,34,202","₹1,06,534"],"answer":1,"explanation":"The 10-payment annuity is worth 134,202 one period before its first payment, i.e. at the end of year 4, so discount it 4 years: 98,642. Discounting 5 years assumes the first payment is at year 6.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-628","question":"A lender quotes a flat rate of 8% a year on a ₹1,00,000 loan repaid in 24 equal monthly instalments (interest is 8% of the original principal each year, added on). What is the approximate effective annual interest rate?","options":["14.7%","15.7%","8.0%","16.0%"],"answer":1,"explanation":"Instalment = (1,00,000 + 16,000)/24 = 4,833. The monthly IRR of 24 payments of 4,833 against 1,00,000 received is 1.223%, i.e. 14.7% nominal or 15.7% effective. A flat rate understates the cost since the principal is repaid gradually.","difficulty":"very-hard","source":"MBA Finance · Big 4"},
  {"id":"mgmt-finance-629","question":"A bond of face ₹100 pays an 8% coupon semi-annually (30/360 day count). Two months have passed since the last coupon date. If the quoted (clean) price is ₹98.50, what must the buyer actually pay?","options":["₹97.17","₹98.50","₹102.50","₹99.83"],"answer":3,"explanation":"Accrued interest = annual coupon 8 x 2/12 = 1.33. Full (dirty) price = clean + accrued = 98.50 + 1.33 = 99.83. Adding a whole semi-annual coupon (4) or deducting accrued interest are errors.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-630","question":"A company announces a rights issue of 1 new share for every 4 held at ₹110. The cum-rights price is ₹150. What is the theoretical ex-rights price?","options":["₹142","₹150","₹130","₹140"],"answer":0,"explanation":"TERP = (4 x 150 + 1 x 110)/5 = 142, so one right is worth 150 - 142 = 8. Averaging the two prices (130) ignores the 4 : 1 weighting.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-631","question":"A stock has a standard deviation of 30% and a correlation of 0.6 with the market, whose standard deviation is 20%. The risk-free rate is 5% and the expected market return is 11%. What return does the CAPM require?","options":["8.6%","14.0%","11.0%","10.4%"],"answer":3,"explanation":"Beta = ρ x σi/σm = 0.6 x 0.30/0.20 = 0.9. Required return = 5 + 0.9 x 6 = 10.4%. Using the correlation as beta gives 8.6%, and the volatility ratio alone (1.5) gives 14%.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-632","question":"A company's free cash flow to the firm for the year just ended was ₹50 crore and is expected to grow at 4% a year forever. WACC is 10%, net debt is ₹200 crore and there are 10 crore shares. What is the value per share?","options":["₹63.33","₹66.67","₹86.67","₹83.33"],"answer":1,"explanation":"FCFF next year = 50 x 1.04 = 52, so EV = 52/(0.10 - 0.04) = 866.67 crore. Equity = 866.67 - 200 = 666.67; per share = 66.67. Using 50 as next year's flow gives 63.33, and forgetting net debt gives 86.67.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-633","question":"A fund returned 12.5% against a benchmark return of 9.5%. Its tracking error (standard deviation of active returns) was 4%, its total volatility 15% and the risk-free rate 5%. What is its information ratio?","options":["0.75","0.50","0.20","1.88"],"answer":0,"explanation":"Information ratio = active return / tracking error = (12.5 - 9.5)/4 = 0.75. The Sharpe ratio would be (12.5 - 5)/15 = 0.50; 1.88 uses excess return over the risk-free rate divided by tracking error.","difficulty":"hard","source":"CFA Level I"},
  {"id":"mgmt-finance-634","question":"Quotes: ₹90 per euro (direct), US$1.10 per euro and ₹83 per US dollar. Starting with ₹1 crore and ignoring costs, what is the profit from the best triangular arbitrage?","options":["₹1,30,000","₹1,42,388","₹1,44,444","Loss of ₹1,42,388"],"answer":2,"explanation":"The implied cross rate is 1.10 x 83 = ₹91.30 per euro, above the direct ₹90. Buy euros directly: 1 crore/90 = 1,11,111 euros; sell for dollars at 1.10 = 1,22,222; sell dollars at 83 = ₹10,144,444. Profit = 144,444. Running the loop in the opposite direction loses 142,388.","difficulty":"very-hard","source":"MBA Finance · Big 4"},
  {"id":"mgmt-finance-635","question":"Under a two-factor APT the risk-free rate is 4%, the risk premium on factor 1 is 5% and on factor 2 is 3%. A stock has factor betas of 1.2 and 0.5. What is its expected return?","options":["10.0%","12.5%","7.5%","11.5%"],"answer":3,"explanation":"E(R) = 4 + 1.2 x 5 + 0.5 x 3 = 4 + 6 + 1.5 = 11.5%. Omitting the risk-free rate gives 7.5%.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-636","question":"A nominal government bond yields 7.5% and an inflation-indexed bond of the same maturity yields a real 3.0%. What is the break-even inflation rate (exact, using the Fisher relation)?","options":["4.50%","4.37%","10.50%","3.00%"],"answer":1,"explanation":"1 + nominal = (1 + real)(1 + inflation), so inflation = 1.075/1.03 - 1 = 4.37%. The simple difference (4.50%) overstates it a little because it ignores the cross term.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-637","question":"A project needs ₹20 lakh of machinery (4-year life, straight-line depreciation to zero) and ₹3 lakh of working capital at the start. It earns ₹8 lakh a year before depreciation and tax; the tax rate is 30%. At the end of year 4 the machine is sold for ₹2 lakh (book value zero, so the gain is taxed) and working capital is recovered. At a 12% cost of capital, what is the NPV?","options":["₹1.36 lakh","₹-0.55 lakh","₹1.74 lakh","₹2.45 lakh"],"answer":0,"explanation":"Annual after-tax cash flow = (8 - 5) x 0.7 + 5 = 7.1; PV over 4 years = 21.57. Terminal: after-tax salvage 1.4 plus working capital 3.0, discounted = 2.80. NPV = -23 + 21.57 + 2.80 = 1.36. Missing the working-capital recovery, the salvage tax or the initial working capital shifts the NPV.","difficulty":"very-hard","source":"MBA Finance · Big 4"},
  {"id":"mgmt-finance-638","question":"A firm buys a 3 x 9 forward rate agreement on a notional of ₹10 crore at an agreed rate of 8% (for a 6-month period). At settlement the 6-month reference rate is 9%. What is the settlement amount received at the start of the 6-month period?","options":["₹5,00,000","₹4,80,769","₹9,56,938","₹4,78,469"],"answer":3,"explanation":"Interest difference = 10 crore x 1% x 0.5 = 5,00,000 payable at the end of the period; because an FRA settles at the start, discount at the market rate: 5,00,000/1.045 = 4,78,469. Discounting at the contract rate (4,80,769) or forgetting the half-year (9,56,938) is wrong.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-639","question":"An investor buys 1 unit of a fund at ₹100. A year later it is worth ₹120 and she buys one more unit at that price. At the end of year 2 each unit is worth ₹108. What is her time-weighted annual return?","options":["5.00%","8.00%","-1.26%","3.92%"],"answer":3,"explanation":"Year 1 return +20%, year 2 return 108/120 - 1 = -10%. TWR = sqrt(1.20 x 0.90) - 1 = 3.92% a year. The arithmetic mean (5%) is not geometric, and -1.26% is the money-weighted return (IRR), which is hurt by the larger amount invested before the fall.","difficulty":"very-hard","source":"CFA Level I"},
  {"id":"mgmt-finance-640","question":"A firm reports net income ₹40 crore, depreciation ₹10 crore, capital expenditure ₹25 crore, an increase in net working capital of ₹5 crore, and net new borrowing of ₹8 crore. What is its free cash flow to equity?","options":["₹12 crore","₹28 crore","₹18 crore","₹33 crore"],"answer":1,"explanation":"FCFE = NI + depreciation - capex - ΔNWC + net borrowing = 40 + 10 - 25 - 5 + 8 = 28. Subtracting borrowing gives 12, forgetting depreciation gives 18 and ignoring working capital gives 33.","difficulty":"moderate","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-641","question":"A project costs ₹500 and returns ₹150, ₹200, ₹250 and ₹300 at the end of years 1 to 4. At a 10% discount rate, what is the discounted payback period?","options":["3.05 years","2.60 years","3.50 years","3.20 years"],"answer":0,"explanation":"Discounted flows are 136.4, 165.3, 187.8 and 204.9; cumulative 489.5 after year 3, so 10.5 of the 204.9 remains in year 4: 3 + 10.5/204.9 = 3.05. The undiscounted payback is 2.60 years.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-642","question":"A project costs ₹1,000 and returns ₹400 at the end of each of the next 3 years. Cash inflows can be reinvested at 12%. What is the modified IRR (MIRR)?","options":["9.7%","6.3%","10.5%","12.0%"],"answer":2,"explanation":"Terminal value of inflows at 12% = 400 x 1.2544 + 400 x 1.12 + 400 = 1349.76. MIRR = (1349.76/1000)^(1/3) - 1 = 10.5%. The ordinary IRR is 9.7% because it implicitly assumes reinvestment at the IRR itself.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-643","question":"A firm has a net profit margin of 8%, total asset turnover of 1.5 and an equity multiplier of 2.0, and pays out 25% of earnings. What is its sustainable growth rate (with constant ratios and no new equity)?","options":["24%","6%","18%","9%"],"answer":2,"explanation":"ROE = 0.08 x 1.5 x 2.0 = 24%. Retention = 75%, so g = ROE x b = 18%. 24% ignores retention, 6% is ROE x payout, and 9% uses ROA (12%) instead of ROE.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-finance-644","question":"An endowment will pay ₹1,00,000 at the end of year 1, and each later payment grows by 5% a year, for 10 payments in all. The discount rate is 10%. What is the present value of the stream?","options":["₹7.44 lakh","₹6.14 lakh","₹7.72 lakh","₹20.00 lakh"],"answer":0,"explanation":"Growing annuity: PV = C/(r − g) × [1 − ((1+g)/(1+r))ⁿ] = 1,00,000/0.05 × [1 − (1.05/1.10)¹⁰] ≈ ₹7.44 lakh. ₹6.14 lakh ignores growth, ₹7.72 lakh wrongly discounts a level annuity at r − g, and ₹20 lakh treats it as a growing perpetuity.","difficulty":"hard","source":"CFA Level I · MBA finance placement"},
  {"id":"mgmt-finance-645","question":"A scheme pays ₹50,000 a year for 5 years, with the FIRST payment at the end of year 4. At 8% a year, what is it worth today?","options":["₹1,46,738","₹1,58,477","₹1,71,155","₹1,99,636"],"answer":1,"explanation":"A 5-payment ordinary annuity valued one period before its first payment sits at the end of year 3: 50,000 × PVIFA(8%,5) = 1,99,636. Discount 3 years: 1,99,636/1.08³ = 1,58,477. Discounting 4 years (₹1,46,738) is the classic off-by-one error.","difficulty":"hard","source":"CA Intermediate FM · MBA finance placement"},
  {"id":"mgmt-finance-646","question":"A ₹10 lakh term loan at 9% a year is repaid in 10 equal year-end instalments of about ₹1,55,820. What is the outstanding principal immediately after the 3rd instalment is paid?","options":["₹7,00,000","₹8,62,436","₹7,84,235","₹8,02,540"],"answer":2,"explanation":"The outstanding balance equals the PV of the 7 remaining instalments: 1,55,820 × PVIFA(9%,7) ≈ ₹7,84,235. Early instalments are mostly interest, so the balance falls far less than the straight-line ₹7 lakh; ₹8,62,436 is the balance after only two instalments.","difficulty":"very-hard","source":"IBPS SO · CA Intermediate FM"},
  {"id":"mgmt-finance-647","question":"Mutually exclusive projects: A has cash flows −₹1,000, +₹800, +₹400 and B has −₹1,000, +₹200, +₹1,060 (years 0, 1, 2). Above what discount rate does A have the higher NPV?","options":["14.8%","13.4%","5.0%","10.0%"],"answer":3,"explanation":"The crossover rate makes the incremental flows (A − B: 0, +600, −660) worth zero: 600/(1+r) = 660/(1+r)², so 1 + r = 1.10 and r = 10%. Above 10% A's earlier cash wins; 14.8% and 13.4% are the projects' own IRRs, not the crossover.","difficulty":"very-hard","source":"CFA Level I · MBA finance placement"},
  {"id":"mgmt-finance-648","question":"A share trades at ₹200; next year's dividend is ₹10 and dividends grow at 8% a year. New shares can be sold at the market price, but flotation costs are 5% of the issue price. What is the cost of NEW equity?","options":["13.00%","13.26%","13.50%","12.75%"],"answer":1,"explanation":"Ke(new) = D₁/[P₀(1 − f)] + g = 10/190 + 8% = 13.26%. 13.00% is the cost of retained earnings, which carries no flotation cost; the gap is why new equity sits above internal equity on the marginal cost schedule.","difficulty":"moderate","source":"CA Intermediate FM · UGC NET Commerce"},
  {"id":"mgmt-finance-649","question":"A firm keeps a target structure of 40% debt and 60% equity. It expects ₹30 crore of retained earnings this year; once these are used up it must issue costlier new equity. At what total capital budget does the marginal cost of capital first rise?","options":["₹18 crore","₹30 crore","₹75 crore","₹50 crore"],"answer":3,"explanation":"Break point = retained earnings ÷ equity weight = 30/0.6 = ₹50 crore; beyond that, each rupee of the budget needs 60 paise of new equity. ₹75 crore wrongly divides by the debt weight and ₹18 crore multiplies by the equity weight.","difficulty":"hard","source":"CA Intermediate FM · UGC NET Commerce"},
  {"id":"mgmt-finance-650","question":"A company pays ₹20 lakh of debenture interest and ₹7 lakh of preference dividend a year; its tax rate is 30%. What is its financial break-even EBIT (the EBIT at which EPS is zero)?","options":["₹30 lakh","₹27 lakh","₹24.9 lakh","₹20 lakh"],"answer":0,"explanation":"Preference dividend is paid out of after-tax profit, so it must be grossed up: FBEP = 20 + 7/(1 − 0.30) = 20 + 10 = ₹30 lakh. ₹27 lakh adds the dividend without grossing up, and ₹24.9 lakh wrongly multiplies by (1 − t).","difficulty":"hard","source":"CA Intermediate FM · MBA finance placement"},
  {"id":"mgmt-finance-651","question":"A new company needs ₹10 crore. Plan X: issue 10 lakh equity shares of ₹100. Plan Y: issue 5 lakh equity shares of ₹100 and ₹5 crore of 10% preference shares. Tax rate 25%, no debt. At what EBIT are the EPS of the two plans equal?","options":["₹1.00 crore","₹0.67 crore","₹1.33 crore","₹2.00 crore"],"answer":2,"explanation":"0.75E/10 = (0.75E − 50)/5 (₹ lakh), so 0.75E = 1.5E − 100 and E = ₹133.3 lakh. ₹1.00 crore treats the preference dividend as if it were tax-deductible like interest; because it is paid after tax, the indifference point is pushed up by 1/(1 − t).","difficulty":"very-hard","source":"CA Intermediate FM · MBA finance placement"},
  {"id":"mgmt-finance-652","question":"A bond (face ₹1,000) pays a 10% annual coupon and has 4 coupons left; the last coupon was paid 3 months ago. Its YTM is 8%. Using full price = value at the last coupon date × (1 + YTM)^(fraction of the period elapsed), what is the CLEAN price?","options":["₹1,066.24","₹1,086.96","₹1,091.24","₹1,061.96"],"answer":3,"explanation":"Value at the last coupon date = ₹1,066.24; full price = 1,066.24 × 1.08^0.25 = ₹1,086.96; accrued interest = 100 × 0.25 = ₹25, so clean price = ₹1,061.96. ₹1,086.96 is the dirty (full) price and ₹1,091.24 adds accrued interest without rolling the value forward.","difficulty":"very-hard","source":"CFA Level I · bank treasury SO"},
  {"id":"mgmt-finance-653","question":"A 10% annual-coupon bond (face ₹1,000) with 5 years to maturity trades at ₹1,080. It is callable at the end of year 2 at ₹1,030. What is its yield to worst?","options":["8.00%","9.26%","7.02%","10.00%"],"answer":2,"explanation":"YTM (held to maturity) ≈ 8.00%; yield to call (₹100, then ₹1,130 at year 2) ≈ 7.02%. For a premium callable bond the call is likely, and yield to worst is the lower of the two, 7.02%. 9.26% is the current yield and 10% the coupon rate.","difficulty":"very-hard","source":"CFA Level I · bank treasury SO"},
  {"id":"mgmt-finance-654","question":"A firm has just paid a dividend of ₹2. Growth is 20% now and is expected to decline linearly to a long-run 6% over 10 years. Using the H-model with a required return of 12%, what is the share worth?","options":["₹82.00","₹58.67","₹35.33","₹56.67"],"answer":1,"explanation":"H-model: V = D₀[(1 + gL) + H(gS − gL)]/(r − gL), with H = half the decline period = 5: 2 × (1.06 + 5 × 0.14)/0.06 = ₹58.67. Using the full 10 years as H gives ₹82.00, and ignoring the high-growth premium gives ₹35.33.","difficulty":"very-hard","source":"CFA Level II · MBA finance placement"},
  {"id":"mgmt-finance-655","question":"A share trades at ₹150. Next year's EPS is ₹10 and the required return on equity is 12%. How much of the price reflects the present value of growth opportunities (PVGO)?","options":["₹66.67","₹83.33","₹70.00","₹56.67"],"answer":0,"explanation":"Without growth the share would be worth E₁/r = 10/0.12 = ₹83.33 (a no-growth perpetuity). PVGO = 150 − 83.33 = ₹66.67. ₹83.33 is the no-growth value itself, not the growth premium.","difficulty":"hard","source":"CFA Level I · MBA finance placement"},
  {"id":"mgmt-finance-656","question":"Fund P returned 14% with a standard deviation of 25%. The market returned 12% with a standard deviation of 20%, and the risk-free rate is 6%. What is the fund's Modigliani (M²) measure, i.e. its return at market risk minus the market return?","options":["2.0%","4.0%","0.4%","−1.6%"],"answer":2,"explanation":"Lever the fund to market risk: Rf + Sharpe × σm = 6% + (8/25) × 20% = 12.4%; M² = 12.4% − 12% = 0.4%. The raw excess over the market (2.0%) ignores that the fund took more risk.","difficulty":"very-hard","source":"CFA Level I · MBA finance placement"},
  {"id":"mgmt-finance-657","question":"An airline will buy 1,00,000 units of jet fuel and hedges with crude-oil futures (10,000 units a contract). Monthly jet-fuel price changes have σ = 3%, futures σ = 4%, and their correlation is 0.8. How many contracts minimise hedge variance?","options":["8","6","10","11"],"answer":1,"explanation":"Minimum-variance hedge ratio h = ρ × σS/σF = 0.8 × 3/4 = 0.6; contracts = 0.6 × 1,00,000/10,000 = 6. Ten contracts is a naive one-to-one hedge, and 11 inverts the volatility ratio.","difficulty":"hard","source":"FRM Part I · bank treasury SO"},
  {"id":"mgmt-finance-658","question":"A bank has sanctioned a ₹60 crore cash-credit limit, of which ₹40 crore is drawn. It applies a 50% credit-conversion factor to the undrawn part. With PD 2% and LGD 45%, what is the expected loss?","options":["₹36 lakh","₹54 lakh","₹90 lakh","₹45 lakh"],"answer":3,"explanation":"EAD = 40 + 0.5 × 20 = ₹50 crore; EL = PD × LGD × EAD = 0.02 × 0.45 × 50 = ₹0.45 crore = ₹45 lakh. ₹36 lakh ignores the undrawn exposure and ₹54 lakh assumes the whole limit is drawn.","difficulty":"hard","source":"IBPS SO · JAIIB/CAIIB"},
  {"id":"mgmt-finance-659","question":"A borrower's PAT is ₹30 lakh, depreciation ₹20 lakh, interest on the term loan ₹10 lakh and the principal instalment due ₹15 lakh. What is the debt-service coverage ratio (DSCR)?","options":["2.40","2.00","6.00","4.00"],"answer":0,"explanation":"DSCR = (PAT + depreciation + interest) ÷ (interest + principal) = 60/25 = 2.40. 2.00 forgets to add back interest in the numerator, and 6.00 is an interest-only coverage that ignores the principal due.","difficulty":"moderate","source":"IBPS SO · JAIIB"},
  {"id":"mgmt-finance-660","question":"A European call on a non-dividend share has a delta of 0.62. If the share price rises by ₹1, approximately how does the European put with the same strike and expiry respond?","options":["Rises by ₹0.38","Falls by ₹0.62","Falls by ₹0.38","Rises by ₹0.62"],"answer":2,"explanation":"From put–call parity (C − P = S − PV(K)), Δput = Δcall − 1 = 0.62 − 1 = −0.38, so the put falls by about ₹0.38. A put's delta is always negative, and −0.62 wrongly reuses the call's delta.","difficulty":"moderate","source":"FRM Part I · bank treasury SO"},
  {"id":"mgmt-finance-661","question":"The spot rate is ₹84 per US dollar. Inflation is expected to be 5% in India and 2% in the US over the next year. Under relative purchasing power parity, what is the expected spot rate in one year?","options":["₹86.52","₹81.60","₹84.00","₹86.47"],"answer":3,"explanation":"Relative PPP: S₁ = S₀ × (1 + πIndia)/(1 + πUS) = 84 × 1.05/1.02 = ₹86.47. ₹86.52 uses the linear approximation 84 × 1.03, and ₹81.60 inverts the ratio as if the rupee would appreciate.","difficulty":"hard","source":"CA Intermediate FM · bank forex SO"},
  {"id":"mgmt-finance-662","question":"Assets A (σ = 20%) and B (σ = 30%) have a correlation of 0.2. What weight in A gives the minimum-variance two-asset portfolio?","options":["73.6%","69.2%","60.0%","80.0%"],"answer":0,"explanation":"wA = (σB² − cov)/(σA² + σB² − 2cov), with cov = 0.2 × 0.2 × 0.3 = 0.012: (0.09 − 0.012)/(0.13 − 0.024) = 73.6%. 69.2% is the zero-correlation answer, and 60% weights by σ instead of variance.","difficulty":"very-hard","source":"CFA Level I · MBA finance placement"},
  {"id":"mgmt-finance-663","question":"A ₹10 lakh project yields ₹3 lakh a year for 5 years; the cost of capital is 10% (PVIFA = 3.7908). By what percentage can the annual inflow fall before the NPV becomes zero?","options":["13.7%","12.1%","45.7%","10.0%"],"answer":1,"explanation":"NPV = 3 × 3.7908 − 10 = ₹1.372 lakh. The inflow can fall by NPV ÷ PV of inflows = 1.372/11.372 = 12.1%. Dividing by the outlay (13.7%) measures sensitivity of the wrong base.","difficulty":"hard","source":"CA Intermediate FM · MBA finance placement"},
  {"id":"mgmt-finance-664","question":"A project costs ₹100 lakh and is expected to return ₹60 lakh at the end of each of 2 years. Certainty-equivalent coefficients are 0.9 for year 1 and 0.8 for year 2, and the risk-free rate is 6%. What is the NPV?","options":["+₹10.00 lakh","−₹6.66 lakh","+₹2.00 lakh","−₹6.34 lakh"],"answer":3,"explanation":"Certain flows are 54 and 48, discounted at the risk-free rate: 54/1.06 + 48/1.06² − 100 = −₹6.34 lakh. Discounting the uncertain ₹60 lakh at 6% gives +₹10 lakh, double-counting nothing for risk.","difficulty":"hard","source":"CA Intermediate FM · UGC NET Commerce"},
  {"id":"mgmt-finance-665","question":"A debt-free company trades at a P/E of 20 and holds idle cash earning 6% before tax (tax rate 25%). It uses part of that cash to buy back shares at the market price. What happens to EPS?","options":["EPS falls, because the cash's after-tax yield (4.5%) is below the earnings yield (5%)","EPS is unchanged, because a buyback at the market price never changes EPS","EPS rises, because the cash's after-tax yield (4.5%) is below the earnings yield (5%)","EPS rises only if the pre-tax yield on cash exceeds the 5% earnings yield"],"answer":2,"explanation":"Earnings lost per rupee spent = 4.5%, earnings per rupee of shares retired = 1/20 = 5%; since the earnings given up are smaller than the earnings of the shares cancelled, EPS rises. EPS falls only when the after-tax yield on cash exceeds the earnings yield.","difficulty":"moderate","source":"CFA Level I · MBA finance placement"},
  {"id":"mgmt-finance-666","question":"10% preference shares (face ₹100) are issued, net of costs, at ₹95 and will be redeemed at ₹105 after 5 years. Using the approximation formula, what is the cost of preference capital?","options":["10.53%","12.00%","11.43%","12.63%"],"answer":1,"explanation":"Kp ≈ [D + (RV − NP)/n] ÷ [(RV + NP)/2] = [10 + 10/5] ÷ 100 = 12%. 10.53% ignores redemption, and 12.63% divides by the net proceeds instead of the average investment.","difficulty":"hard","source":"CA Intermediate FM · UGC NET Commerce"},
  {"id":"mgmt-finance-667","question":"A division has EBIT of ₹120 crore, interest of ₹30 crore, a 25% tax rate, invested capital of ₹600 crore and a WACC of 12%. What is its economic value added (EVA)?","options":["−₹4.5 crore","₹48 crore","₹18 crore","₹0"],"answer":2,"explanation":"EVA = NOPAT − WACC × capital = 120 × 0.75 − 0.12 × 600 = 90 − 72 = ₹18 crore. Using PAT (after interest) double-charges debt, since interest is already in the WACC charge; that gives −₹4.5 crore.","difficulty":"hard","source":"CA Intermediate FM · MBA finance placement"},
  {"id":"mgmt-finance-668","question":"A firm's credit sales are ₹100 lakh on 30-day terms. Extending terms to 60 days would raise sales to ₹120 lakh. Variable cost is 75% of sales, bad debts on the extra sales would be 3%, and the required return on funds tied up in receivables (valued at variable cost) is 15%. Using a 360-day year, what is the net annual gain from the change?","options":["₹2.65 lakh","₹3.09 lakh","₹3.69 lakh","₹4.03 lakh"],"answer":1,"explanation":"Extra contribution 5.00 − bad debts 0.60 − carrying cost of extra receivables at cost [(120 × 0.75 × 60/360) − (100 × 0.75 × 30/360)] × 15% = 1.3125 gives ₹3.09 lakh. Valuing receivables at sales price gives ₹2.65 lakh, and forgetting bad debts gives ₹3.69 lakh.","difficulty":"very-hard","source":"CA Intermediate FM · MBA finance placement"},
  {"id":"mgmt-finance-669","question":"Annual demand is 20,000 units at ₹50 each; ordering cost is ₹400 an order and holding cost 20% of the unit price a year. The supplier offers 2% off the price on orders of 4,000 units or more. What is the net annual saving from ordering 4,000 units instead of the EOQ?","options":["₹20,000","₹10,649","₹6,725","₹11,049"],"answer":3,"explanation":"EOQ ≈ 1,265 units, total cost ₹10,12,649. At 4,000 units: purchases 9,80,000 + ordering 2,000 + holding 2,000 × ₹9.80 = ₹10,01,600, so saving = ₹11,049. Keeping holding cost at ₹10 gives ₹10,649; ignoring the fall in ordering cost gives ₹6,725.","difficulty":"very-hard","source":"CA Intermediate · MBA operations-finance placement"},
  {"id":"mgmt-finance-670","question":"A company's annual credit sales are ₹730 crore. Tighter collections cut its days sales outstanding from 50 days to 40 days. If it funds working capital at 9% a year, what is the annual interest saving (365-day year)?","options":["₹1.80 crore","₹20.00 crore","₹3.60 crore","₹0.90 crore"],"answer":0,"explanation":"Daily sales = 730/365 = ₹2 crore; 10 fewer days frees ₹20 crore of receivables, which saves 20 × 9% = ₹1.80 crore of interest a year. ₹20 crore is the one-time cash release, not the annual saving.","difficulty":"moderate","source":"Bank SO · MBA finance placement"},
  {"id":"mgmt-finance-671","question":"A share is about to pay a ₹10 dividend. The marginal investor pays 30% tax on dividends and 10% on capital gains. Under the Elton–Gruber tax-clientele argument, by how much should the share price fall on the ex-dividend date?","options":["₹10.00","₹7.00","₹7.78","₹9.00"],"answer":2,"explanation":"Indifference requires ΔP(1 − tg) = D(1 − td), so ΔP = 10 × 0.70/0.90 = ₹7.78. Without taxes the drop would equal the dividend; ₹7.00 ignores the tax saved on the smaller capital gain.","difficulty":"very-hard","source":"CFA Level II · MBA finance placement"},
  {"id":"mgmt-finance-672","question":"A company with ₹10 face-value shares is choosing between a 1:1 bonus issue and a 2-for-1 stock split. Which effect occurs under the bonus issue but NOT under the split?","options":["Number of shares doubles","Market price per share roughly halves","Reserves are transferred to share capital","Total shareholders' equity stays unchanged"],"answer":2,"explanation":"A bonus issue capitalises reserves, raising paid-up capital while face value stays ₹10; a split simply halves face value to ₹5 with no transfer. Both double the share count, roughly halve the price and leave total equity unchanged.","difficulty":"moderate","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-finance-673","question":"A firm worth ₹1,000 crore has 10 crore shares at ₹100 and no debt. It spends ₹250 crore of its cash buying back 2 crore shares through a tender offer at ₹125. Assuming the remaining assets are valued fairly, what is the post-buyback price per share?","options":["₹100.00","₹93.75","₹106.25","₹125.00"],"answer":1,"explanation":"Remaining value = 1,000 − 250 = ₹750 crore over 8 crore shares = ₹93.75. Paying above fair value transfers ₹6.25 a share from those who do not tender to those who do; a buyback at ₹100 would have left the price at ₹100.","difficulty":"hard","source":"CFA Level I · MBA finance placement"},
  {"id":"mgmt-finance-674","question":"A treasury holds a bond position with a market value of ₹25 crore and a modified duration of 4.2. What is the position's price value of a basis point (PV01)?","options":["₹1,05,000","₹10,500","₹10,50,000","₹42,000"],"answer":0,"explanation":"PV01 = market value × modified duration × 0.0001 = 25,00,00,000 × 4.2 × 0.0001 = ₹1,05,000. ₹10,50,000 would be the change for a 10-basis-point move.","difficulty":"moderate","source":"Bank treasury SO · FRM Part I"},
  {"id":"mgmt-finance-675","question":"A non-dividend share trades at ₹100. A one-year European call has a strike of ₹95, and the risk-free rate is 8% a year with annual compounding. What is the lowest price the call can trade at without an arbitrage?","options":["₹5.00","₹12.60","₹4.63","₹12.04"],"answer":3,"explanation":"Lower bound = S − K/(1 + r)ᵀ = 100 − 95/1.08 = ₹12.04. Intrinsic value (₹5) understates the bound because a European call holder pays the strike only later; ₹12.60 wrongly discounts by multiplying by (1 − r).","difficulty":"hard","source":"FRM Part I · bank treasury SO"},
  {"id":"mgmt-finance-676","question":"A trader holding stock sells futures at ₹1,520 when the spot is ₹1,500. When she closes out, the spot is ₹1,400 and the futures price ₹1,410. She sells the stock in the spot market. What effective price does she realise?","options":["₹1,500","₹1,520","₹1,510","₹1,530"],"answer":2,"explanation":"Effective price = spot at close + futures gain = 1,400 + (1,520 − 1,410) = ₹1,510, which equals the initial futures price plus the final basis (1,400 − 1,410 = −10). Locking ₹1,520 would need the basis to be zero at close-out.","difficulty":"hard","source":"FRM Part I · CA Intermediate"},
  {"id":"mgmt-finance-677","question":"An Indian exporter will receive $2,00,000 in 6 months. Spot is ₹84/$; it can borrow dollars at 5% a year and invest rupees at 7% a year (simple interest for the half-year). Using a money-market hedge, what rupee amount per dollar does it lock in for month 6?","options":["₹84.82","₹84.84","₹85.68","₹83.18"],"answer":0,"explanation":"Borrow 2,00,000/1.025 = $1,95,122, convert at ₹84, invest at 3.5% for 6 months: ₹1,69,63,902, i.e. ₹84.82 per dollar. Using annual rates for a half-year or skipping the discounting of the dollar borrowing gives the other figures.","difficulty":"very-hard","source":"CA Intermediate FM · bank forex SO"},
  {"id":"mgmt-finance-678","question":"A bank has credit risk-weighted assets of ₹8,000 crore, a market-risk capital charge of ₹40 crore and an operational-risk capital charge of ₹60 crore. Its total capital is ₹1,000 crore. If capital charges are converted to RWA by multiplying by 1/0.09 (the assumed minimum ratio), what is its CRAR?","options":["12.35%","12.50%","10.81%","10.98%"],"answer":3,"explanation":"RWA = 8,000 + (40 + 60)/0.09 = ₹9,111 crore; CRAR = 1,000/9,111 = 10.98%. Adding the charges as if they were RWA gives 12.35%, and converting at 12.5× (an 8% minimum) gives 10.81%.","difficulty":"very-hard","source":"IBPS SO · JAIIB/CAIIB"},
  {"id":"mgmt-finance-679","question":"A 182-day commercial paper with face value ₹100 is issued at ₹96. What is its money-market yield on the issue price (simple annualisation, 365-day year)?","options":["8.02%","8.36%","8.53%","4.17%"],"answer":1,"explanation":"Yield = (100 − 96)/96 × 365/182 = 8.36%. 8.02% is the discount yield on face value, 8.53% the compounded effective annual yield and 4.17% the unannualised holding-period return.","difficulty":"hard","source":"Bank treasury SO · CA Intermediate"},
  {"id":"mgmt-finance-680","question":"Acquirer A earns ₹200 crore on 50 crore shares; target T earns ₹50 crore on 20 crore shares. The merger will add ₹10 crore of earnings. What is the highest share-exchange ratio (A shares per T share) that keeps A's EPS from falling?","options":["0.625","0.800","1.333","0.750"],"answer":3,"explanation":"Combined earnings ₹260 crore must support EPS ₹4, so total shares ≤ 65 crore; A can issue 15 crore new shares for 20 crore T shares, a ratio of 0.75. Ignoring the synergy gives 0.625.","difficulty":"hard","source":"CA Intermediate FM · MBA finance placement"},
  {"id":"mgmt-finance-681","question":"A company's enterprise value is ₹1,500 crore. It has debt of ₹400 crore, cash of ₹100 crore, non-controlling interest of ₹50 crore and preference capital of ₹50 crore, with 10 crore equity shares. What is the value per equity share?","options":["₹110","₹120","₹130","₹100"],"answer":0,"explanation":"Equity = EV − debt + cash − NCI − preference = 1,500 − 400 + 100 − 50 − 50 = ₹1,100 crore, i.e. ₹110 a share. Leaving out NCI and preference gives ₹120; adding NCI instead of deducting it gives ₹130.","difficulty":"hard","source":"Big 4 valuation · MBA finance placement"},
  {"id":"mgmt-finance-682","question":"A mature firm's NOPAT next year will be ₹100 crore. It will grow at 5% a year forever, earning a 15% return on new invested capital; its WACC is 10%. What is its value today (terminal-value formula)?","options":["₹2,000 crore","₹1,333 crore","₹1,000 crore","₹2,100 crore"],"answer":1,"explanation":"Reinvestment rate = g/ROIC = 5/15 = 1/3, so FCFF = 100 × 2/3 = 66.7 and value = 66.7/(0.10 − 0.05) = ₹1,333 crore. Using NOPAT as if no reinvestment were needed gives ₹2,000 crore; with ROIC equal to WACC the value would be ₹1,000 crore.","difficulty":"very-hard","source":"CFA Level II · Big 4 valuation"},
  {"id":"mgmt-finance-683","question":"A fund earned 12% against a minimum acceptable return of 4%; its downside deviation (below 4%) is 10% and its total standard deviation is 16%. What is its Sortino ratio?","options":["0.50","0.75","1.20","0.80"],"answer":3,"explanation":"Sortino = (R − MAR)/downside deviation = (12 − 4)/10 = 0.80. Dividing by the total standard deviation (0.50) penalises upside volatility too, which is exactly what Sortino avoids.","difficulty":"moderate","source":"CFA Level I · MBA finance placement"},
  {"id":"mgmt-finance-684","question":"A project costs ₹110 crore today. In a year it will be worth ₹180 crore or ₹60 crore with equal probability, and at that point it can be abandoned for a salvage value of ₹90 crore. At a 10% discount rate, what is the NPV including the abandonment option?","options":["₹12.73 crore","−₹0.91 crore","₹13.64 crore","₹25.00 crore"],"answer":0,"explanation":"With the option, the bad state is worth max(60, 90) = 90: (0.5 × 180 + 0.5 × 90)/1.1 − 110 = ₹12.73 crore. Without it the NPV is −₹0.91 crore; ₹13.64 crore is the value of the option itself.","difficulty":"very-hard","source":"CFA Level II · MBA finance placement"},
  {"id":"mgmt-finance-685","question":"A ₹10 lakh machine with a ₹2 lakh salvage value and a 4-year life earns an average annual profit after depreciation and tax of ₹1.5 lakh. What is its accounting rate of return on AVERAGE investment?","options":["15%","30%","25%","18.75%"],"answer":2,"explanation":"Average investment = (10 + 2)/2 = ₹6 lakh, so ARR = 1.5/6 = 25%. 15% uses initial investment and 30% ignores the salvage value in the average.","difficulty":"moderate","source":"UGC NET Commerce · CA Intermediate"},
  {"id":"mgmt-finance-686","question":"A firm's debt has a market value of ₹38 crore (book ₹40 crore) with a pre-tax YTM of 10%; its equity has a market value of ₹62 crore (book ₹30 crore) and a cost of 14%. The tax rate is 25%. What is its WACC?","options":["10.29%","12.48%","11.53%","10.75%"],"answer":2,"explanation":"Market weights: 0.62 × 14% + 0.38 × 10% × 0.75 = 8.68% + 2.85% = 11.53%. Book weights give 10.29%, and forgetting the debt tax shield gives 12.48%.","difficulty":"very-hard","source":"CA Intermediate FM · MBA finance placement"},
  {"id":"mgmt-finance-687","question":"Under the RBI's marginal cost of funds based lending rate (MCLR) framework, which of these is NOT a component of the MCLR itself?","options":["Marginal cost of borrowed funds","Negative carry on CRR balances","Operating costs of the bank","Borrower's credit risk premium"],"answer":3,"explanation":"MCLR is built from the marginal cost of funds, the negative carry on CRR, operating costs and a tenor premium. The borrower's credit-risk premium is part of the spread a bank adds over the MCLR when pricing a loan.","difficulty":"hard","source":"IBPS SO · RBI Grade B"},
  {"id":"mgmt-finance-688","question":"Under the RBI's framework for early recognition of stress, a term loan's principal has been overdue for 75 days. How is the account classified?","options":["SMA-1","SMA-2","Sub-standard NPA","SMA-0"],"answer":1,"explanation":"SMA-0 covers overdues up to 30 days, SMA-1 31–60 days and SMA-2 61–90 days; it becomes an NPA only when overdue for more than 90 days. At 75 days the account is SMA-2.","difficulty":"hard","source":"IBPS SO · JAIIB"},
  {"id":"mgmt-finance-689","question":"Spot is ₹80/$ and the 1-year forward is ₹82/$. One-year interest rates are 6% in India and 2% in the US. An arbitrageur borrows $1 for a year. How much riskless profit does she make per dollar borrowed?","options":["₹1.14","₹2.00","₹0.00","₹1.16"],"answer":3,"explanation":"Convert $1 to ₹80, invest at 6% to get ₹84.80, buy the $1.02 owed forward at ₹82 for ₹83.64: profit ₹1.16. The parity forward is ₹83.14, so the actual forward makes the dollar too cheap; ₹1.14 is the forward gap per dollar, not per dollar borrowed with interest.","difficulty":"very-hard","source":"CA Intermediate FM · bank forex SO"},
  {"id":"mgmt-finance-690","question":"₹10 lakh is invested for 10 years in a fund earning 12% a year before costs. Plan R charges 1.5% a year, Plan D 0.5%, deducted from the return each year. How much more does Plan D have at the end?","options":["₹1.00 lakh","₹2.56 lakh","₹1.05 lakh","₹2.97 lakh"],"answer":1,"explanation":"Plan D: 10 × 1.115¹⁰ = ₹29.70 lakh; Plan R: 10 × 1.105¹⁰ = ₹27.14 lakh; gap = ₹2.56 lakh. The 1% fee difference compounds on a growing base, so it costs far more than 1% × 10 years × ₹10 lakh.","difficulty":"hard","source":"NISM Mutual Fund · MBA finance placement"},
  {"id":"mgmt-finance-691","question":"In a public issue through ASBA (Application Supported by Blocked Amount), what happens to the applicant's money until allotment?","options":["It is debited and held in the issuer's escrow account","It is transferred to the lead manager's pool account","It stays in the applicant's account, blocked by the bank","It is debited and parked with the registrar to the issue"],"answer":2,"explanation":"Under ASBA the self-certified syndicate bank blocks the application amount in the investor's own account; it is debited only for the shares actually allotted, and the rest is unblocked. The money keeps earning interest meanwhile.","difficulty":"moderate","source":"NISM · bank SO · UGC NET Commerce"},
  {"id":"mgmt-finance-692","question":"A share trades at ₹250 and has JUST paid a dividend of ₹10. Investors require 12%. What constant dividend growth rate does the market price imply?","options":["8.00%","7.69%","4.00%","7.40%"],"answer":1,"explanation":"250 = 10(1 + g)/(0.12 − g) gives 30 − 250g = 10 + 10g, so g = 20/260 = 7.69%. Treating ₹10 as next year's dividend gives 8.00%; 4.00% is the dividend yield subtracted from 12% without grossing up.","difficulty":"hard","source":"CA Intermediate FM · MBA finance placement"},
  {"id":"mgmt-finance-693","question":"A firm pays out 40% of earnings, earns an ROE of 15% on retained profits forever, and its shareholders require 12%. What is its justified TRAILING P/E?","options":["13.33","20.00","14.53","3.33"],"answer":2,"explanation":"g = ROE × retention = 15% × 0.6 = 9%. Leading P/E = payout/(r − g) = 0.4/0.03 = 13.33; trailing P/E = leading × (1 + g) = 14.53. 20.00 wrongly uses the retention ratio as the payout.","difficulty":"very-hard","source":"CFA Level I · MBA finance placement"},
  {"id":"mgmt-finance-694","question":"A 3-year bond (face ₹1,000) pays a 9% coupon semi-annually. Its yield to maturity is 10% a year, quoted on a semi-annual basis. What is its price?","options":["₹975.13","₹1,000.00","₹1,025.38","₹974.62"],"answer":3,"explanation":"Discount six ₹45 coupons and ₹1,000 at 5% a half-year: 45 × PVIFA(5%,6) + 1,000/1.05⁶ = ₹974.62. ₹975.13 is the annual-coupon valuation; the price must be below par because the yield exceeds the coupon.","difficulty":"hard","source":"Bank treasury SO · CFA Level I"},
  {"id":"mgmt-finance-695","question":"An investor buys a 2-year, 10% annual-coupon bond at par (₹1,000) and holds it to maturity. The first coupon can be reinvested only at 6%. What is the realised compound annual yield?","options":["10.00%","9.82%","8.00%","9.66%"],"answer":1,"explanation":"Terminal wealth = 100 × 1.06 + 1,100 = ₹1,206; realised yield = (1,206/1,000)^½ − 1 = 9.82%. YTM (10%) is earned only if coupons are reinvested at the YTM itself, which is the reinvestment risk.","difficulty":"very-hard","source":"CFA Level I · bank treasury SO"},
  {"id":"mgmt-finance-696","question":"A borrower buys an interest-rate cap at 8% on a ₹50 crore floating loan with 6-monthly resets (period = half a year). At one reset, MIBOR is 9.2%. What does the cap pay for that period?","options":["₹60 lakh","₹15 lakh","₹30 lakh","₹46 lakh"],"answer":2,"explanation":"Cap payoff = notional × max(MIBOR − cap rate, 0) × period = 50 crore × 1.2% × 0.5 = ₹30 lakh. ₹60 lakh forgets the half-year accrual, and ₹46 lakh applies the full 9.2% instead of the excess over the cap.","difficulty":"hard","source":"FRM Part I · bank treasury SO"},
  {"id":"mgmt-finance-697","question":"Under the Net Operating Income approach, a firm has EBIT of ₹30 lakh, an overall capitalisation rate of 12% and ₹100 lakh of 9% debt (no taxes). What is its cost of equity?","options":["12.0%","14.0%","21.0%","12.6%"],"answer":1,"explanation":"Firm value = EBIT/Ko = 250; equity = 250 − 100 = 150; Ke = (30 − 9)/150 = 14%. Under NOI the overall rate is fixed, so Ke rises as cheap debt is added.","difficulty":"hard","source":"CA Intermediate FM · UGC NET Commerce"},
  {"id":"mgmt-finance-698","question":"A company issues 5-year 11% debentures; net proceeds are ₹96 per ₹100 and redemption is at ₹104. The tax rate is 30%. Using the approximation formula, what is the after-tax cost of debt?","options":["8.82%","8.02%","9.30%","12.60%"],"answer":2,"explanation":"Kd ≈ [I(1 − t) + (RV − NP)/n] ÷ [(RV + NP)/2] = [7.7 + 1.6]/100 = 9.30%. 8.02% ignores the redemption premium and discount, and 8.82% wrongly applies the tax shield to the amortised premium as well.","difficulty":"hard","source":"CA Intermediate FM · UGC NET Commerce"},
  {"id":"mgmt-finance-699","question":"A firm finances all its fixed assets and part of its permanent current assets with long-term funds, and funds the rest of its permanent current assets and all temporary ones with short-term borrowing. Which working-capital financing policy is this?","options":["Aggressive","Matching (hedging)","Conservative","Zero working capital"],"answer":0,"explanation":"Using short-term funds for part of the permanent (core) current assets is the aggressive policy: cheaper but exposed to refinancing risk. The matching policy funds all permanent assets long-term; the conservative policy also funds part of the temporary assets long-term.","difficulty":"moderate","source":"CA Intermediate FM · UGC NET Commerce"},
  {"id":"mgmt-finance-700","question":"A bank's cash-credit limit is ₹60 lakh. The borrower has paid stock of ₹50 lakh (margin 25%) after deducting creditors of ₹10 lakh from stock of ₹60 lakh, plus receivables under 90 days of ₹40 lakh (margin 40%). What is the drawing power available?","options":["₹60 lakh","₹54 lakh","₹48 lakh","₹61.5 lakh"],"answer":0,"explanation":"DP = 50 × 0.75 + 40 × 0.60 = 37.5 + 24 = ₹61.5 lakh, but drawings are capped at the lower of DP and the sanctioned limit, so ₹60 lakh is available. ₹61.5 lakh ignores the cap, ₹54 lakh deducts creditors a second time, and ₹48 lakh applies the 40% margin to everything.","difficulty":"very-hard","source":"IBPS SO · JAIIB"},
  {"id":"mgmt-finance-701","question":"A borrower's current assets are ₹400 lakh and current liabilities other than bank borrowing are ₹100 lakh. Under the Tandon Committee's second method of lending, what is the maximum permissible bank finance?","options":["₹225 lakh","₹300 lakh","₹175 lakh","₹200 lakh"],"answer":3,"explanation":"Method II: MPBF = 75% of current assets − other current liabilities = 300 − 100 = ₹200 lakh, so the borrower funds 25% of total current assets long-term. ₹225 lakh is Method I (75% of the working-capital gap).","difficulty":"hard","source":"IBPS SO · JAIIB"},
  {"id":"mgmt-finance-702","question":"A 2-year bond pays a 10% annual coupon and trades at par (YTM 10%). What is its Macaulay duration?","options":["1.909 years","2.000 years","1.736 years","1.500 years"],"answer":0,"explanation":"PV weights: 100/1.1 = 90.91 at year 1 and 1,100/1.21 = 909.09 at year 2, so D = (90.91 + 2 × 909.09)/1,000 = 1.909 years. 1.736 is the modified duration (1.909/1.1); only a zero-coupon bond has duration equal to maturity.","difficulty":"hard","source":"Bank treasury SO · CFA Level I"},
  {"id":"mgmt-finance-703","question":"A bank SELLS a 6×12 FRA on ₹20 crore at 7.5% a year. At settlement the 6-month reference rate is 6.5% (period = half a year), and settlement is paid at the start of the period, discounted at the reference rate. What happens?","options":["The bank pays ₹9,68,523","The bank receives ₹10,00,000","The bank receives ₹9,63,855","The bank receives ₹9,68,523"],"answer":3,"explanation":"The FRA seller gains when rates fall: 20 crore × 1% × 0.5 = ₹10,00,000 due at the end of the period, discounted at 6.5% for half a year (÷ 1.0325) = ₹9,68,523 received. Discounting at the FRA rate gives ₹9,63,855.","difficulty":"very-hard","source":"FRM Part I · bank treasury SO"},
  {"id":"mgmt-finance-704","question":"A Ludhiana bicycle maker buys and sells only in rupees, but its profits fall when the rupee appreciates because imported bicycles become cheaper. What kind of currency exposure is this?","options":["Transaction (contractual) exposure","Translation (accounting) exposure","Economic (operating) exposure","Settlement exposure"],"answer":2,"explanation":"With no foreign-currency receivables, payables or subsidiaries, the firm has no transaction or translation exposure; its competitive position still depends on the exchange rate, which is economic exposure.","difficulty":"moderate","source":"CA Intermediate FM · bank forex SO"},
  {"id":"mgmt-finance-705","question":"A company's book equity is ₹400 crore and it will earn a constant ₹60 crore net income forever, paying out everything. Its cost of equity is 12%. Using the residual-income model, what is equity worth?","options":["₹400 crore","₹600 crore","₹500 crore","₹512 crore"],"answer":2,"explanation":"Residual income = 60 − 12% × 400 = ₹12 crore a year; value = 400 + 12/0.12 = ₹500 crore (same as 60/0.12). ₹600 crore wrongly adds the capitalised net income to book value instead of the capitalised residual income.","difficulty":"hard","source":"CFA Level II · Big 4 valuation"},
  {"id":"mgmt-finance-706","question":"Which statement about Value-at-Risk (VaR) and Expected Shortfall (ES) at the same confidence level is correct?","options":["ES is always smaller than VaR because it averages all outcomes","VaR is subadditive for every distribution; ES is not","Both measures ignore losses beyond the confidence level","ES averages losses beyond VaR and is subadditive"],"answer":3,"explanation":"ES is the average loss in the tail beyond VaR, so it is at least as large as VaR and reflects tail severity. ES is a coherent (subadditive) measure; VaR can violate subadditivity, so diversification can appear to raise VaR.","difficulty":"hard","source":"FRM Part I · bank risk SO"},
  {"id":"mgmt-finance-707","question":"A portfolio holds three stocks in equal weights. Each has σ = 20% and every pair has a correlation of 0.5. What is the portfolio's standard deviation?","options":["20.00%","16.33%","11.55%","14.14%"],"answer":1,"explanation":"σp² = (1/3)σ² + (2/3)ρσ² = 0.04 × (1/3 + 1/3) = 0.0267, so σp = 16.33%. 11.55% assumes zero correlation, and 20% assumes perfect correlation.","difficulty":"very-hard","source":"CFA Level I · MBA finance placement"},
  {"id":"mgmt-finance-708","question":"An investor puts ₹12,000 into a fund each month for three months at NAVs of ₹20, ₹24 and ₹30. What is her average cost per unit?","options":["₹24.00","₹24.67","₹25.00","₹23.33"],"answer":0,"explanation":"Units = 600 + 500 + 400 = 1,500 for ₹36,000, so cost = ₹24.00 (the harmonic mean of the NAVs). It is below the simple average NAV of ₹24.67 because a fixed sum buys more units when NAV is low.","difficulty":"moderate","source":"NISM Mutual Fund · bank SO"},
  {"id":"mgmt-finance-709","question":"A project needs ₹10 lakh of working capital at the start, fully recovered at the end of year 5. At 10%, what does this working capital cost the project in NPV terms?","options":["₹0, since it is fully recovered","₹10.00 lakh","₹6.21 lakh","₹3.79 lakh"],"answer":3,"explanation":"NPV effect = −10 + 10/1.1⁵ = −10 + 6.21 = −₹3.79 lakh. Recovery does not cancel the outlay because the money is tied up for 5 years; ₹6.21 lakh is the PV of the recovery, not the cost.","difficulty":"hard","source":"CA Intermediate FM · MBA finance placement"},
  {"id":"mgmt-finance-710","question":"An asset costing ₹100 lakh is added to a block depreciated at 25% a year on the written-down value forever. The tax rate is 25% and the discount rate 10%. Ignoring timing conventions within the year, what is the PV of the depreciation tax shields (PV = C × d × t/(d + k))?","options":["₹17.86 lakh","₹25.00 lakh","₹6.25 lakh","₹15.63 lakh"],"answer":0,"explanation":"PV = 100 × 0.25 × 0.25/(0.25 + 0.10) = ₹17.86 lakh. ₹25 lakh is the undiscounted total of the shields; ₹6.25 lakh is only the first year's shield.","difficulty":"very-hard","source":"CA Final SFM · MBA finance placement"},
  {"id":"mgmt-finance-711","question":"An investment of ₹500 crore yields ₹60 crore at the end of year 1, growing at 3% a year forever. What is its IRR?","options":["12.0%","15.0%","9.0%","15.4%"],"answer":1,"explanation":"For a growing perpetuity, price = C₁/(IRR − g), so IRR = 60/500 + 3% = 15%. 12% ignores growth, and 15.4% grows the first cash flow once more.","difficulty":"moderate","source":"CFA Level I · MBA finance placement"},
  {"id":"mgmt-finance-712","question":"A ₹12 lakh loan at 12% a year (1% a month) is repaid by 60 monthly EMIs of about ₹26,693. How much of the 13th EMI is interest?","options":["₹12,000","₹9,600","₹10,137","₹26,693"],"answer":2,"explanation":"Balance after 12 EMIs = 12,00,000 × 1.01¹² − 26,693 × FVIFA(1%,12) ≈ ₹10,13,652; interest in month 13 = 1% of that ≈ ₹10,137. ₹9,600 assumes equal principal repayment each month.","difficulty":"very-hard","source":"IBPS SO · CA Intermediate"},
  {"id":"mgmt-finance-713","question":"A deposit pays 9% a year; the investor pays 30% tax on interest and inflation is 5%. What is her exact after-tax real return?","options":["4.00%","2.80%","1.30%","1.24%"],"answer":3,"explanation":"After-tax nominal = 9% × 0.7 = 6.3%; real = 1.063/1.05 − 1 = 1.24%. 2.80% taxes only the real part (tax is levied on the full nominal interest), and 1.30% is the linear approximation.","difficulty":"hard","source":"CFA Level I · bank SO"},
  {"id":"mgmt-finance-714","question":"Under Miller's model with personal taxes, the corporate tax rate is 25%, the personal tax on equity income 10% and on interest income 30%. What is the gain in firm value from ₹100 crore of permanent debt?","options":["₹25.00 crore","₹0","₹41.67 crore","₹3.57 crore"],"answer":3,"explanation":"Gain = [1 − (1 − tc)(1 − te)/(1 − td)] × D = [1 − 0.75 × 0.90/0.70] × 100 = ₹3.57 crore. The MM-with-corporate-tax answer (tc × D = ₹25 crore) ignores that investors pay more tax on interest than on equity income. Swapping te and td in the formula gives ₹41.67 crore.","difficulty":"very-hard","source":"CA Final SFM · MBA finance placement"},
];

export default questions;
